def env_flag(*names: str, default: bool = False) -> bool:
    for name in names:
        value = os.getenv(name)
        if value is None:
            continue
        parsed = parse_env_bool(value)
        if parsed is not None:
            return parsed
    return default


def env_flag_value(*names: str) -> bool | None:
    for name in names:
        value = os.getenv(name)
        if value is None:
            continue
        parsed = parse_env_bool(value)
        if parsed is not None:
            return parsed
    return None


def parse_env_bool(value: str) -> bool | None:
    normalized = value.strip().lower()
    if normalized in TRUE_ENV_VALUES:
        return True
    if normalized in FALSE_ENV_VALUES:
        return False
    return None


def env_custom_theme_name(default: str = DEFAULT_CUSTOM_THEME_NAME) -> str:
    name = os.getenv("AGENT_PBX_TUI_CUSTOM_THEME_NAME", default).strip()
    return name or default


def env_color(name: str, default: str) -> str:
    value = os.getenv(name, "").strip()
    if not value:
        return default
    try:
        Color.parse(value)
    except ColorParseError:
        return default
    return value


def env_custom_palette() -> dict[str, str]:
    return {
        key: env_color(
            f"AGENT_PBX_TUI_CUSTOM_{key.upper()}",
            DEFAULT_CUSTOM_PALETTE[key],
        )
        for key in THEME_KEYS
    }


def is_custom_theme_selector(theme: str, custom_name: str) -> bool:
    normalized = theme.strip().lower()
    return normalized in {
        custom_name.strip().lower(),
        DEFAULT_CUSTOM_THEME_NAME,
        "leet",
    }


def is_minimal_theme_selector(theme: str) -> bool:
    normalized = theme.strip().lower().replace("_", "-")
    return normalized in {
        MINIMAL_TUI_THEME,
        "basic",
        "black-white",
        "blackwhite",
        "bw",
        "compat",
        "compatible",
        "mono",
        "monochrome",
    }


def is_default_theme_selector(theme: str) -> bool:
    normalized = theme.strip().lower().replace("_", "-")
    return normalized in {
        "",
        "default",
        DEFAULT_TUI_THEME,
        "github",
        "github dark",
        "github-dark",
    }


def env_theme(
    default: str = DEFAULT_TUI_THEME, custom_name: str | None = None
) -> str:
    override = env_theme_value(custom_name=custom_name)
    return override or default


def env_theme_value(custom_name: str | None = None) -> str | None:
    resolved_custom_name = custom_name or env_custom_theme_name()
    if env_flag_value("AGENT_PBX_TUI_1337"):
        return resolved_custom_name
    if "AGENT_PBX_TUI_THEME" not in os.environ:
        return None
    theme = os.getenv("AGENT_PBX_TUI_THEME", "").strip().lower()
    if is_custom_theme_selector(theme, resolved_custom_name):
        return resolved_custom_name
    if is_minimal_theme_selector(theme):
        return MINIMAL_TUI_THEME
    if is_default_theme_selector(theme):
        return DEFAULT_TUI_THEME
    return None


def resolve_layout(layout_name: str) -> str:
    normalized = layout_name.strip().lower().replace("_", "-")
    if normalized in {"", "default", "auto", "adaptive", "responsive"}:
        return ADAPTIVE_TUI_LAYOUT
    if normalized in {"split", "wide", "desktop"}:
        return SPLIT_TUI_LAYOUT
    if normalized in {"compact", "mobile", "small", "single", "single-pane"}:
        return COMPACT_TUI_LAYOUT
    if normalized in {"tiny", "pocket", "pocketchip", "mini"}:
        return TINY_TUI_LAYOUT
    return DEFAULT_TUI_LAYOUT


def env_layout_value() -> str | None:
    if "AGENT_PBX_TUI_LAYOUT" not in os.environ:
        return None
    return resolve_layout(os.getenv("AGENT_PBX_TUI_LAYOUT", ""))


def clamp_split_percent(value: int) -> int:
    return max(MIN_SPLIT_PERCENT, min(MAX_SPLIT_PERCENT, value))


def operator_panel_height(left_height: int) -> int:
    if left_height <= 0:
        return OPERATOR_PANEL_MIN_HEIGHT
    minimum = max(OPERATOR_PANEL_MIN_HEIGHT, round(left_height * OPERATOR_PANEL_MIN_RATIO))
    maximum = max(minimum, round(left_height * OPERATOR_PANEL_MAX_RATIO))
    desired = round(left_height * OPERATOR_PANEL_DEFAULT_RATIO)
    return max(minimum, min(maximum, desired))


def agent_pbx_mcp_url(server: str) -> str:
    return f"{server.rstrip('/')}/mcp"


def codex_command_argv(codex_command: str) -> list[str]:
    argv = shlex.split(codex_command.strip())
    return argv or ["codex"]


def codex_mcp_add_command(codex_command: str, mcp_url: str) -> list[str]:
    return [
        *codex_command_argv(codex_command),
        "mcp",
        "add",
        "agent-pbx",
        "--url",
        mcp_url,
        "--bearer-token-env-var",
        AGENT_PBX_TOKEN_ENV,
    ]


def codex_mcp_remove_command(codex_command: str) -> list[str]:
    return [*codex_command_argv(codex_command), "mcp", "remove", "agent-pbx"]


def toml_key(value: str) -> str:
    if re.match(r"^[A-Za-z0-9_-]+$", value):
        return value
    return json.dumps(value)


def codex_config_mcp_key(server_name: str, setting: str) -> str:
    return f"mcp_servers.{toml_key(server_name)}.{setting}"


def toml_literal(value: object) -> str:
    if isinstance(value, str):
        return json.dumps(value)
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return json.dumps(value)
    if isinstance(value, Mapping):
        return (
            "{"
            + ", ".join(
                f"{toml_key(str(key))} = {toml_literal(item)}"
                for key, item in value.items()
            )
            + "}"
        )
    if isinstance(value, Iterable):
        return "[" + ", ".join(toml_literal(item) for item in value) + "]"
    return json.dumps(value)


def codex_config_override(key: str, value: object) -> str:
    return f"{key}={toml_literal(value)}"


def codex_model_launch_config_overrides() -> list[str]:
    return codex_model_config_overrides(
        model=os.getenv(CODEX_MODEL_ENV),
        reasoning_effort=os.getenv(CODEX_REASONING_EFFORT_ENV),
        reasoning_summary=os.getenv(CODEX_REASONING_SUMMARY_ENV),
        verbosity=os.getenv(CODEX_VERBOSITY_ENV),
        service_tier=os.getenv(CODEX_SERVICE_TIER_ENV),
    )


def codex_project_trust_config_override(cwd: str | None) -> str | None:
    path = str(cwd or "").strip()
    if not path:
        return None
    try:
        resolved = str(Path(path).expanduser().resolve())
    except OSError:
        resolved = str(Path(path).expanduser())
    return codex_config_override(
        "projects",
        {resolved: {"trust_level": "trusted"}},
    )


def parse_codex_config_string_value(raw_value: str) -> str | None:
    value = raw_value.strip()
    if len(value) < 2:
        return None
    if value[0] == value[-1] == '"':
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return value[1:-1]
        return parsed if isinstance(parsed, str) else None
    if value[0] == value[-1] == "'":
        return value[1:-1]
    return None


def parse_codex_config_string_array(raw_value: str) -> list[str] | None:
    value = raw_value.strip()
    if not value.startswith("[") or not value.endswith("]"):
        return None
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError:
        return None
    if not isinstance(parsed, list):
        return None
    items = [item for item in parsed if isinstance(item, str)]
    return items if len(items) == len(parsed) else None


def parse_codex_config_simple_value(raw_value: str) -> object | None:
    value = raw_value.strip()
    parsed_string = parse_codex_config_string_value(value)
    if parsed_string is not None:
        return parsed_string
    parsed_array = parse_codex_config_string_array(value)
    if parsed_array is not None:
        return parsed_array
    return None


def codex_mcp_server_header_name(line: str) -> str | None:
    match = re.match(r"^\s*\[mcp_servers\.(?P<name>.+)]\s*(?:#.*)?$", line)
    if not match:
        return None
    raw_name = match.group("name").strip()
    if raw_name.startswith('"') and raw_name.endswith('"'):
        try:
            parsed = json.loads(raw_name)
        except json.JSONDecodeError:
            return raw_name[1:-1]
        return parsed if isinstance(parsed, str) else None
    return raw_name


def load_codex_mcp_server_configs(
    codex_home: Path | None,
    server_names: Iterable[str],
) -> dict[str, dict[str, object]]:
    if codex_home is None:
        return {}
    config_path = codex_home / "config.toml"
    try:
        lines = config_path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return {}

    targets = set(server_names)
    configs: dict[str, dict[str, object]] = {}
    current: str | None = None
    for line in lines:
        header_name = codex_mcp_server_header_name(line)
        if header_name is not None:
            current = header_name if header_name in targets else None
            if current is not None:
                configs.setdefault(current, {})
            continue
        if line.strip().startswith("["):
            current = None
            continue
        if current is None or "=" not in line:
            continue
        key, raw_value = line.split("=", 1)
        key = key.strip()
        if key not in CODEX_MCP_SERVER_TRANSPORT_KEYS:
            continue
        value = parse_codex_config_simple_value(raw_value)
        if value is not None:
            configs[current][key] = value
    return configs


def review_operator_mcp_approval_server_names() -> tuple[str, ...]:
    return mcp_approval_server_names(
        REVIEW_OPERATOR_MCP_APPROVAL_SERVERS_ENV,
        fallback_env_names=(),
    )


def operator_mcp_approval_server_names() -> tuple[str, ...]:
    return mcp_approval_server_names(
        OPERATOR_MCP_APPROVAL_SERVERS_ENV,
        fallback_env_names=(REVIEW_OPERATOR_MCP_APPROVAL_SERVERS_ENV,),
    )


def mcp_approval_server_names(
    env_name: str,
    *,
    fallback_env_names: Iterable[str] = (),
) -> tuple[str, ...]:
    configured = os.getenv(env_name, "").strip()
    if not configured:
        for fallback_name in fallback_env_names:
            configured = os.getenv(fallback_name, "").strip()
            if configured:
                break
    if configured:
        names = tuple(
            name.strip()
            for name in configured.split(",")
            if name.strip()
        )
    else:
        names = DEFAULT_REVIEW_OPERATOR_MCP_APPROVAL_SERVERS
    if "agent-pbx" in names:
        return names
    return ("agent-pbx", *names)


def review_operator_mcp_config_overrides(
    server_names: Iterable[str] | None = None,
    *,
    mcp_url: str | None = None,
    codex_home: Path | None = None,
    server_configs: Mapping[str, Mapping[str, object]] | None = None,
    agent_pbx_approved_tools: Iterable[str] | None = None,
) -> list[str]:
    overrides: list[str] = []
    names = server_names or review_operator_mcp_approval_server_names()
    configured_servers: dict[str, dict[str, object]] = {
        server_name: dict(config)
        for server_name, config in DEFAULT_REVIEW_OPERATOR_MCP_SERVER_CONFIGS.items()
    }
    configured_servers.update(load_codex_mcp_server_configs(codex_home, names))
    if server_configs:
        configured_servers.update(
            {
                server_name: dict(config)
                for server_name, config in server_configs.items()
            }
        )
    resolved_agent_pbx_tools = tuple(agent_pbx_approved_tools or ())
    for server_name in names:
        approved_tools = (
            resolved_agent_pbx_tools
            if server_name == "agent-pbx" and resolved_agent_pbx_tools
            else REVIEW_OPERATOR_MCP_APPROVED_TOOLS.get(server_name)
        )
        if not approved_tools:
            continue
        transport_config = dict(configured_servers.get(server_name, {}))
        if server_name == "agent-pbx":
            transport_config["url"] = (
                mcp_url
                or str(transport_config.get("url") or "").strip()
                or agent_pbx_mcp_url(
                    os.getenv(AGENT_PBX_SERVER_URL_ENV, "http://127.0.0.1:8765")
                )
            )
            transport_config["bearer_token_env_var"] = AGENT_PBX_TOKEN_ENV
        if not transport_config.get("url") and not transport_config.get("command"):
            continue
        config = {
            key: value
            for key, value in transport_config.items()
            if key in CODEX_MCP_SERVER_TRANSPORT_KEYS
        }
        config["enabled_tools"] = list(approved_tools)
        config["default_tools_approval_mode"] = "approve"
        overrides.append(
            codex_config_override(
                f"mcp_servers.{toml_key(server_name)}",
                config,
            )
        )
    return overrides


def agent_pbx_mcp_config_override(
    approved_tools: Iterable[str],
    *,
    mcp_url: str | None = None,
) -> str:
    transport_config = {
        "url": mcp_url
        or agent_pbx_mcp_url(
            os.getenv(AGENT_PBX_SERVER_URL_ENV, "http://127.0.0.1:8765")
        ),
        "bearer_token_env_var": AGENT_PBX_TOKEN_ENV,
        "enabled_tools": list(approved_tools),
        "default_tools_approval_mode": "approve",
    }
    return codex_config_override(
        "mcp_servers.agent-pbx",
        transport_config,
    )


