def operator_agent_config_overrides(
    server_names: Iterable[str] | None = None,
    *,
    mcp_url: str | None = None,
    codex_home: Path | None = None,
    work_root: str | None = None,
    server_configs: Mapping[str, Mapping[str, object]] | None = None,
    include_campaign_lifecycle: bool = False,
    terminal_mode: str = CODEX_TERMINAL_MODE_DEFAULT,
) -> list[str]:
    """Build a least-privilege operator MCP allowlist for a launch.

    Root operator panes receive the campaign lifecycle tools. Edit and review
    forks remain unable to create, follow up, or finish campaigns directly.
    """
    overrides = review_operator_mcp_config_overrides(
        server_names or operator_mcp_approval_server_names(),
        mcp_url=mcp_url,
        codex_home=codex_home,
        server_configs=server_configs,
        agent_pbx_approved_tools=(
            OPERATOR_AGENT_PBX_APPROVED_TOOLS
            if include_campaign_lifecycle
            else None
        ),
    )
    trust_override = codex_project_trust_config_override(work_root)
    if trust_override:
        overrides.append(trust_override)
    overrides.extend(
        codex_model_preset_config_overrides(
            CODEX_MODEL_PRESET_BY_KEY[DEFAULT_OPERATOR_MODEL_PRESET_KEY]
        )
    )
    overrides.extend(codex_model_launch_config_overrides())
    overrides.extend(codex_terminal_config_overrides(terminal_mode))
    return overrides


def process_error_summary(result: subprocess.CompletedProcess[str]) -> str:
    detail = (result.stderr or result.stdout or "").strip()
    if detail:
        return detail
    return f"exit code {result.returncode}"


def configure_codex_mcp(
    codex_command: str,
    mcp_url: str,
    *,
    timeout: float = 15.0,
) -> None:
    add_command = codex_mcp_add_command(codex_command, mcp_url)
    add = subprocess.run(
        add_command,
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    if add.returncode == 0:
        return
    add_failure = process_error_summary(add).lower()
    if "exist" not in add_failure and "already" not in add_failure:
        raise RuntimeError(f"add failed: {process_error_summary(add)}")

    remove = subprocess.run(
        codex_mcp_remove_command(codex_command),
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    retry = subprocess.run(
        add_command,
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    if retry.returncode == 0:
        return

    details = [f"add failed: {process_error_summary(add)}"]
    if remove.returncode != 0:
        details.append(f"remove failed: {process_error_summary(remove)}")
    details.append(f"retry failed: {process_error_summary(retry)}")
    raise RuntimeError("; ".join(details))


