def normalize_joplin_copy_mode(value: object) -> str:
    mode = str(value or "").strip().casefold().replace("-", "_")
    if mode in {
        JOPLIN_COPY_MODE_COPY_FIRST,
        "copy",
        "clipboard",
        "clipboard_first",
        "legacy",
        "legacy_clipboard",
        "fast",
    }:
        return JOPLIN_COPY_MODE_COPY_FIRST
    if mode in {
        JOPLIN_COPY_MODE_TRANSCRIPT_FIRST,
        "transcript",
        "export",
        "clean",
    }:
        return JOPLIN_COPY_MODE_TRANSCRIPT_FIRST
    if mode in {
        JOPLIN_COPY_MODE_TMUX_CAPTURE,
        "tmux",
        "capture",
        "visible",
    }:
        return JOPLIN_COPY_MODE_TMUX_CAPTURE
    return DEFAULT_JOPLIN_COPY_MODE


def normalize_codex_terminal_mode(value: object) -> str:
    mode = str(value or "").strip().casefold().replace("-", "_")
    if mode in {"scrollback", "normal", "pbx", "compatible"}:
        return CODEX_TERMINAL_MODE_SCROLLBACK
    if mode in {"raw", "raw_output", "raw_scrollback"}:
        return CODEX_TERMINAL_MODE_RAW
    if mode in {"default", "codex", "auto"}:
        return CODEX_TERMINAL_MODE_DEFAULT
    return DEFAULT_CODEX_TERMINAL_MODE


def codex_terminal_config_overrides(mode: object) -> list[str]:
    normalized = normalize_codex_terminal_mode(mode)
    overrides = list(portable_codex_keymap_overrides())
    if normalized == CODEX_TERMINAL_MODE_DEFAULT:
        return overrides
    overrides.append(codex_config_override("tui.alternate_screen", "never"))
    if normalized == CODEX_TERMINAL_MODE_RAW:
        overrides.append(codex_config_override("tui.raw_output_mode", True))
    return overrides


def codex_model_preset_for(value: object) -> CodexModelPreset | None:
    key = str(value or "").strip().casefold()
    if not key:
        return None
    return CODEX_MODEL_PRESET_ALIASES.get(key)


def codex_model_preset_from_metadata(
    metadata: Mapping[str, Any] | None,
) -> CodexModelPreset | None:
    """Recover the last selected harness preset without trusting free-form text."""
    if not isinstance(metadata, Mapping):
        return None
    preset = codex_model_preset_for(metadata.get("codex_model_preset"))
    if preset is not None:
        return preset
    model = str(metadata.get("codex_model") or "").strip()
    effort = str(metadata.get("codex_model_reasoning_effort") or "").strip()
    summary = str(metadata.get("codex_model_reasoning_summary") or "").strip()
    verbosity = str(metadata.get("codex_model_verbosity") or "").strip()
    for candidate in CODEX_MODEL_PRESETS:
        if candidate.model != model or candidate.reasoning_effort != effort:
            continue
        if summary and candidate.reasoning_summary != summary:
            continue
        if candidate.verbosity and candidate.verbosity != verbosity:
            continue
        return candidate
    return None


def codex_model_preset_config_overrides(
    preset: CodexModelPreset | None,
) -> list[str]:
    if preset is None:
        return []
    return codex_model_config_overrides(
        model=preset.model,
        reasoning_effort=preset.reasoning_effort,
        reasoning_summary=preset.reasoning_summary,
        verbosity=preset.verbosity,
    )


