def normalized_key_names(event: Key) -> set[str]:
    values = {event.key, getattr(event, "name", "")}
    values.update(getattr(event, "aliases", []) or [])
    return {value.strip().lower().replace("_", "+") for value in values if value}


def is_follow_up_newline_key(event: Key) -> bool:
    names = normalized_key_names(event)
    return bool(names & FOLLOW_UP_NEWLINE_KEYS) or any(
        ("shift" in name.split("+") or "alt" in name.split("+"))
        and ("enter" in name.split("+") or "return" in name.split("+"))
        for name in names
    )


def follow_up_edit_control(event: Key) -> str | None:
    for name in normalized_key_names(event):
        if edit := FOLLOW_UP_EDIT_KEYS.get(name):
            return edit
    return None


def slash_completion_direction(event: Key) -> int | None:
    names = normalized_key_names(event)
    if names & SLASH_COMPLETION_FORWARD_KEYS:
        return 1
    if names & SLASH_COMPLETION_BACKWARD_KEYS:
        return -1
    return None


def git_diff_passthrough_command(target: str = "") -> str:
    clean_target = target.strip()
    if not clean_target:
        return "!git diff"
    quoted = shlex.quote(clean_target)
    if ":" in clean_target and not clean_target.startswith((".", "/")):
        return f"!git diff {quoted}"
    return f"!git diff -- {quoted}"


def git_push_passthrough_command(branch: str = "") -> str:
    clean_branch = branch.strip()
    if not clean_branch:
        return "!git push origin HEAD"
    return f"!git push origin {shlex.quote(clean_branch)}"


def parse_git_push_slash_command(message: str) -> str | None:
    stripped = message.strip()
    if "\n" in stripped:
        return None
    if stripped.lower() == "/gitpush":
        return ""
    command, separator, branch = stripped.partition(" ")
    if not separator or command.lower() != "/gitpush":
        return None
    return branch.strip()


class SettingsScreen(ModalScreen[None]):
    BINDINGS = [("escape", "dismiss", "Close")]

    def __init__(
        self,
        *,
        visual_flash_enabled: bool,
        terminal_bell_enabled: bool,
        agent_blink_enabled: bool,
        low_power_enabled: bool,
        layout_mode: str,
        split_percent: int,
        joplin_copy_mode: str,
        tmux_direct_enabled: bool,
        tmux_features_available: bool,
        tmux_runtime_server_mode: str,
        embedded_terminal_enabled: bool,
        embedded_terminal_scroll_mode: str,
        tmux_popout_mode: str,
        custom_theme_name: str,
        theme_name: str,
    ) -> None:
        super().__init__()
        self.visual_flash_enabled = visual_flash_enabled
        self.terminal_bell_enabled = terminal_bell_enabled
        self.agent_blink_enabled = agent_blink_enabled
        self.low_power_enabled = low_power_enabled
        self.layout_mode = layout_mode
        self.split_percent = split_percent
        self.joplin_copy_mode = normalize_joplin_copy_mode(joplin_copy_mode)
        self.tmux_direct_enabled = tmux_direct_enabled
        self.tmux_features_available = tmux_features_available
        self.tmux_runtime_server_mode = normalize_runtime_server_mode(
            tmux_runtime_server_mode
        ).value
        self.embedded_terminal_enabled = embedded_terminal_enabled
        self.embedded_terminal_scroll_mode = normalize_embedded_scroll_mode(
            embedded_terminal_scroll_mode
        )
        self.tmux_popout_mode = tmux_popout_mode
        self.custom_theme_name = custom_theme_name
        self.theme_name = theme_name

    def compose(self) -> ComposeResult:
        with Vertical(id="settings-panel"):
            yield Static("Settings", id="settings-title")
            with Vertical(id="settings-options"):
                yield Checkbox(
                    "Visual flash",
                    value=self.visual_flash_enabled,
                    id="visual-flash",
                )
                yield Checkbox(
                    "Terminal bell",
                    value=self.terminal_bell_enabled,
                    id="terminal-bell",
                )
                yield Checkbox(
                    "Unseen blink",
                    value=self.agent_blink_enabled,
                    id="agent-blink",
                )
                yield Checkbox(
                    "Low-power watch mode",
                    value=self.low_power_enabled,
                    id="low-power",
                )
                yield Static("Layout", id="layout-mode-label")
                yield Select(
                    LAYOUT_CHOICES,
                    value=self.layout_mode,
                    allow_blank=False,
                    id="layout-mode",
                )
                yield Static(
                    f"Agents width: {self.split_percent}%",
                    id="split-percent-label",
                )
                with Horizontal(id="split-percent-actions"):
                    yield Button("Narrow", id="split-narrow")
                    yield Button("Reset", id="split-reset")
                    yield Button("Widen", id="split-widen")
                yield Static("Joplin response copy", id="joplin-copy-mode-label")
                yield Select(
                    JOPLIN_COPY_MODE_CHOICES,
                    value=self.joplin_copy_mode,
                    allow_blank=False,
                    id="joplin-copy-mode",
                )
                tmux_direct = Checkbox(
                    "Tmux direct default",
                    value=self.tmux_direct_enabled,
                    id="tmux-direct",
                )
                tmux_direct.disabled = not self.tmux_features_available
                yield tmux_direct
                yield Static("Runtime tmux server", id="tmux-runtime-mode-label")
                yield Select(
                    TMUX_RUNTIME_SERVER_MODE_CHOICES,
                    value=self.tmux_runtime_server_mode,
                    allow_blank=False,
                    id="tmux-runtime-mode",
                )
                embedded_terminal = Checkbox(
                    "Embedded native tmux terminal (v2)",
                    value=self.embedded_terminal_enabled,
                    id="embedded-terminal-v2",
                )
                embedded_terminal.disabled = not self.tmux_features_available
                yield embedded_terminal
                yield Static(
                    "Embedded wheel/swipe behavior",
                    id="embedded-terminal-scroll-mode-label",
                )
                embedded_scroll_mode = Select(
                    EMBEDDED_TERMINAL_SCROLL_MODE_CHOICES,
                    value=self.embedded_terminal_scroll_mode,
                    allow_blank=False,
                    id="embedded-terminal-scroll-mode",
                )
                embedded_scroll_mode.disabled = not self.tmux_features_available
                yield embedded_scroll_mode
                yield Static("Tmux pop-out behavior", id="tmux-popout-mode-label")
                yield Select(
                    TMUX_POPOUT_MODE_CHOICES,
                    value=self.tmux_popout_mode,
                    allow_blank=False,
                    id="tmux-popout-mode",
                )
                yield Static("Theme", id="theme-label")
                yield Select(
                    [
                        ("Cyberpunk", DEFAULT_TUI_THEME),
                        ("Minimal", MINIMAL_TUI_THEME),
                        (self.custom_theme_name, self.custom_theme_name),
                    ],
                    value=self.theme_name,
                    allow_blank=False,
                    id="theme-mode",
                )
            with Horizontal(id="settings-actions"):
                yield Button("Close", id="settings-close", variant="primary")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "settings-close":
            event.stop()
            self.dismiss()
            return
        if event.button.id in {"split-narrow", "split-reset", "split-widen"}:
            event.stop()
            app = self.app
            if event.button.id == "split-narrow":
                app.adjust_split_percent(-SPLIT_PERCENT_STEP)  # type: ignore[attr-defined]
            elif event.button.id == "split-widen":
                app.adjust_split_percent(SPLIT_PERCENT_STEP)  # type: ignore[attr-defined]
            else:
                app.reset_split_percent()  # type: ignore[attr-defined]
            self.split_percent = app.split_percent  # type: ignore[attr-defined]
            self.query_one("#split-percent-label", Static).update(
                f"Agents width: {self.split_percent}%"
            )

    def on_select_changed(self, event: Select.Changed) -> None:
        if event.select.id == "layout-mode":
            event.stop()
            self.app.set_layout_mode(str(event.value))  # type: ignore[attr-defined]
        elif event.select.id == "theme-mode":
            event.stop()
            self.app.set_ui_theme(str(event.value))  # type: ignore[attr-defined]
        elif event.select.id == "joplin-copy-mode":
            event.stop()
            self.app.set_joplin_copy_mode(str(event.value))  # type: ignore[attr-defined]
        elif event.select.id == "tmux-runtime-mode":
            event.stop()
            self.app.set_tmux_runtime_server_mode(str(event.value))  # type: ignore[attr-defined]
        elif event.select.id == "embedded-terminal-scroll-mode":
            event.stop()
            self.app.set_embedded_terminal_scroll_mode(str(event.value))  # type: ignore[attr-defined]
        elif event.select.id == "tmux-popout-mode":
            event.stop()
            self.app.set_tmux_popout_mode(str(event.value))  # type: ignore[attr-defined]


class ManagedProjectPickerScreen(ModalScreen[None]):
    BINDINGS = [("escape", "dismiss", "Close")]

    def __init__(self, projects: list[dict[str, Any]], roots: list[str]) -> None:
        super().__init__()
        self.projects = projects
        self.roots = roots
        self.selected_path = ""
        self.selected_owners: list[str] = []

    def compose(self) -> ComposeResult:
        with Vertical(id="managed-project-picker"):
            yield Static("Launch Project Workspace", id="managed-project-picker-title")
            yield Static(
                "Approved roots: " + (", ".join(self.roots) or "none"),
                id="managed-project-roots",
            )
            yield DataTable(id="managed-projects", cursor_type="row", show_row_labels=False)
            yield Input(placeholder="Optional Agent ID", id="managed-agent-id")
            yield Select(
                (
                    ("Agent", "agent"),
                    ("Agent + root Operator", "agent_operator"),
                ),
                value="agent",
                allow_blank=False,
                id="managed-launch-mode",
            )
            yield Select(
                (
                    ("Sol 5.6 / high", "sol-high"),
                    ("Sol 5.6 / xhigh", "sol-xhigh"),
                    ("Terra 5.6 / xhigh", "terra-xhigh"),
                    ("Terra 5.6 / max", "terra-max"),
                ),
                value="sol-high",
                allow_blank=False,
                id="managed-agent-profile",
            )
            yield Select(
                TMUX_RUNTIME_SERVER_MODE_CHOICES,
                value=self.app.tmux_runtime_server_mode,  # type: ignore[attr-defined]
                allow_blank=False,
                id="managed-agent-runtime-mode",
            )
            with Horizontal(id="managed-project-actions"):
                yield Button("Launch", id="managed-project-launch", variant="primary")
                yield Button("Close", id="managed-project-close")

    def on_mount(self) -> None:
        table = self.query_one("#managed-projects", DataTable)
        table.add_columns("Available", "Project", "Branch", "Path", "Owner")
        for item in self.projects:
            path = str(item.get("path") or "")
            owners = item.get("owned_by") if isinstance(item.get("owned_by"), list) else []
            table.add_row(
                "yes" if item.get("available") else "no",
                str(item.get("name") or "-"),
                str(item.get("branch") or "-"),
                path,
                ", ".join(str(owner) for owner in owners) or "-",
                key=path,
            )
        if self.projects:
            first_item = self.projects[0]
            first = str(first_item.get("path") or "")
            if first:
                self.selected_path = first
                owners = first_item.get("owned_by")
                self.selected_owners = (
                    [str(owner) for owner in owners]
                    if isinstance(owners, list)
                    else []
                )
                table.move_cursor(row=0)

    def on_data_table_row_selected(self, event: DataTable.RowSelected) -> None:
        if event.data_table.id == "managed-projects":
            self.selected_path = str(event.row_key.value)
            selected = next(
                (
                    item
                    for item in self.projects
                    if str(item.get("path") or "") == self.selected_path
                ),
                {},
            )
            owners = selected.get("owned_by") if isinstance(selected, dict) else []
            self.selected_owners = (
                [str(owner) for owner in owners]
                if isinstance(owners, list)
                else []
            )

    async def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "managed-project-close":
            self.dismiss()
            return
        if event.button.id != "managed-project-launch":
            return
        if not self.selected_path:
            self.app.notify("Select a Git project first.", severity="warning")
            return
        launch_request = {
            "project_path": self.selected_path,
            "agent_id": self.query_one("#managed-agent-id", Input).value,
            "profile_id": str(self.query_one("#managed-agent-profile", Select).value),
            "runtime_server_mode": str(
                self.query_one("#managed-agent-runtime-mode", Select).value
            ),
            "launch_mode": str(self.query_one("#managed-launch-mode", Select).value),
            "existing_owner_ids": self.selected_owners,
        }
        # Managed launch selects the new Agent and attaches its terminal. Pop
        # the modal first so app-level widget queries resolve against the main
        # PBX screen instead of this temporary picker.
        self.dismiss()
        await asyncio.sleep(0)
        await self.app.launch_managed_workspace_from_picker(  # type: ignore[attr-defined]
            **launch_request,
        )


class RuntimeMigrationScreen(ModalScreen[None]):
    BINDINGS = [("escape", "dismiss", "Close")]

    def __init__(self, batch: dict[str, Any]) -> None:
        super().__init__()
        self.batch = batch

    def compose(self) -> ComposeResult:
        with Vertical(id="runtime-migration-screen"):
            yield Static(
                f"Runtime Migration {self.batch.get('batch_id', '-')}",
                id="runtime-migration-title",
            )
            yield Static(
                f"Eligible {self.batch.get('eligible_count', 0)} · "
                f"Blocked {self.batch.get('blocked_count', 0)} · "
                f"Rollback retained until {self.batch.get('retention_until', '-')}",
                id="runtime-migration-summary",
            )
            yield DataTable(id="runtime-migration-candidates", cursor_type="row")
            with Horizontal(id="runtime-migration-actions"):
                yield Button("Apply Eligible", id="runtime-migration-apply", variant="primary")
                yield Button("Restore Mappings", id="runtime-migration-rollback")
                yield Button("Close", id="runtime-migration-close")

    def on_mount(self) -> None:
        table = self.query_one("#runtime-migration-candidates", DataTable)
        table.add_columns("Agent", "Type", "Session", "Eligible", "Blockers")
        candidates = self.batch.get("candidates")
        for item in candidates if isinstance(candidates, list) else []:
            if not isinstance(item, dict):
                continue
            table.add_row(
                str(item.get("agent_id") or "-"),
                str(item.get("agent_type") or "-"),
                str(item.get("session_id") or "-"),
                "yes" if item.get("eligible") else "no",
                "; ".join(str(value) for value in item.get("blockers", [])) or "-",
            )

    async def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "runtime-migration-close":
            self.dismiss()
        elif event.button.id == "runtime-migration-apply":
            await self.app.apply_runtime_migration_batch(self.batch)  # type: ignore[attr-defined]
            self.dismiss()
        elif event.button.id == "runtime-migration-rollback":
            await self.app.rollback_runtime_migration_batch(  # type: ignore[attr-defined]
                str(self.batch.get("batch_id") or "")
            )
            self.dismiss()


