    @staticmethod
    def is_plain_function_key(key: str) -> bool:
        normalized = str(key or "").strip().lower().replace("_", "+")
        return bool(re.fullmatch(r"f(?:[1-9]|1[0-2])", normalized))

    @classmethod
    def pbx_owns_key_under_terminal_focus(cls, key: str) -> bool:
        """Return whether PBX retains a key while the child terminal is focused."""

        normalized = str(key or "").strip().lower().replace("_", "+")
        return normalized == cls.COMMAND_PALETTE_BINDING or cls.is_plain_function_key(
            normalized
        )

    def embedded_terminal_surface(
        self,
        *,
        require_focus: bool = False,
    ) -> PbxTerminalSurface | None:
        """Return the live writable terminal only while it owns Latest input."""

        agent_id = self.embedded_terminal_agent_id
        if (
            not agent_id
            or not self.embedded_terminal_v2_enabled
            or self.active_agent_tab != "latest-tab"
            or self.selected_agent_id != agent_id
            or not self.is_tmux_direct_enabled(agent_id)
        ):
            return None
        surface = self.query_one_or_none(
            "#pbx-terminal-surface", PbxTerminalSurface
        )
        if (
            surface is None
            or not surface.attached
            or surface.read_only_client
        ):
            return None
        if require_focus:
            try:
                if self.focused is not surface:
                    return None
            except ScreenStackError:
                return None
        return surface

    async def _check_bindings(self, key: str, priority: bool = False) -> bool:
        """Route focused-terminal keys through the central PBX ownership policy.

        Textual evaluates priority bindings before forwarding a key to the
        focused widget. The gate must therefore run here; action-level guards
        alone would still consume printable characters and control bytes.
        Plain function keys and the command-palette key remain PBX-owned.
        """

        if (
            priority
            and self.embedded_terminal_surface(require_focus=True) is not None
            and not self.pbx_owns_key_under_terminal_focus(key)
        ):
            return False
        return await super()._check_bindings(key, priority)

    def resolve_agent_refresh_seconds(self) -> float:
        default = (
            LOW_POWER_AGENT_REFRESH_SECONDS
            if self.low_power_enabled
            else DEFAULT_AGENT_REFRESH_SECONDS
        )
        return env_agent_refresh_seconds_value() or default

    def resolve_attention_blink_seconds(self) -> float:
        default = (
            LOW_POWER_ATTENTION_BLINK_SECONDS
            if self.low_power_enabled
            else DEFAULT_ATTENTION_BLINK_SECONDS
        )
        return env_attention_blink_seconds_value() or default

    def api_client(self) -> httpx.AsyncClient:
        if self.http_client is None:
            self.http_client = httpx.AsyncClient(base_url=self.server, timeout=10)
        return self.http_client

    async def refresh_codex_posture(self) -> None:
        posture = await asyncio.to_thread(inspect_codex_posture)
        self.codex_posture = posture
        panel = self.query_one_or_none("#codex-posture", Static)
        if panel is not None:
            panel.update(self.format_codex_posture(posture))
        for warning in posture.warnings:
            self.notify(warning, severity="warning")

    async def update_codex_cli_from_host(self, target: str = "latest") -> None:
        self.notify(f"Updating Codex CLI package to {target} via Agent PBX daemon...")
        try:
            response = await self.api_client().post(
                "/v1/codex/cli/update",
                json={"target": target},
                headers=auth_headers(self.token),
                timeout=240,
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Codex CLI update failed: {exc}", severity="error")
            return
        detail = self.query_one_or_none("#detail", TextArea)
        lines = self.format_codex_update_result(result)
        if detail is not None:
            detail.text = "\n".join(lines)
        if bool(result.get("ok")):
            after = result.get("after") if isinstance(result.get("after"), dict) else {}
            shell_version = str(after.get("shell_version") or "-")
            self.notify(f"Codex CLI update complete; shell CLI is {shell_version}.")
        else:
            error = str(result.get("error") or "unknown error")
            self.notify(f"Codex CLI update failed: {error}", severity="error")
        await self.refresh_codex_posture()
        await self.load_codex_config()

    def selected_codex_model_preset(self) -> CodexModelPreset:
        selector = self.query_one_or_none("#codex-model-preset", Select)
        if selector is not None:
            preset = codex_model_preset_for(selector.value)
            if preset is not None:
                return preset
        return self.default_codex_model_preset_for_agent()

    def default_codex_model_preset_for_agent(
        self,
        agent_id: str | None = None,
    ) -> CodexModelPreset:
        target_id = str(agent_id or self.selected_agent_id or "").strip()
        agent = self.agents.get(target_id) or {}
        key = (
            "sol-5.6-xhigh"
            if self.agent_type(agent) == OPERATOR_AGENT_TYPE
            else "sol-5.6-high"
        )
        return CODEX_MODEL_PRESET_BY_KEY[key]

    def sync_codex_model_preset_for_agent(self, agent_id: str) -> CodexModelPreset:
        agent = self.agents.get(agent_id) or {}
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        preset = (
            codex_model_preset_from_metadata(metadata)
            or self.default_codex_model_preset_for_agent(agent_id)
        )
        selector = self.query_one_or_none("#codex-model-preset", Select)
        if selector is not None:
            selector.value = preset.key
        self.update_codex_model_status(preset)
        return preset

    def codex_model_target_agent_id(self) -> str | None:
        """Return the explicit right-pane target for model-affecting actions.

        A command-palette invocation moves focus away from the Agents or
        Operators table.  The tables retain independent cursors, so using a
        cursor after that focus change can restart an unrelated pane.  Model
        changes are intentionally bound to the agent currently displayed in
        the right pane instead.
        """
        agent_id = str(self.selected_agent_id or "").strip()
        if agent_id and agent_id in self.agents:
            return agent_id
        self.notify(
            "Select the target agent or operator before changing its Codex model.",
            severity="warning",
        )
        return None

    def set_codex_model_preset_selector(self, preset: CodexModelPreset) -> None:
        selector = self.query_one_or_none("#codex-model-preset", Select)
        if selector is not None:
            selector.value = preset.key
        self.update_codex_model_status(preset)

    def update_codex_model_status(self, preset: CodexModelPreset | None = None) -> None:
        preset = preset or self.selected_codex_model_preset()
        status = self.query_one_or_none("#codex-model-status", Static)
        if status is not None:
            target = str(self.selected_agent_id or "").strip() or "select an agent"
            verbosity = (
                f", verbosity {preset.verbosity}" if preset.verbosity else ""
            )
            reasoning_summary = (
                f", reasoning summary {preset.reasoning_summary}"
                if preset.reasoning_summary
                else ""
            )
            status.update(
                f"Target: {target}\n"
                "Model preset: "
                f"{preset.label} -> {preset.model}/{preset.reasoning_effort}"
                f"{verbosity}{reasoning_summary}. "
                f"{preset.description}"
            )

    async def validate_codex_model_preset(
        self,
        preset: CodexModelPreset,
    ) -> tuple[bool, str]:
        catalog = await asyncio.to_thread(
            inspect_codex_model_catalog,
            self.operator_codex_command(),
        )
        if not catalog:
            return (
                False,
                "Codex model catalog is unavailable from `codex debug models`.",
            )
        by_slug: dict[str, CodexModelOption] = {
            item.slug: item for item in catalog if not item.hidden
        }
        model = by_slug.get(preset.model)
        if model is None:
            return (
                False,
                f"{preset.model!r} is not in `codex debug models`.",
            )
        supported_efforts = {
            str(level).strip().casefold()
            for level in model.supported_reasoning_levels
        }
        if (
            supported_efforts
            and preset.reasoning_effort.casefold() not in supported_efforts
        ):
            return (
                False,
                f"{preset.model!r} does not advertise reasoning effort "
                f"{preset.reasoning_effort!r}.",
            )
        if preset.verbosity and model.supports_verbosity is False:
            return (
                False,
                f"{preset.model!r} does not advertise response verbosity support.",
            )
        return True, ""

    async def ensure_codex_model_preset_valid(
        self,
        preset: CodexModelPreset,
    ) -> bool:
        ok, warning = await self.validate_codex_model_preset(preset)
        if ok:
            return True
        self.notify(f"Codex model preset unavailable: {warning}", severity="error")
        return False

    def codex_model_preset_plan_lines(
        self,
        agent_id: str,
        preset: CodexModelPreset,
    ) -> list[str]:
        agent = self.agents.get(agent_id) or {}
        metadata = (
            agent.get("metadata")
            if isinstance(agent.get("metadata"), dict)
            else {}
        )
        pane_id = str(
            self.tmux_agent_targets.get(agent_id)
            or metadata.get("tmux_pane_id")
            or ""
        ).strip()
        session_id = str(
            metadata.get("fork_codex_session_id")
            or metadata.get("last_resume_codex_session_id")
            or metadata.get("codex_session_id")
            or metadata.get("codex_thread_id")
            or metadata.get("source_codex_session_id")
            or ""
        ).strip()
        cwd = str(metadata.get("work_root") or metadata.get("cwd") or "").strip()
        role = self.operator_role(agent) if isinstance(agent, dict) else CALLER_AGENT_TYPE
        preset_lines = [
            f"- {preset.label}",
            f"- model = {preset.model}",
            f"- model_reasoning_effort = {preset.reasoning_effort}",
        ]
        if preset.verbosity:
            preset_lines.append(f"- model_verbosity = {preset.verbosity}")
        if preset.reasoning_summary:
            preset_lines.append(
                f"- model_reasoning_summary = {preset.reasoning_summary}"
            )
        preset_lines.append(f"- description: {preset.description}")
        lines = [
            "Codex Model Migration Plan",
            "",
            f"Target: {agent_id}",
            f"Type: {self.agent_type(agent) if isinstance(agent, dict) else '-'}",
            f"Role: {role}",
            f"Pane: {pane_id or '-'}",
            f"CWD: {cwd or '-'}",
            f"Current session: {session_id or '-'}",
            "",
            "Preset:",
            *preset_lines,
            "",
            "Safe switch path:",
            "1. Snapshot Agent PBX metadata, pane id, cwd, session id, and transcript boundary.",
            "2. Ask for or capture a compact handoff if the pane is not idle.",
            "3. Respawn the current tmux pane with explicit `-c` model overrides.",
            "4. Resume the fork/current session id first; avoid falling back to source session ids unless this is a fresh fork launch.",
            "5. Keep the same pane id under the same Agent PBX id and patch metadata with the selected preset.",
            "6. Verify latest transcript/session mapping and Joplin copy before retiring backups.",
            "",
            "Current TUI restart action:",
            "- Restarts and resumes in the selected tmux pane, then applies the preset overrides to the Codex command.",
            "- For maximum rollback safety during bulk cleanup, run a dry plan first and migrate in small batches.",
        ]
        if preset.eol:
            lines.extend(["", f"Warning: this preset has EOL date {preset.eol}."])
        return lines

    async def show_selected_codex_model_plan(self) -> None:
        preset = self.selected_codex_model_preset()
        agent_id = self.codex_model_target_agent_id()
        if agent_id is None:
            return
        detail = self.query_one_or_none("#codex-config-detail", TextArea)
        if detail is None:
            detail = self.query_one_or_none("#detail", TextArea)
        ok, warning = await self.validate_codex_model_preset(preset)
        lines = self.codex_model_preset_plan_lines(agent_id, preset)
        lines.extend(
            [
                "",
                "Local validation:",
                f"- {'ok' if ok else 'blocked'}"
                + (f": {warning}" if warning else ""),
            ]
        )
        if detail is not None:
            detail.text = "\n".join(lines)
        self.activate_agent_tab("codex-tab")

    async def restart_selected_with_codex_model_preset(self) -> None:
        preset = self.selected_codex_model_preset()
        agent_id = self.codex_model_target_agent_id()
        if agent_id is None:
            return
        if preset.elevated:
            self.push_screen(ModelElevationScreen(agent_id=agent_id, preset=preset))
            return
        self.notify(f"Restarting {agent_id} with Codex model preset {preset.label}.")
        await self.restart_tmux_codex_session(agent_id, model_preset=preset)

    async def approve_and_restart_model_elevation(
        self,
        agent_id: str,
        preset: CodexModelPreset,
        justification: str,
    ) -> None:
        if not preset.elevated:
            self.notify(f"{preset.label} does not require elevation.", severity="warning")
            return
        if not await self.ensure_codex_model_preset_valid(preset):
            return
        agent = self.agents.get(agent_id) or {}
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        prior_profile = str(metadata.get("codex_model_preset") or "").strip() or None
        headers = auth_headers(self.token)
        try:
            requested = await self.api_client().post(
                "/v2/codex/elevations",
                json={
                    "agent_id": agent_id,
                    "requested_profile": "sol-max",
                    "prior_profile": prior_profile,
                    "justification": justification,
                    "scope": "one_task",
                },
                headers=headers,
            )
            requested.raise_for_status()
            lease = requested.json()
            decided = await self.api_client().post(
                f"/v2/codex/elevations/{lease['lease_id']}/decision",
                json={
                    "approved": True,
                    "approved_by": "agent-pbx-tui-user",
                    "duration_seconds": 3600,
                },
                headers=headers,
            )
            decided.raise_for_status()
        except Exception as exc:
            self.notify(f"Sol max approval failed: {exc}", severity="error")
            return
        self.notify(
            f"Approved bounded Sol max elevation for {agent_id}; restarting at the safe boundary."
        )
        await self.restart_tmux_codex_session(
            agent_id,
            model_preset=preset,
            model_elevation_lease_id=str(lease["lease_id"]),
        )

    async def activate_model_elevation_lease(
        self,
        lease_id: str,
        *,
        agent_id: str,
        preset: CodexModelPreset,
    ) -> bool:
        try:
            response = await self.api_client().post(
                f"/v2/codex/elevations/{lease_id}/activate",
                json={
                    "transition": {
                        "phase": "safe_boundary",
                        "requested_model": preset.model,
                        "requested_reasoning_effort": preset.reasoning_effort,
                    }
                },
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            lease = response.json()
        except Exception as exc:
            self.notify(f"Model elevation activation failed: {exc}", severity="error")
            return False
        if (
            str(lease.get("agent_id") or "") != agent_id
            or str(lease.get("requested_profile") or "") != "sol-max"
            or str(lease.get("status") or "") != "active"
            or bool(lease.get("expired"))
        ):
            self.notify("Model elevation lease did not match the target session.", severity="error")
            return False
        return True

    async def finish_model_elevation_lease(
        self,
        lease_id: str,
        *,
        status: str,
        transition: dict[str, object] | None = None,
    ) -> None:
        try:
            response = await self.api_client().post(
                f"/v2/codex/elevations/{lease_id}/finish",
                json={"status": status, "transition": transition or {}},
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
        except Exception as exc:
            self.notify(f"Unable to update model elevation lease: {exc}", severity="warning")

    async def save_selected_codex_model_preset_as_default(self) -> None:
        await self.save_codex_model_preset_as_default(self.selected_codex_model_preset())

    async def save_codex_model_preset_as_default(self, preset: CodexModelPreset) -> None:
        if preset.elevated:
            self.notify(
                "Sol max is a bounded elevation and cannot be saved as the global default.",
                severity="warning",
            )
            return
        if not await self.ensure_codex_model_preset_valid(preset):
            return
        updates: dict[str, str] = {
            "model": preset.model,
            "model_reasoning_effort": preset.reasoning_effort,
        }
        if preset.verbosity:
            updates["model_verbosity"] = preset.verbosity
        if preset.reasoning_summary:
            updates["model_reasoning_summary"] = preset.reasoning_summary
        payload: dict[str, object] = {"updates": updates}
        if not preset.reasoning_summary:
            payload["remove"] = ["model_reasoning_summary"]
        try:
            response = await self.api_client().patch(
                "/v1/codex/config",
                json=payload,
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Codex model default save failed: {exc}", severity="error")
            return
        config = result.get("config") if isinstance(result, dict) else None
        self.codex_config = config if isinstance(config, dict) else self.codex_config
        self.render_codex_config(self.codex_config)
        self.notify(f"Saved Codex default model preset {preset.label}.")
        await self.refresh_codex_posture()

    def codex_model_cleanup_targets(self) -> list[dict[str, Any]]:
        roots = {"operator-0", "operator-2", "operator-5"}
        targets: list[dict[str, Any]] = []
        seen: set[str] = set()
        for agent_id, agent in sorted(self.agents.items()):
            metadata = (
                agent.get("metadata")
                if isinstance(agent.get("metadata"), dict)
                else {}
            )
            logical_operator_id = self.logical_operator_id_for_agent(agent)
            include = False
            reason = ""
            if agent_id in self.starred_agent_ids:
                include = True
                reason = "starred"
            if agent_id in roots:
                include = True
                reason = "operator cleanup root"
            if logical_operator_id in roots and self.operator_role(agent) == OPERATOR_ROLE_FORK:
                include = True
                reason = f"{logical_operator_id} fork/review"
            if not include or agent_id in seen:
                continue
            seen.add(agent_id)
            hidden = self.is_hidden_agent(agent)
            active = bool(agent.get("pbx_active", True))
            targets.append(
                {
                    "agent_id": agent_id,
                    "reason": reason,
                    "hidden": hidden,
                    "pbx_active": active,
                    "status": agent.get("effective_status") or agent.get("status") or "",
                    "pane": self.tmux_agent_targets.get(agent_id)
                    or metadata.get("tmux_pane_id")
                    or "",
                    "cwd": metadata.get("work_root") or metadata.get("cwd") or "",
                    "session": metadata.get("fork_codex_session_id")
                    or metadata.get("last_resume_codex_session_id")
                    or metadata.get("codex_session_id")
                    or metadata.get("codex_thread_id")
                    or "",
                }
            )
        return targets

    async def show_codex_model_cleanup_plan(self) -> None:
        preset = self.selected_codex_model_preset()
        ok, warning = await self.validate_codex_model_preset(preset)
        targets = self.codex_model_cleanup_targets()
        lines = [
            "Codex Model Cleanup Dry Run",
            "",
            "Preset: "
            f"{preset.label} -> {preset.model}/{preset.reasoning_effort}"
            + (f", verbosity {preset.verbosity}" if preset.verbosity else ""),
            f"Validation: {'ok' if ok else 'blocked'}"
            + (f" ({warning})" if warning else ""),
            "",
            "Target policy:",
            "- Include visible starred agents.",
            "- Include Operators 0, 2, and 5.",
            "- Include active forks/review forks whose logical operator is 0, 2, or 5.",
            "- Skip hidden/inactive targets during execution unless explicitly selected.",
            "",
            "Backup/rollback before execution:",
            "- Copy Agent PBX SQLite state and TUI settings JSON with a timestamp.",
            "- Export target metadata, tmux pane ids, cwd, session ids, and transcript boundaries.",
            "- Keep old panes until replacement panes register and pass transcript/Joplin checks.",
            "",
            "Targets:",
        ]
        if not targets:
            lines.append("- none loaded")
        for item in targets:
            skip = " skip-hidden" if item["hidden"] else ""
            if not item["pbx_active"]:
                skip += " skip-inactive"
            lines.append(
                "- {agent_id} [{reason}] status={status} pane={pane} "
                "session={session} cwd={cwd}{skip}".format(
                    agent_id=item["agent_id"],
                    reason=item["reason"],
                    status=item["status"] or "-",
                    pane=item["pane"] or "-",
                    session=item["session"] or "-",
                    cwd=item["cwd"] or "-",
                    skip=skip,
                )
            )
        detail = self.query_one_or_none("#codex-config-detail", TextArea)
        if detail is None:
            detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = "\n".join(lines)
        self.activate_agent_tab("codex-tab")

    async def load_codex_config(self) -> None:
        status = self.query_one_or_none("#codex-config-status", Static)
        if status is not None:
            status.update("Codex config: loading...")
        try:
            response = await self.api_client().get(
                "/v1/codex/config",
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            payload = response.json()
        except Exception as exc:
            if status is not None:
                status.update(f"Codex config: unavailable ({exc})")
            detail = self.query_one_or_none("#codex-config-detail", TextArea)
            if detail is not None:
                detail.text = f"Codex config unavailable: {exc}"
            return
        self.codex_config = payload if isinstance(payload, dict) else {}
        self.render_codex_config(self.codex_config)

    def render_codex_config(self, payload: Mapping[str, Any] | None) -> None:
        config = payload or {}
        status = self.query_one_or_none("#codex-config-status", Static)
        if status is not None:
            warnings = config.get("warnings") if isinstance(config.get("warnings"), list) else []
            warning_suffix = f" | warnings {len(warnings)}" if warnings else ""
            exists = "present" if config.get("exists") else "not found"
            status.update(
                f"Codex config: {exists} | {config.get('path') or '-'}{warning_suffix}"
            )
        table = self.query_one_or_none("#codex-config-fields", DataTable)
        if table is not None:
            position = self.data_table_position(table)
            table.clear()
            for field in config.get("fields") or []:
                if not isinstance(field, dict):
                    continue
                key = str(field.get("key") or "")
                if not key:
                    continue
                value = str(field.get("value_preview") or field.get("value") or "")
                status_text = "set" if field.get("configured") else "unset"
                if field.get("sensitive"):
                    status_text = "hidden"
                table.add_row(key, value or "-", status_text, key=key)
            for item in config.get("hidden_items") or []:
                if not isinstance(item, dict):
                    continue
                key = str(item.get("key") or "")
                if not key:
                    continue
                value = str(item.get("value_preview") or "")
                status_text = str(item.get("policy") or "read_only")
                table.add_row(key, value or "-", status_text, key=f"hidden:{key}")
            self.restore_data_table_position(table, position)
        detail = self.query_one_or_none("#codex-config-detail", TextArea)
        if detail is not None:
            detail.text = self.format_codex_config_detail(config)

    def format_codex_config_detail(self, config: Mapping[str, Any]) -> str:
        lines = [
            "Codex Global Config",
            f"Path: {config.get('path') or '-'}",
            f"Status: {'present' if config.get('exists') else 'not found'}",
            "",
            "Editable safe keys:",
        ]
        editable = config.get("editable_paths") if isinstance(config.get("editable_paths"), list) else []
        lines.append(", ".join(str(item) for item in editable) if editable else "-")
        lines.extend(["", "Sensitive/read-only areas:"])
        hidden_items = config.get("hidden_items") if isinstance(config.get("hidden_items"), list) else []
        if hidden_items:
            for item in hidden_items:
                if not isinstance(item, dict):
                    continue
                configured = "configured" if item.get("configured") else "not configured"
                lines.append(
                    f"- {item.get('label') or item.get('key')}: {configured}; {item.get('policy')}"
                )
                reason = str(item.get("reason") or "").strip()
                if reason:
                    lines.append(f"  {reason}")
        else:
            lines.append("- none")
        lines.extend(["", "MCP servers:"])
        servers = config.get("mcp_servers") if isinstance(config.get("mcp_servers"), list) else []
        if servers:
            for server in servers:
                if not isinstance(server, dict):
                    continue
                parts = [str(server.get("name") or "-")]
                if server.get("url"):
                    parts.append(f"url={server.get('url')}")
                if server.get("command"):
                    parts.append(f"command={server.get('command')}")
                if server.get("bearer_token_env_var"):
                    parts.append(f"bearer_env={server.get('bearer_token_env_var')}")
                if server.get("http_headers"):
                    parts.append("http_headers=hidden")
                if server.get("env_keys"):
                    parts.append("env=hidden")
                lines.append("- " + " | ".join(parts))
        else:
            lines.append("- none")
        requirements = config.get("requirements") if isinstance(config.get("requirements"), list) else []
        present_requirements = [
            item for item in requirements if isinstance(item, dict) and item.get("exists")
        ]
        lines.extend(["", "Admin/managed config:"])
        if present_requirements:
            for item in present_requirements:
                keys = item.get("keys") if isinstance(item.get("keys"), list) else []
                lines.append(
                    f"- {item.get('kind')}: {item.get('path')} ({', '.join(str(key) for key in keys) or 'no keys'})"
                )
        else:
            lines.append("- none detected")
        warnings = config.get("warnings") if isinstance(config.get("warnings"), list) else []
        if warnings:
            lines.extend(["", "Warnings:"])
            lines.extend(f"- {warning}" for warning in warnings)
        secret_paths = (
            config.get("secret_update_paths")
            if isinstance(config.get("secret_update_paths"), list)
            else []
        )
        lines.extend(["", "Opaque secret replacement paths:"])
        lines.extend(f"- {path}" for path in secret_paths)
        keymap = config.get("keymap") if isinstance(config.get("keymap"), dict) else {}
        composer = keymap.get("composer") if isinstance(keymap.get("composer"), dict) else {}
        editor = keymap.get("editor") if isinstance(keymap.get("editor"), dict) else {}
        lines.extend(
            [
                "",
                "Managed keymap:",
                f"- preset: {keymap.get('preset') or 'default'}",
                "- submit: "
                + (", ".join(str(item) for item in composer.get("submit", [])) or "Codex default"),
                "- newline: "
                + (
                    ", ".join(str(item) for item in editor.get("insert_newline", []))
                    or "Codex default"
                ),
            ]
        )
        return "\n".join(lines)

    def format_effective_keymap(self) -> str:
        return "\n".join(
            [
                "Agent PBX and Codex Keymap",
                "",
                "PBX-owned under every focus:",
                "- F1 Agents · F2 Events · F3 right tabs · F4 input",
                "- F5 Operators · F6/F7 forks · F8 next alert · F9 editor · F10 launch",
                "- Ctrl+T toggles the selected Latest tmux surface",
                "- Ctrl+P command palette",
                "",
                "Codex terminal input:",
                "- Enter submit",
                "- Ctrl+J newline (portable canonical binding)",
                "- Shift+Enter / Alt+Enter / Ctrl+Enter -> Ctrl+J newline",
                "- Ctrl+A/E line start/end · Alt+B/F word movement",
                "- Ctrl+W/Alt+D delete word · Ctrl+U/K cut · Ctrl+Y yank",
                "- Escape cancel · Ctrl+C interrupt",
                "- Shift+F1..F12 -> child F1..F12",
                "",
                "Tmux history:",
                "- Page Up enters and scrolls runtime tmux copy mode",
                "- Up/Down and Page Up/Page Down navigate after entry",
                "- /tmux scrollback remains the explicit fallback",
                "",
                "Use /codex keymap to open Codex's native keymap viewer.",
            ]
        )

    async def apply_codex_keymap_preset(self, preset: str) -> bool:
        try:
            response = await self.api_client().patch(
                "/v1/codex/config",
                json={"keymap_preset": preset},
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Codex keymap update failed: {exc}", severity="error")
            return False
        config = result.get("config") if isinstance(result, dict) else None
        self.codex_config = config if isinstance(config, dict) else self.codex_config
        self.render_codex_config(self.codex_config)
        if preset == "portable":
            self.notify(
                "Saved the portable Codex keymap. Restart/resume running Codex "
                "sessions before relying on the new global bindings."
            )
        else:
            self.notify(
                "Removed Agent PBX Codex keymap overrides. Restart/resume running "
                "Codex sessions to reload defaults."
            )
        return True

    async def open_native_codex_keymap(self) -> bool:
        agent_id = str(self.selected_agent_id or "").strip()
        if not agent_id or not self.is_tmux_direct_enabled(agent_id):
            self.notify(
                "Select a tmux-direct Agent or Operator before opening Codex /keymap.",
                severity="warning",
            )
            return False
        if not await self.send_text_to_tmux(agent_id, "/keymap"):
            self.notify(
                "Unable to send /keymap to the selected Codex pane.",
                severity="error",
            )
            return False
        return True

    def select_codex_config_field(self, key: str) -> None:
        self.selected_codex_config_key = key
        if key.startswith("hidden:"):
            hidden_key = key.removeprefix("hidden:")
            self.show_codex_hidden_detail(hidden_key)
            return
        field = self.codex_config_field(key)
        if field is None:
            return
        key_input = self.query_one_or_none("#codex-config-key", Input)
        value_input = self.query_one_or_none("#codex-config-value", Input)
        if key_input is not None:
            key_input.value = key
        if value_input is not None:
            value_input.value = str(field.get("value") or "")
            value_input.focus()
        detail = self.query_one_or_none("#codex-config-detail", TextArea)
        if detail is not None:
            detail.text = self.format_codex_config_field_detail(field)

    def show_codex_hidden_detail(self, hidden_key: str) -> None:
        item = self.codex_config_hidden_item(hidden_key)
        if item is None:
            return
        detail = self.query_one_or_none("#codex-config-detail", TextArea)
        if detail is not None:
            lines = [
                str(item.get("label") or hidden_key),
                f"Policy: {item.get('policy') or 'read_only'}",
                f"Configured: {'yes' if item.get('configured') else 'no'}",
                "",
                str(item.get("reason") or ""),
            ]
            detail.text = "\n".join(lines).strip()

    def codex_config_field(self, key: str) -> dict[str, Any] | None:
        config = self.codex_config or {}
        fields = config.get("fields") if isinstance(config.get("fields"), list) else []
        for field in fields:
            if isinstance(field, dict) and field.get("key") == key:
                return field
        return None

    def codex_config_hidden_item(self, key: str) -> dict[str, Any] | None:
        config = self.codex_config or {}
        items = config.get("hidden_items") if isinstance(config.get("hidden_items"), list) else []
        for item in items:
            if isinstance(item, dict) and item.get("key") == key:
                return item
        return None

    def format_codex_config_field_detail(self, field: Mapping[str, Any]) -> str:
        lines = [
            str(field.get("label") or field.get("key") or "Codex field"),
            f"Key: {field.get('key') or '-'}",
            f"Configured: {'yes' if field.get('configured') else 'no'}",
            f"Editable: {'yes' if field.get('editable') else 'no'}",
            f"Value: {field.get('value_preview') or field.get('value') or '-'}",
            "",
            str(field.get("description") or ""),
        ]
        return "\n".join(lines).strip()

    async def save_codex_config_field(self) -> None:
        key_input = self.query_one_or_none("#codex-config-key", Input)
        value_input = self.query_one_or_none("#codex-config-value", Input)
        key = key_input.value.strip() if key_input is not None else ""
        value = value_input.value.strip() if value_input is not None else ""
        if not key:
            self.notify("Select or enter a Codex config key first.", severity="warning")
            return
        try:
            response = await self.api_client().patch(
                "/v1/codex/config",
                json={"updates": {key: value}},
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Codex config save failed: {exc}", severity="error")
            return
        config = result.get("config") if isinstance(result, dict) else None
        self.codex_config = config if isinstance(config, dict) else self.codex_config
        self.render_codex_config(self.codex_config)
        self.notify(f"Saved Codex config {key}.")

    async def remove_codex_config_field(self) -> None:
        key_input = self.query_one_or_none("#codex-config-key", Input)
        key = key_input.value.strip() if key_input is not None else ""
        if not key:
            self.notify("Select or enter a Codex config key first.", severity="warning")
            return
        try:
            response = await self.api_client().patch(
                "/v1/codex/config",
                json={"remove": [key]},
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Codex config remove failed: {exc}", severity="error")
            return
        config = result.get("config") if isinstance(result, dict) else None
        self.codex_config = config if isinstance(config, dict) else self.codex_config
        self.render_codex_config(self.codex_config)
        self.notify(f"Removed Codex config {key}.")

    async def wire_agent_pbx_mcp_config(self) -> None:
        try:
            response = await self.api_client().patch(
                "/v1/codex/config",
                json={
                    "agent_pbx_mcp": {
                        "url": agent_pbx_mcp_url(self.server),
                        "bearer_token_env_var": AGENT_PBX_TOKEN_ENV,
                        "default_tools_approval_mode": "approve",
                    }
                },
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Codex MCP config save failed: {exc}", severity="error")
            return
        config = result.get("config") if isinstance(result, dict) else None
        self.codex_config = config if isinstance(config, dict) else self.codex_config
        self.render_codex_config(self.codex_config)
        self.notify("Agent PBX MCP config written to global Codex config.")

    async def replace_codex_secret(self, *, remove: bool = False) -> None:
        path_input = self.query_one_or_none("#codex-secret-path", Input)
        value_input = self.query_one_or_none("#codex-secret-value", Input)
        secret_path = path_input.value.strip() if path_input is not None else ""
        secret_value = value_input.value if value_input is not None else ""
        if not secret_path:
            self.notify("Enter an opaque secret path first.", severity="warning")
            return
        if not remove and not secret_value:
            self.notify("Enter a new secret value first.", severity="warning")
            return
        patch: dict[str, object] = {"path": secret_path}
        if remove:
            patch["remove"] = True
        else:
            patch["value"] = secret_value
        try:
            response = await self.api_client().patch(
                "/v1/codex/config",
                json={"secret_updates": [patch]},
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Codex secret update failed: {exc}", severity="error")
            return
        if value_input is not None:
            value_input.value = ""
        config = result.get("config") if isinstance(result, dict) else None
        self.codex_config = config if isinstance(config, dict) else self.codex_config
        self.render_codex_config(self.codex_config)
        action = "Removed" if remove else "Replaced"
        self.notify(f"{action} opaque Codex secret path.")

    def format_codex_update_result(self, result: Mapping[str, Any]) -> list[str]:
        before = result.get("before") if isinstance(result.get("before"), dict) else {}
        after = result.get("after") if isinstance(result.get("after"), dict) else {}
        command = result.get("command") if isinstance(result.get("command"), list) else []
        lines = [
            "Codex CLI Update",
            f"Status: {'ok' if result.get('ok') else 'failed'}",
            f"Target: {result.get('target') or '-'}",
            f"Package: {result.get('package_spec') or '-'}",
            f"Command: {shlex.join([str(part) for part in command]) if command else '-'}",
            f"Return code: {result.get('returncode') if result.get('returncode') is not None else '-'}",
            f"Duration: {float_value(result.get('duration_seconds')) or 0.0:.1f}s",
            "",
            "Before:",
            f"  shell CLI: {before.get('shell_version') or '-'}",
            f"  app-server: {before.get('app_server_version') or '-'}",
            f"  latest stable: {before.get('latest_stable_version') or '-'}",
            f"  npm-managed: {before.get('npm_managed') if before.get('npm_managed') is not None else '-'}",
            "",
            "After:",
            f"  shell CLI: {after.get('shell_version') or '-'}",
            f"  app-server: {after.get('app_server_version') or '-'}",
            f"  latest stable: {after.get('latest_stable_version') or '-'}",
            f"  npm-managed: {after.get('npm_managed') if after.get('npm_managed') is not None else '-'}",
        ]
        if result.get("error"):
            lines.extend(["", f"Error: {result.get('error')}"])
        stdout = str(result.get("stdout") or "").strip()
        stderr = str(result.get("stderr") or "").strip()
        if stdout:
            lines.extend(["", "stdout:", stdout])
        if stderr:
            lines.extend(["", "stderr:", stderr])
        return lines

    def format_codex_posture(self, posture: CodexCliPosture | None) -> str:
        if posture is None:
            return "Codex: checking..."
        parts = [
            f"CLI {posture.shell_version or '-'}",
            f"app-server {posture.app_server_version or '-'}",
            f"latest {posture.latest_stable_version or '-'}",
        ]
        if posture.configured_model:
            marker = ""
            if posture.model_known is False:
                marker = " !"
            elif posture.model_known is None:
                marker = " ?"
            source = (
                f" via {posture.configured_model_source}"
                if posture.configured_model_source
                else ""
            )
            parts.append(f"model {posture.configured_model}{marker}{source}")
        if posture.model_catalog_count:
            parts.append(f"catalog {posture.model_catalog_count}")
        text = "Codex: " + " | ".join(parts)
        if posture.warnings:
            text += "\n" + "\n".join(f"Warning: {warning}" for warning in posture.warnings)
        return text

    def composer_hotkeys_text(self) -> str:
        nav = (
            "a Agents | e Events | v Tabs | i Input"
            if self.is_tiny_layout() or self.low_power_enabled
            else "F1 Agents | F2 Events | F3 Tabs | F4 Input"
        )
        text = f"{nav} | Shift+F2 Codex warnings | Enter send | Ctrl+J newline | Ctrl+W word"
        if self.tmux_features_available:
            text += " | Ctrl+T tmux | F8 alert"
        return text

    def tmux_hotkeys_text(self) -> str:
        if self.is_tiny_layout() or self.low_power_enabled:
            return (
                "a Agt | e Evt | v Tabs | i In | Shift+F2 Codex warnings | "
                "Enter send | C-J nl | PgUp hist | C-T PBX | F8 alert"
            )
        return (
            "F1 Agents | F2 Events | Shift+F2 Codex warnings | F3 Tabs | "
            "F4 Input | Ctrl+P Palette | Enter send | Ctrl+J newline | "
            "PgUp history | Ctrl+T PBX | F8 alert"
        )

    def editor_hotkeys_text(self) -> str:
        if self.is_tiny_layout() or self.low_power_enabled:
            return "F9 full | Save/Revert/Close buttons | copy path/text | check"
        return "F9 fullscreen | Save/Revert/Close buttons | Copy Path/Text | Check"

    def joplin_hotkeys_text(self) -> str:
        return JOPLIN_SHORTCUT_HINT

    def register_core_actions(self) -> None:
        """Describe global navigation once for keys, help, and the palette."""

        self.action_registry.extend(
            (
                ActionDefinition("focus.agents", "Agents", "f1"),
                ActionDefinition("focus.events", "Events", "f2"),
                ActionDefinition("focus.tabs", "Tabs", "f3"),
                ActionDefinition("focus.input", "Input", "f4"),
                ActionDefinition("focus.operators", "Operators", "f5"),
                ActionDefinition("operator.previous_fork", "Previous Fork", "f6"),
                ActionDefinition("operator.next_fork", "Next Fork", "f7"),
                ActionDefinition("terminal.toggle", "Tmux", "ctrl+t"),
                ActionDefinition("alerts.next", "Focus next alert", "f8"),
                ActionDefinition(
                    "terminal.scrollback",
                    "Enter tmux scrollback",
                    "pageup or /tmux scrollback",
                    focus_scope="terminal",
                    capability="terminal_input",
                ),
                ActionDefinition("editor.fullscreen", "Editor Full", "f9"),
                ActionDefinition("workspace.launch", "Launch Workspace", "f10"),
                ActionDefinition(
                    "terminal.function_key_passthrough",
                    "Codex function key",
                    f"{self.function_key_passthrough.modifier}+f1..f12",
                    focus_scope="terminal",
                    capability="terminal_input",
                ),
            )
        )

