    async def open_managed_project_picker(self) -> None:
        try:
            response = await self.api_client().get(
                "/v2/projects/discover",
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            payload = response.json()
        except Exception as exc:
            self.notify(f"Unable to discover managed projects: {exc}", severity="error")
            return
        projects = payload.get("projects") if isinstance(payload, dict) else []
        roots = payload.get("roots") if isinstance(payload, dict) else []
        if not isinstance(projects, list) or not projects:
            root_text = ", ".join(str(item) for item in roots) if isinstance(roots, list) else ""
            self.notify(
                "No Git projects were found in approved roots"
                + (f": {root_text}." if root_text else ".")
                + " Configure AGENT_PBX_PROJECT_ROOTS in the daemon environment "
                "and restart the daemon after changing it.",
                severity="warning",
            )
            return
        self.push_screen(
            ManagedProjectPickerScreen(
                [item for item in projects if isinstance(item, dict)],
                [str(item) for item in roots] if isinstance(roots, list) else [],
            )
        )

    async def launch_managed_agent_from_picker(
        self,
        *,
        project_path: str,
        agent_id: str,
        profile_id: str,
        runtime_server_mode: str,
    ) -> bool:
        request = {
            "project_path": project_path,
            "agent_id": agent_id.strip(),
            "profile_id": profile_id,
            "runtime_server_mode": runtime_server_mode,
        }
        try:
            preview = await self.api_client().post(
                "/v2/agents/managed-launch/preview",
                json=request,
                headers=auth_headers(self.token),
                timeout=30,
            )
            preview.raise_for_status()
            launched = await self.api_client().post(
                "/v2/agents/managed-launch",
                json=request,
                headers=auth_headers(self.token),
                timeout=45,
            )
            launched.raise_for_status()
            payload = launched.json()
        except Exception as exc:
            self.notify(f"Managed Agent launch failed: {exc}", severity="error")
            return False
        launched_agent = payload.get("agent") if isinstance(payload, dict) else None
        mapping = payload.get("runtime_mapping") if isinstance(payload, dict) else None
        if not isinstance(launched_agent, dict) or not isinstance(mapping, dict):
            self.notify("Managed launch returned incomplete identity data.", severity="error")
            return False
        launched_id = str(launched_agent.get("agent_id") or "")
        self.agents[launched_id] = launched_agent
        self.tmux_runtime_mapping_by_agent[launched_id] = mapping
        self.tmux_agent_targets[launched_id] = str(mapping.get("pane_id") or "")
        self.tmux_direct_agent_modes[launched_id] = True
        self.tmux_detached_agent_ids.discard(launched_id)
        self.save_settings()
        await self.refresh_agents()
        await self.select_agent(launched_id)
        self.notify(
            f"Launched {launched_id} on {payload.get('model')} in {project_path}."
        )
        return True

    def managed_workspace_caller_owner(
        self,
        owner_ids: Iterable[str],
    ) -> str | None:
        callers = sorted(
            {
                str(owner_id)
                for owner_id in owner_ids
                if str(owner_id) in self.agents
                and self.agent_type(self.agents[str(owner_id)]) == CALLER_AGENT_TYPE
            }
        )
        return callers[0] if len(callers) == 1 else None

    async def wait_for_managed_caller_registration(
        self,
        agent_id: str,
        *,
        timeout_seconds: float = 30.0,
    ) -> bool:
        deadline = asyncio.get_running_loop().time() + max(0.1, timeout_seconds)
        while True:
            try:
                response = await self.api_client().get(
                    "/v1/agents",
                    params={"include_hidden": "true"},
                    headers=auth_headers(self.token),
                    timeout=10,
                )
                response.raise_for_status()
                payload = response.json()
            except Exception:
                payload = []
            for item in payload if isinstance(payload, list) else []:
                if not isinstance(item, dict) or item.get("agent_id") != agent_id:
                    continue
                self.agents[agent_id] = item
                if self.operator_fork_start_blocker(agent_id) is None:
                    return True
            if asyncio.get_running_loop().time() >= deadline:
                return False
            await asyncio.sleep(0.5)

    async def launch_managed_workspace_from_picker(
        self,
        *,
        project_path: str,
        agent_id: str,
        profile_id: str,
        runtime_server_mode: str,
        launch_mode: str,
        existing_owner_ids: Iterable[str] = (),
    ) -> bool:
        mode = str(launch_mode or "agent").strip().lower()
        if mode not in {"agent", "agent_operator"}:
            self.notify(f"Unknown workspace launch mode: {launch_mode}", severity="error")
            return False

        owners = [str(owner) for owner in existing_owner_ids if str(owner)]
        caller_id = self.managed_workspace_caller_owner(owners)
        if owners and caller_id is None:
            self.notify(
                "The project has no unique caller Agent owner; select the intended "
                "caller before starting an Operator.",
                severity="error",
            )
            return False
        if caller_id is None:
            launched = await self.launch_managed_agent_from_picker(
                project_path=project_path,
                agent_id=agent_id,
                profile_id=profile_id,
                runtime_server_mode=runtime_server_mode,
            )
            if not launched:
                return False
            caller_id = self.selected_agent_id
        elif caller_id in self.agents:
            await self.select_agent(caller_id)
            self.notify(f"Using existing caller Agent {caller_id} for this workspace.")

        if mode == "agent":
            return True
        if not caller_id:
            self.notify("Managed launch did not return a caller Agent id.", severity="error")
            return False

        if self.operator_fork_start_blocker(caller_id) is not None:
            bootstrap = (
                "Use Agent PBX in report mode. Register this Codex session under "
                f"the existing Agent PBX id `{caller_id}`, send a waiting report, "
                "then stop at the Codex prompt. This is startup registration only; "
                "do not begin project work."
            )
            if not await self.send_text_to_tmux(caller_id, bootstrap):
                self.notify(
                    f"Agent {caller_id} launched, but startup registration could not "
                    "be sent. Select it and use /operator start after it registers.",
                    severity="warning",
                )
                return True
            self.notify(
                f"Waiting for {caller_id} to publish its Codex session before "
                "starting the Operator."
            )
            if not await self.wait_for_managed_caller_registration(caller_id):
                self.notify(
                    f"Agent {caller_id} is running, but its Codex session has not "
                    "registered yet. Use /operator start after registration completes.",
                    severity="warning",
                )
                return True

        await self.start_operator_agent(source_caller_agent_id=caller_id)
        return True

    async def preview_selected_agent_pane_adoption(self) -> dict[str, Any] | None:
        agent_id = str(self.selected_agent_id or "").strip()
        agent = self.agents.get(agent_id)
        if not agent_id or not isinstance(agent, dict):
            self.notify("Select a caller Agent first.", severity="warning")
            return None
        if self.agent_type(agent) != CALLER_AGENT_TYPE:
            self.notify("Native pane adoption applies to caller Agents.", severity="warning")
            return None
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception as exc:
            self.notify(f"Unable to inspect tmux panes: {exc}", severity="error")
            return None
        pane, _mode = self.resolve_tmux_pane(agent_id, panes)
        if pane is None:
            self.notify(f"No live tmux pane is selected for {agent_id}.", severity="warning")
            return None
        outer = await asyncio.to_thread(read_outer_tmux_context, self.tmux_runtime_server)
        payload = {
            "agent_id": agent_id,
            "pane_id": pane.pane_id,
            "runtime_server_mode": self.tmux_runtime_server_mode,
            "destination_session": "agent-pbx-agents",
            "origin_session_name": outer.session_name if outer else None,
            "origin_client_tty": outer.client_tty if outer else None,
            "retention_days": 7,
        }
        try:
            response = await self.api_client().post(
                "/v2/agent-pane-adoptions/preview",
                json=payload,
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            batch = response.json()
        except Exception as exc:
            self.notify(f"Native Agent adoption preview failed: {exc}", severity="error")
            return None
        self.latest_agent_pane_adoption_batch = batch
        plan = batch.get("plan") if isinstance(batch.get("plan"), dict) else {}
        source = plan.get("source") if isinstance(plan.get("source"), dict) else {}
        lines = [
            f"Native Agent pane adoption: {agent_id}",
            "",
            f"Eligible: {'yes' if plan.get('eligible') else 'no'}",
            f"Pane: {plan.get('pane_id') or '-'}",
            f"Codex session: {plan.get('codex_session_id') or '-'}",
            f"Source: {source.get('session_name') or '-'}:{source.get('window_id') or '-'}",
            f"Destination: {plan.get('destination_session')}:{plan.get('destination_window_name')}",
            "Process action: move existing pane; no Codex restart",
            "Final state: popped in",
            "",
            "Blockers:",
            *([f"- {item}" for item in plan.get("blockers", [])] or ["- none"]),
            "",
            "Warnings:",
            *([f"- {item}" for item in plan.get("warnings", [])] or ["- none"]),
        ]
        detail = self.query_one_or_none("#codex-config-detail", TextArea)
        if detail is None:
            detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = "\n".join(lines)
        self.notify(
            f"Native adoption preview for {agent_id}: "
            f"{'eligible' if plan.get('eligible') else 'blocked'}."
        )
        return batch

    async def apply_selected_agent_pane_adoption(self) -> bool:
        batch = self.latest_agent_pane_adoption_batch or {}
        batch_id = str(batch.get("batch_id") or "")
        if not batch_id:
            self.notify("Preview native Agent adoption first.", severity="warning")
            return False
        plan = batch.get("plan") if isinstance(batch.get("plan"), dict) else {}
        agent_id = str(plan.get("agent_id") or "")
        if agent_id != self.selected_agent_id:
            self.notify(
                "The reviewed adoption belongs to another Agent; preview again.",
                severity="warning",
            )
            return False
        if not plan.get("eligible"):
            self.notify("The reviewed native adoption is blocked.", severity="error")
            return False
        await self.detach_embedded_tmux_terminal(release_lease=True)
        try:
            response = await self.api_client().post(
                f"/v2/agent-pane-adoptions/{quote(batch_id, safe='')}/apply",
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            payload = response.json()
        except Exception as exc:
            self.notify(f"Native Agent adoption failed: {exc}", severity="error")
            return False
        self.latest_agent_pane_adoption_batch = payload.get("batch", batch)
        result = payload.get("result") if isinstance(payload.get("result"), dict) else {}
        mapping = result.get("mapping") if isinstance(result.get("mapping"), dict) else {}
        pane_id = str(result.get("pane_id") or mapping.get("pane_id") or "")
        if pane_id:
            self.tmux_agent_targets[agent_id] = pane_id
        self.tmux_direct_agent_modes[agent_id] = True
        self.tmux_manual_override_agent_ids.add(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        if mapping:
            self.tmux_runtime_mapping_by_agent[agent_id] = mapping
        self.tmux_runtime_mapping_signature_by_agent.pop(agent_id, None)
        self.save_settings()
        await self.refresh_agents()
        await self.refresh_tmux_stream()
        self.notify(f"Adopted {agent_id} into native tmux; state is popped in.")
        return True

    async def rollback_selected_agent_pane_adoption(self) -> bool:
        batch = self.latest_agent_pane_adoption_batch or {}
        batch_id = str(batch.get("batch_id") or "")
        if not batch_id:
            self.notify("No native Agent adoption is available to restore.", severity="warning")
            return False
        await self.detach_embedded_tmux_terminal(release_lease=True)
        try:
            response = await self.api_client().post(
                f"/v2/agent-pane-adoptions/{quote(batch_id, safe='')}/rollback",
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            payload = response.json()
        except Exception as exc:
            self.notify(f"Native Agent placement restore failed: {exc}", severity="error")
            return False
        self.latest_agent_pane_adoption_batch = payload.get("batch", batch)
        self.tmux_runtime_mapping_by_agent.clear()
        self.tmux_runtime_mapping_validated_at_by_agent.clear()
        self.tmux_runtime_mapping_signature_by_agent.clear()
        await self.refresh_agents()
        await self.refresh_tmux_stream()
        result = payload.get("result") if isinstance(payload.get("result"), dict) else {}
        self.notify(f"Restored {result.get('agent_id') or 'Agent'} to its source tmux layout.")
        return True

    async def preview_runtime_migration(self) -> dict[str, Any] | None:
        target_version = self.codex_posture.shell_version if self.codex_posture else ""
        await self.prepare_runtime_migration_mappings()
        try:
            response = await self.api_client().post(
                "/v2/runtime-migrations/preview",
                json={
                    "include_starred": True,
                    "include_operators": True,
                    "target_cli_version": target_version,
                    "retention_days": 7,
                },
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            batch = response.json()
        except Exception as exc:
            self.notify(f"Runtime migration preview failed: {exc}", severity="error")
            return None
        self.latest_runtime_migration_batch = batch
        self.push_screen(RuntimeMigrationScreen(batch))
        return batch

    async def prepare_runtime_migration_mappings(self) -> None:
        """Refresh legacy outer-server mappings before asking the daemon to preview."""

        await self.refresh_agents()
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception:
            return
        self.tmux_panes = panes
        for agent_id, agent in self.agents.items():
            if not (
                bool(agent.get("starred"))
                or self.agent_type(agent) == OPERATOR_AGENT_TYPE
            ):
                continue
            pane, _mode = self.resolve_tmux_pane(agent_id, panes)
            if pane is not None:
                await self.ensure_tmux_runtime_mapping(agent_id, pane)

    async def apply_runtime_migration_batch(
        self,
        batch: dict[str, Any],
    ) -> list[dict[str, Any]]:
        candidates = batch.get("candidates")
        results: list[dict[str, Any]] = []
        await self.detach_embedded_tmux_terminal(release_lease=True)
        for item in candidates if isinstance(candidates, list) else []:
            if not isinstance(item, dict):
                continue
            agent_id = str(item.get("agent_id") or "")
            if not item.get("eligible"):
                results.append(
                    {
                        "agent_id": agent_id,
                        "status": "skipped",
                        "reason": "; ".join(str(value) for value in item.get("blockers", [])),
                    }
                )
                continue
            self.tmux_direct_agent_modes[agent_id] = True
            mapping = item.get("mapping")
            if isinstance(mapping, dict):
                self.tmux_runtime_mapping_by_agent[agent_id] = mapping
                self.tmux_agent_targets[agent_id] = str(mapping.get("pane_id") or "")
            self.runtime_migration_error_by_agent.pop(agent_id, None)
            try:
                target_server_id = self.tmux_runtime_server.server_id
                restart_in_place = bool(
                    isinstance(mapping, dict)
                    and str(mapping.get("state") or "") == "ready"
                    and str(mapping.get("server_id") or "") == target_server_id
                )
                restarted = (
                    await self.restart_tmux_codex_session(agent_id)
                    if restart_in_place
                    else await self.resume_tmux_codex_in_managed_runtime(agent_id)
                )
            except Exception as exc:
                reason = str(exc)
                self.runtime_migration_error_by_agent[agent_id] = reason
                results.append({"agent_id": agent_id, "status": "failed", "error": reason})
            else:
                result = {
                    "agent_id": agent_id,
                    "status": "complete" if restarted else "failed",
                }
                if not restarted:
                    result["error"] = self.runtime_migration_error_by_agent.get(
                        agent_id,
                        "runtime restart or resume returned false without a diagnostic",
                    )
                results.append(result)
        batch_id = str(batch.get("batch_id") or "")
        try:
            response = await self.api_client().post(
                f"/v2/runtime-migrations/{quote(batch_id, safe='')}/results",
                json={"results": results},
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            self.latest_runtime_migration_batch = response.json()
        except Exception as exc:
            self.notify(f"Migration results could not be recorded: {exc}", severity="error")
            return results
        completed = sum(item.get("status") == "complete" for item in results)
        failed = sum(item.get("status") == "failed" for item in results)
        self.save_settings()
        self.notify(f"Runtime migration finished: {completed} complete, {failed} failed.")
        return results

    async def rollback_runtime_migration_batch(self, batch_id: str) -> bool:
        try:
            response = await self.api_client().post(
                f"/v2/runtime-migrations/{quote(batch_id, safe='')}/rollback",
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            payload = response.json()
        except Exception as exc:
            self.notify(f"Runtime mapping restore failed: {exc}", severity="error")
            return False
        restored = payload.get("restored") if isinstance(payload, dict) else []
        self.tmux_runtime_mapping_by_agent.clear()
        self.tmux_runtime_mapping_validated_at_by_agent.clear()
        self.tmux_runtime_mapping_signature_by_agent.clear()
        await self.refresh_agents()
        self.notify(f"Restored {len(restored) if isinstance(restored, list) else 0} runtime snapshots.")
        return True

