    def on_key(self, event: Key) -> None:
        thread = self.query_one_or_none("#thread", DataTable)
        try:
            focused = self.focused
        except ScreenStackError:
            focused = None
        if self.handle_function_key_passthrough(event, focused=focused):
            return
        if self.handle_joplin_shortcut_key(event, focused=focused):
            return
        if event.key == "space" and thread is not None and focused is thread:
            event.stop()
            self.toggle_current_thread_mark()
            return
        if isinstance(focused, (Input, FollowUpTextArea)):
            self.clear_agent_jump_prefix()
            return
        if self.handle_agent_jump_key(event):
            return
        if event.character == "[":
            event.stop()
            self.adjust_split_percent(-SPLIT_PERCENT_STEP)
            return
        if event.character == "]":
            event.stop()
            self.adjust_split_percent(SPLIT_PERCENT_STEP)
            return
        if event.character == "0":
            event.stop()
            self.reset_split_percent()
            return
        if self.handle_focus_shortcut_key(event):
            return

    def handle_function_key_passthrough(
        self,
        event: Key,
        *,
        focused: Widget | None = None,
    ) -> bool:
        if self.active_agent_tab != "latest-tab" or not self.selected_agent_id:
            return False
        focused_id = str(getattr(focused, "id", "") or "")
        if focused_id not in {"tmux-stream", "pbx-terminal-surface"}:
            return False
        translated = self.function_key_passthrough.translate(
            [event.key, getattr(event, "name", ""), *(event.aliases or [])]
        )
        if translated is None:
            return False
        event.stop()
        event.prevent_default()
        terminal = self.query_one_or_none(
            "#pbx-terminal-surface", PbxTerminalSurface
        )
        if (
            focused_id == "pbx-terminal-surface"
            and terminal is not None
            and terminal.attached
            and terminal.write(translated.sequence)
        ):
            return True
        self.run_worker(
            self.send_key_to_tmux(
                self.selected_agent_id,
                translated.child_key.upper(),
            ),
            name=f"terminal-{translated.child_key}-passthrough",
            exclusive=False,
        )
        return True

    def on_descendant_focus(self, event: DescendantFocus) -> None:
        self.focus_generation.changed()
        focused_id = str(event.widget.id or "")
        released_order_lock = False
        if focused_id == "agents":
            table = self.query_one_or_none("#agents", DataTable)
            if table is not None and self.agent_table_order_lock is None:
                self.agent_table_order_lock = self.table_agent_order(table)
        elif self.agent_table_order_lock is not None:
            self.agent_table_order_lock = None
            released_order_lock = True
        if focused_id == "operators":
            table = self.query_one_or_none("#operators", DataTable)
            if table is not None and self.operator_table_order_lock is None:
                self.operator_table_order_lock = self.table_agent_order(table)
        elif self.operator_table_order_lock is not None:
            self.operator_table_order_lock = None
            released_order_lock = True
        if released_order_lock:
            self.call_after_refresh(self.render_agents)

    def handle_joplin_shortcut_key(
        self,
        event: Key,
        *,
        focused: Widget | None = None,
    ) -> bool:
        if self.active_agent_tab != "joplin-tab":
            self.joplin_shortcut_pending = False
            return False
        key_names = normalized_key_names(event)
        key = str(event.character or event.key or "").lower()
        editable_focus = isinstance(focused, (Input, TextArea)) and not bool(
            getattr(focused, "read_only", False)
        )
        starts_prefix = "ctrl+g" in key_names or "c-g" in key_names
        if not starts_prefix and key == "j" and not editable_focus:
            starts_prefix = True
        if starts_prefix:
            event.stop()
            event.prevent_default()
            self.joplin_shortcut_pending = True
            self.notify(JOPLIN_SHORTCUT_HINT)
            return True
        if not self.joplin_shortcut_pending:
            return False
        event.stop()
        event.prevent_default()
        self.joplin_shortcut_pending = False
        if event.key == "escape":
            self.notify("Joplin shortcut canceled.")
            return True
        action = JOPLIN_SHORTCUT_ACTIONS.get(key)
        if action is None:
            self.notify(f"Unknown Joplin shortcut {key!r}.", severity="warning")
            return True
        agent_id = self.joplin_target_agent_id(focused=focused)
        if not agent_id:
            self.notify("Select an agent first.", severity="warning")
            return True
        action_name, label = action
        self.run_worker(
            self.joplin_action_for_agent(agent_id, action_name),
            name=f"joplin-shortcut-{slugify(action_name)}",
            exclusive=True,
        )
        self.notify(f"Joplin {label} requested for {agent_id}.")
        return True

    def handle_focus_shortcut_key(self, event: Key) -> bool:
        key = str(event.character or event.key or "").lower()
        if key == "a":
            event.stop()
            event.prevent_default()
            self.action_focus_agents()
            return True
        if key == "o":
            event.stop()
            event.prevent_default()
            self.action_focus_operators()
            return True
        if key == "e":
            event.stop()
            event.prevent_default()
            self.action_focus_events()
            return True
        if key == "v":
            event.stop()
            event.prevent_default()
            self.run_worker(
                self.action_focus_right_pane(),
                name="key-focus-right-pane",
                exclusive=True,
            )
            return True
        if key == "i":
            event.stop()
            event.prevent_default()
            self.run_worker(
                self.action_focus_latest_input(),
                name="key-focus-latest-input",
                exclusive=True,
            )
            return True
        return False

    def on_mouse_down(self, event: MouseDown) -> None:
        target = self.mouse_focus_target(event)
        self.log_mouse_event("mouse_down", event, target)
        if target is None or event.button not in {0, 1}:
            return
        try:
            target.focus()
        except Exception:
            return

    async def on_click(self, event: Click) -> None:
        self.log_mouse_event("click", event, self.mouse_focus_target(event))
        if getattr(event.widget, "id", None) == "attention":
            opened = await self.open_attention_latest()
            if opened:
                event.stop()

    def mouse_focus_target(self, event: MouseDown | Click) -> Widget | None:
        widget = event.widget
        if widget is None:
            return None
        for candidate in self.widget_ancestry(widget):
            candidate_id = getattr(candidate, "id", None)
            if isinstance(
                candidate,
                (Button, Checkbox, DataTable, Input, RichLog, Select, TextArea),
            ):
                return candidate
            if candidate_id in MOUSE_FOCUS_TARGET_IDS and getattr(
                candidate, "can_focus", False
            ):
                return candidate
            selector = self.mouse_focus_container_selector(candidate_id)
            if selector is not None:
                target = self.query_one_or_none(selector, Widget)
                if target is not None:
                    return target
        return None

    def widget_ancestry(self, widget: Widget) -> Iterable[Widget]:
        current: Any = widget
        while isinstance(current, Widget):
            yield current
            current = getattr(current, "parent", None)

    def mouse_focus_container_selector(self, widget_id: str | None) -> str | None:
        if widget_id == "latest-tab" and self.is_tmux_direct_enabled():
            return "#tmux-stream"
        return MOUSE_FOCUS_CONTAINER_TARGETS.get(widget_id or "")

    def log_mouse_event(
        self,
        event_name: str,
        event: MouseDown | Click,
        target: Widget | None,
    ) -> None:
        if not self.mouse_debug_enabled:
            return
        widget_id = getattr(event.widget, "id", None) or type(event.widget).__name__
        target_id = getattr(target, "id", None) if target is not None else None
        self.log(
            f"{event_name} widget={widget_id} target={target_id} "
            f"button={event.button} x={event.x} y={event.y} "
            f"screen_x={event.screen_x} screen_y={event.screen_y}"
        )

    def on_text_area_changed(self, event: TextArea.Changed) -> None:
        if self.selected_agent_id and event.text_area.id == "message":
            self.message_draft_by_agent[self.selected_agent_id] = event.text_area.text
        if event.text_area.id == "message":
            self.resize_message_input()
        if self.selected_agent_id and event.text_area.id == "tmux-message":
            self.tmux_message_draft_by_agent[self.selected_agent_id] = (
                event.text_area.text
            )
        if self.selected_agent_id and event.text_area.id == "editor":
            self.update_editor_dirty_state(self.selected_agent_id)
        if (
            self.selected_agent_id
            and event.text_area.id == "joplin-body"
            and not self.joplin_body_loading
        ):
            scope = self.joplin_selection_key(self.selected_agent_id)
            draft = self.joplin_panel_state.update_draft(scope, event.text_area.text)
            if draft is not None:
                self.schedule_joplin_draft_persist(self.selected_agent_id)

    async def on_input_submitted(self, event: Input.Submitted) -> None:
        if event.input.id == "files-search-query":
            event.stop()
            if self.selected_agent_id:
                await self.search_agent_files(self.selected_agent_id, event.value)

    def set_agent_draft_text(
        self,
        agent_id: str,
        text_area: TextArea,
        text: str,
    ) -> None:
        text_area.text = text
        if text_area.id == "message":
            self.message_draft_by_agent[agent_id] = text
            self.resize_message_input()
        elif text_area.id == "tmux-message":
            self.tmux_message_draft_by_agent[agent_id] = text

    def sent_history_agent_id(self, text_area: TextArea) -> str | None:
        if text_area.id == "tmux-message":
            agent_id = self.selected_agent_id
            if agent_id:
                return agent_id
        agent_input = self.query_one_or_none("#agent-id", Input)
        if agent_input is not None and agent_input.value.strip():
            return agent_input.value.strip()
        return self.selected_agent_id

    def record_sent_message(self, agent_id: str, message: str) -> None:
        if not message.strip():
            return
        history = self.sent_message_history_by_agent.setdefault(agent_id, [])
        if not history or history[-1] != message:
            history.append(message)
        if len(history) > SENT_MESSAGE_HISTORY_LIMIT:
            del history[: len(history) - SENT_MESSAGE_HISTORY_LIMIT]
        self.sent_message_history_cursor = {
            key: value
            for key, value in self.sent_message_history_cursor.items()
            if key[0] != agent_id
        }

    def recall_sent_message(self, text_area: TextArea, *, direction: int) -> bool:
        agent_id = self.sent_history_agent_id(text_area)
        if not agent_id:
            return False
        history = self.sent_message_history_by_agent.get(agent_id) or []
        if not history:
            return False
        input_id = text_area.id or "message"
        key = (agent_id, input_id)
        current = self.sent_message_history_cursor.get(key)
        current_text = text_area.text
        if current is None:
            if current_text.strip():
                return False
            next_index = len(history) - 1
        elif 0 <= current < len(history) and current_text == history[current]:
            next_index = current + direction
            if next_index >= len(history):
                self.set_agent_draft_text(agent_id, text_area, "")
                self.sent_message_history_cursor.pop(key, None)
                return True
            next_index = max(0, next_index)
        elif current_text.strip():
            return False
        else:
            next_index = len(history) - 1
        text_area.text = history[next_index]
        last_line = text_area.text.split("\n")[-1]
        text_area.move_cursor((text_area.text.count("\n"), len(last_line)))
        self.sent_message_history_cursor[key] = next_index
        if text_area.id == "message":
            self.resize_message_input()
        return True

    def slash_command_entries(self) -> list[SystemCommand]:
        entries: list[SystemCommand] = []
        seen: set[str] = set()
        for command in self.get_system_commands(self.screen):
            title = command.title.strip()
            key = title.lower()
            if not title.startswith("/") or key in seen:
                continue
            seen.add(key)
            entries.append(command)
        return entries

    def slash_command_titles(self) -> list[str]:
        return [command.title for command in self.slash_command_entries()]

    def slash_command_for_text(self, text: str) -> SystemCommand | None:
        stripped = text.strip()
        if not stripped or "\n" in stripped:
            return None
        for command in self.slash_command_entries():
            if command.title.lower() == stripped.lower():
                return command
        return None

    def file_completion_context(
        self,
        text_area: TextArea,
    ) -> FileCompletionContext | None:
        input_id = text_area.id or "message"
        row, column = text_area.cursor_location
        lines = text_area.text.split("\n")
        if row < 0 or row >= len(lines):
            return None
        line = lines[row]
        column = min(max(0, column), len(line))
        start_col = line.rfind("@", 0, column)
        if start_col < 0:
            return None
        before = line[start_col:column]
        if any(char.isspace() for char in before):
            return None
        if start_col > 0 and not line[start_col - 1].isspace():
            if line[start_col - 1] not in "([{'\"`":
                return None
        end_col = column
        while end_col < len(line) and not line[end_col].isspace():
            end_col += 1
        prefix = line[start_col:column]
        split = split_file_completion_prefix(prefix[1:])
        if split is None:
            return None
        directory, name_prefix = split
        return FileCompletionContext(
            input_id=input_id,
            line=row,
            start_col=start_col,
            end_col=end_col,
            prefix=prefix,
            directory=directory,
            name_prefix=name_prefix,
        )

    def file_completion_matches(
        self,
        context: FileCompletionContext,
        agent_id: str,
    ) -> tuple[str, ...]:
        entries = self.file_directory_entries_by_agent.get(agent_id, {}).get(
            context.directory
        )
        if not entries:
            return ()
        prefix_key = context.name_prefix.lower()
        candidates: list[tuple[int, str]] = []
        seen: set[str] = set()
        for entry in entries.values():
            if not isinstance(entry, dict):
                continue
            name = str(entry.get("name") or "")
            if not name or name == ".." or not name.lower().startswith(prefix_key):
                continue
            path = normalize_project_path(str(entry.get("path") or name))
            if path is None:
                continue
            is_directory = entry.get("kind") == "directory"
            completion = f"@{path}{'/' if is_directory else ''}"
            if completion in seen:
                continue
            seen.add(completion)
            candidates.append((0 if is_directory else 1, completion))
        candidates.sort(key=lambda item: (item[0], item[1].lower()))
        return tuple(completion for _kind, completion in candidates)

    def joplin_note_completion_matches(
        self,
        context: FileCompletionContext,
        agent_id: str,
    ) -> tuple[str, ...]:
        cache_agent_id = self.joplin_note_cache_agent_id(agent_id)
        notes = self.joplin_notes_by_agent.get(cache_agent_id, {})
        if not notes:
            return ()
        prefix_key = context.prefix.lower()
        return tuple(
            token
            for token in joplin_note_ref_completion_tokens(notes.values())
            if token.lower().startswith(prefix_key)
        )

    def caller_agent_completion_matches(
        self,
        context: FileCompletionContext,
        agent_id: str,
    ) -> tuple[str, ...]:
        if not self.is_operator_agent_id(agent_id):
            return ()
        prefix_key = context.prefix.lower()
        return tuple(
            token
            for token in caller_agent_ref_completion_tokens(self.caller_agents())
            if token.lower().startswith(prefix_key)
        )

    def pull_request_completion_matches(
        self,
        context: FileCompletionContext,
        agent_id: str,
    ) -> tuple[str, ...]:
        repo_agent_id = self.repo_scope_agent_id(agent_id)
        pulls = self.pull_requests_by_agent.get(repo_agent_id) or self.pull_requests_by_agent.get(
            agent_id,
            {},
        )
        if not pulls:
            return ()
        prefix_key = context.prefix.lower()
        return tuple(
            token
            for token in pull_request_ref_completion_tokens(pulls.values())
            if token.lower().startswith(prefix_key)
        )

    def issue_completion_matches(
        self,
        context: FileCompletionContext,
        agent_id: str,
    ) -> tuple[str, ...]:
        repo_agent_id = self.repo_scope_agent_id(agent_id)
        issues = self.issues_by_agent.get(repo_agent_id) or self.issues_by_agent.get(
            agent_id,
            {},
        )
        if not issues:
            return ()
        prefix_key = context.prefix.lower()
        return tuple(
            token
            for token in issue_ref_completion_tokens(issues.values())
            if token.lower().startswith(prefix_key)
        )

    def project_for_agent(self, agent_id: str) -> str:
        agent = self.agents.get(agent_id)
        if isinstance(agent, dict) and agent.get("project"):
            return str(agent["project"])
        return agent_id

    def joplin_scope_agent_id(self, agent_id: str) -> str:
        agent = self.agents.get(agent_id)
        if (
            isinstance(agent, dict)
            and self.agent_type(agent) == OPERATOR_AGENT_TYPE
            and self.operator_role(agent) == OPERATOR_ROLE_FORK
        ):
            metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
            source_agent_id = str(metadata.get("source_caller_agent_id") or "").strip()
            if source_agent_id:
                return source_agent_id
        return agent_id

    def joplin_note_cache_agent_id(self, agent_id: str) -> str:
        return self.joplin_scope_agent_id(agent_id)

    def joplin_project_for_agent(self, agent_id: str) -> str:
        return self.project_for_agent(self.joplin_scope_agent_id(agent_id))

    def use_agent_joplin_note_scope(self, agent_id: str) -> bool:
        agent = self.agents.get(agent_id)
        return (
            isinstance(agent, dict)
            and self.agent_type(agent) == OPERATOR_AGENT_TYPE
            and self.operator_role(agent) == OPERATOR_ROLE_ROOT
        )

    def agent_joplin_notes_url(self, agent_id: str, note_id: str | None = None) -> str:
        base = f"/v1/agents/{quote(agent_id, safe='')}/joplin/notes"
        if note_id is None:
            return base
        return f"{base}/{quote(note_id, safe='')}"

    def joplin_notes_url_for_agent(
        self,
        agent_id: str,
        note_id: str | None = None,
    ) -> str:
        if self.use_agent_joplin_note_scope(agent_id):
            return self.agent_joplin_notes_url(agent_id, note_id)
        return self.project_joplin_notes_url(
            self.joplin_project_for_agent(agent_id),
            note_id,
        )

    def joplin_edit_url_for_agent(self, agent_id: str, note_id: str) -> str:
        return f"{self.joplin_notes_url_for_agent(agent_id, note_id)}/edit"

    def joplin_conflict_url_for_agent(
        self,
        agent_id: str,
        conflict_id: str,
    ) -> str:
        if self.use_agent_joplin_note_scope(agent_id):
            return (
                f"/v1/agents/{quote(agent_id, safe='')}/joplin/conflicts/"
                f"{quote(conflict_id, safe='')}/resolve"
            )
        project = quote(self.joplin_project_for_agent(agent_id), safe="")
        return (
            f"/v1/projects/{project}/joplin/conflicts/"
            f"{quote(conflict_id, safe='')}/resolve"
        )

    def joplin_scope_label_for_agent(self, agent_id: str) -> str:
        if self.use_agent_joplin_note_scope(agent_id):
            return f"agent {agent_id}"
        return f"project {self.joplin_project_for_agent(agent_id)}"

    def repo_scope_agent_id(self, agent_id: str) -> str:
        agent = self.agents.get(agent_id)
        if not isinstance(agent, dict) or self.agent_type(agent) != OPERATOR_AGENT_TYPE:
            return agent_id
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        if self.operator_role(agent) == OPERATOR_ROLE_FORK:
            source_agent_id = str(metadata.get("source_caller_agent_id") or "").strip()
            if source_agent_id:
                return source_agent_id
        source_agent_id = str(
            metadata.get("default_source_caller_agent_id")
            or metadata.get("source_caller_agent_id")
            or ""
        ).strip()
        if source_agent_id:
            return source_agent_id
        inferred_source_agent_id = self.single_active_operator_fork_source_agent_id(
            self.logical_operator_id_for_agent(agent)
        )
        if inferred_source_agent_id:
            return inferred_source_agent_id
        return agent_id

    def default_github_reference_scope_agent_id(self, agent_id: str) -> str | None:
        agent = self.agents.get(agent_id)
        if not isinstance(agent, dict) or self.agent_type(agent) != OPERATOR_AGENT_TYPE:
            return agent_id
        repo_agent_id = self.repo_scope_agent_id(agent_id)
        if repo_agent_id and repo_agent_id != agent_id:
            return repo_agent_id
        return None

    def project_joplin_notes_url(self, project: str, note_id: str | None = None) -> str:
        base = f"/v1/projects/{quote(project, safe='')}/joplin/notes"
        if note_id is None:
            return base
        return f"{base}/{quote(note_id, safe='')}"

    def text_before_completion_context(
        self,
        text_area: TextArea,
        context: FileCompletionContext,
    ) -> str:
        lines = text_area.text.split("\n")
        if context.line < 0 or context.line >= len(lines):
            return ""
        prefix_lines = lines[: context.line]
        prefix_lines.append(lines[context.line][: context.start_col])
        return "\n".join(prefix_lines)

    def caller_scope_agent_id_before_context(
        self,
        text_area: TextArea,
        context: FileCompletionContext,
    ) -> str | None:
        token = None
        before = self.text_before_completion_context(text_area, context)
        for match in CALLER_AGENT_REF_PATTERN.finditer(before):
            token = match.group(1)
        if token is None:
            return None
        return self.resolve_caller_agent_ref_token(token)

    def joplin_completion_agent_id(
        self,
        text_area: TextArea,
        context: FileCompletionContext,
        default_agent_id: str,
    ) -> str:
        if not self.is_operator_agent_id(default_agent_id):
            return default_agent_id
        return (
            self.caller_scope_agent_id_before_context(text_area, context)
            or default_agent_id
        )

    def github_completion_agent_id(
        self,
        text_area: TextArea,
        context: FileCompletionContext,
        default_agent_id: str,
    ) -> str:
        if not self.is_operator_agent_id(default_agent_id):
            return default_agent_id
        return (
            self.caller_scope_agent_id_before_context(text_area, context)
            or self.default_github_reference_scope_agent_id(default_agent_id)
            or default_agent_id
        )

    def file_completion_index(
        self,
        context: FileCompletionContext,
        matches: tuple[str, ...],
        *,
        direction: int,
    ) -> int:
        state = self.file_completion_state.get(context.input_id)
        if (
            state is not None
            and state.line == context.line
            and state.start_col == context.start_col
            and state.matches == matches
            and 0 <= state.index < len(matches)
            and context.prefix.lower() == matches[state.index].lower()
        ):
            return (state.index + direction) % len(matches)
        exact_index = next(
            (
                index
                for index, title in enumerate(matches)
                if title.lower() == context.prefix.lower()
            ),
            None,
        )
        if exact_index is not None:
            if len(matches) == 1:
                return exact_index
            return (exact_index + direction) % len(matches)
        return 0 if direction > 0 else len(matches) - 1

    def apply_file_completion(
        self,
        text_area: TextArea,
        context: FileCompletionContext,
        completion: str,
    ) -> None:
        lines = text_area.text.split("\n")
        line = lines[context.line]
        lines[context.line] = (
            line[: context.start_col] + completion + line[context.end_col :]
        )
        text_area.text = "\n".join(lines)
        text_area.move_cursor((context.line, context.start_col + len(completion)))
        if text_area.id == "message":
            self.resize_message_input()

    def complete_file_reference(self, text_area: TextArea, *, direction: int) -> bool:
        context = self.file_completion_context(text_area)
        if context is None:
            return False
        agent_id = self.sent_history_agent_id(text_area)
        if not agent_id:
            self.notify("Select an agent before completing @file references.", severity="warning")
            return True
        is_joplin_ref = context.prefix.lower().startswith(JOPLIN_NOTE_REF_PREFIX)
        is_caller_ref = context.prefix.lower().startswith(CALLER_AGENT_REF_PREFIX)
        is_pull_request_ref = context.prefix.lower().startswith(PULL_REQUEST_REF_PREFIX)
        is_issue_ref = context.prefix.lower().startswith(ISSUE_REF_PREFIX)
        if is_caller_ref and not self.is_operator_agent_id(agent_id):
            self.notify(
                "Select an operator before completing @caller references.",
                severity="warning",
            )
            return True
        joplin_agent_id = (
            self.joplin_completion_agent_id(text_area, context, agent_id)
            if is_joplin_ref
            else agent_id
        )
        github_agent_id = (
            self.github_completion_agent_id(text_area, context, agent_id)
            if is_pull_request_ref or is_issue_ref
            else agent_id
        )
        state = self.file_completion_state.get(context.input_id)
        if (
            state is not None
            and state.line == context.line
            and state.start_col == context.start_col
            and 0 <= state.index < len(state.matches)
            and context.prefix.lower() == state.matches[state.index].lower()
        ):
            matches = state.matches
        else:
            if is_caller_ref:
                matches = self.caller_agent_completion_matches(context, agent_id)
            elif is_joplin_ref:
                matches = self.joplin_note_completion_matches(context, joplin_agent_id)
            elif is_pull_request_ref:
                matches = self.pull_request_completion_matches(context, github_agent_id)
            elif is_issue_ref:
                matches = self.issue_completion_matches(context, github_agent_id)
            else:
                matches = self.file_completion_matches(context, agent_id)
        if not matches:
            self.file_completion_state.pop(context.input_id, None)
            if is_caller_ref:
                self.notify(
                    f"No cached caller matches {context.prefix!r}; refresh agents first.",
                    severity="warning",
                )
            elif is_joplin_ref:
                self.notify(
                    f"No cached Joplin note matches {context.prefix!r}; open or refresh the Joplin tab.",
                    severity="warning",
                )
            elif is_pull_request_ref:
                self.notify(
                    f"No cached pull request matches {context.prefix!r}; open or refresh the PRs tab.",
                    severity="warning",
                )
            elif is_issue_ref:
                self.notify(
                    f"No cached issue matches {context.prefix!r}; open or refresh the Issues tab.",
                    severity="warning",
                )
            else:
                self.notify(
                    f"No cached file matches {context.prefix!r}; open or refresh Files for {context.directory}.",
                    severity="warning",
                )
            return True
        index = self.file_completion_index(context, matches, direction=direction)
        completion = matches[index]
        self.apply_file_completion(text_area, context, completion)
        self.file_completion_state[context.input_id] = FileCompletionState(
            input_id=context.input_id,
            line=context.line,
            start_col=context.start_col,
            original_prefix=context.prefix,
            matches=matches,
            index=index,
        )
        return True

    async def complete_file_reference_async(
        self,
        text_area: TextArea,
        *,
        direction: int,
    ) -> bool:
        context = self.file_completion_context(text_area)
        if context is None:
            return False
        agent_id = self.sent_history_agent_id(text_area)
        is_joplin_ref = context.prefix.lower().startswith(JOPLIN_NOTE_REF_PREFIX)
        is_caller_ref = context.prefix.lower().startswith(CALLER_AGENT_REF_PREFIX)
        is_pull_request_ref = context.prefix.lower().startswith(PULL_REQUEST_REF_PREFIX)
        is_issue_ref = context.prefix.lower().startswith(ISSUE_REF_PREFIX)
        if not agent_id:
            if is_caller_ref:
                target = "@caller"
            elif is_joplin_ref:
                target = "@joplin note"
            elif is_pull_request_ref:
                target = "@pr reference"
            elif is_issue_ref:
                target = "@issue reference"
            else:
                target = "@file"
            self.notify(f"Select an agent before completing {target} references.", severity="warning")
            return True
        if is_caller_ref and not self.is_operator_agent_id(agent_id):
            self.notify(
                "Select an operator before completing @caller references.",
                severity="warning",
            )
            return True
        joplin_agent_id = (
            self.joplin_completion_agent_id(text_area, context, agent_id)
            if is_joplin_ref
            else agent_id
        )
        github_agent_id = (
            self.github_completion_agent_id(text_area, context, agent_id)
            if is_pull_request_ref or is_issue_ref
            else agent_id
        )

        state = self.file_completion_state.get(context.input_id)
        if (
            state is not None
            and state.line == context.line
            and state.start_col == context.start_col
            and 0 <= state.index < len(state.matches)
            and context.prefix.lower() == state.matches[state.index].lower()
        ):
            matches = state.matches
        else:
            if is_caller_ref:
                matches = self.caller_agent_completion_matches(context, agent_id)
            elif is_joplin_ref:
                matches = self.joplin_note_completion_matches(context, joplin_agent_id)
            elif is_pull_request_ref:
                matches = self.pull_request_completion_matches(context, github_agent_id)
            elif is_issue_ref:
                matches = self.issue_completion_matches(context, github_agent_id)
            else:
                matches = self.file_completion_matches(context, agent_id)
            if not matches:
                try:
                    if is_caller_ref:
                        await self.refresh_agents()
                    elif is_joplin_ref:
                        await self.fetch_joplin_note_summaries(joplin_agent_id)
                    elif is_pull_request_ref:
                        await self.fetch_pull_request_summaries(github_agent_id)
                    elif is_issue_ref:
                        await self.fetch_issue_summaries(github_agent_id)
                    else:
                        payload = await self.fetch_agent_file_listing(
                            agent_id,
                            context.directory,
                        )
                        self.cache_file_listing(payload)
                except Exception as exc:
                    self.file_completion_state.pop(context.input_id, None)
                    if is_caller_ref:
                        label = "Caller"
                    elif is_joplin_ref:
                        label = "Joplin note"
                    elif is_pull_request_ref:
                        label = "Pull request"
                    elif is_issue_ref:
                        label = "Issue"
                    else:
                        label = "File"
                    self.notify(
                        f"{label} completion failed: {exc}",
                        severity="error",
                    )
                    return True
                if is_caller_ref:
                    matches = self.caller_agent_completion_matches(context, agent_id)
                elif is_joplin_ref:
                    matches = self.joplin_note_completion_matches(context, joplin_agent_id)
                elif is_pull_request_ref:
                    matches = self.pull_request_completion_matches(context, github_agent_id)
                elif is_issue_ref:
                    matches = self.issue_completion_matches(context, github_agent_id)
                else:
                    matches = self.file_completion_matches(context, agent_id)

        if not matches:
            self.file_completion_state.pop(context.input_id, None)
            if is_caller_ref:
                label = "caller agent"
            elif is_joplin_ref:
                label = "scoped Joplin note"
            elif is_pull_request_ref:
                label = "pull request"
            elif is_issue_ref:
                label = "issue"
            else:
                label = "project file"
            self.notify(
                f"No {label} matches {context.prefix!r}.",
                severity="warning",
            )
            return True

        index = self.file_completion_index(context, matches, direction=direction)
        completion = matches[index]
        self.apply_file_completion(text_area, context, completion)
        self.file_completion_state[context.input_id] = FileCompletionState(
            input_id=context.input_id,
            line=context.line,
            start_col=context.start_col,
            original_prefix=context.prefix,
            matches=matches,
            index=index,
        )
        return True

    def slash_completion_context(
        self, text_area: TextArea
    ) -> SlashCompletionContext | None:
        input_id = text_area.id or "message"
        row, column = text_area.cursor_location
        lines = text_area.text.split("\n")
        if row < 0 or row >= len(lines):
            return None
        line = lines[row]
        column = min(max(0, column), len(line))
        if not line.startswith("/") or column == 0:
            return None
        suffix = line[column:]
        if suffix.strip():
            return None
        prefix = line[:column]
        if not prefix.startswith("/"):
            return None
        return SlashCompletionContext(
            input_id=input_id,
            line=row,
            start_col=0,
            end_col=column,
            prefix=prefix,
        )

    def slash_completion_matches(self, prefix: str) -> tuple[str, ...]:
        prefix_key = prefix.lower()
        return tuple(
            title
            for title in self.slash_command_titles()
            if title.lower().startswith(prefix_key)
        )

    def slash_completion_index(
        self,
        context: SlashCompletionContext,
        matches: tuple[str, ...],
        *,
        direction: int,
    ) -> int:
        state = self.slash_completion_state.get(context.input_id)
        if (
            state is not None
            and state.line == context.line
            and state.start_col == context.start_col
            and state.matches == matches
            and 0 <= state.index < len(matches)
            and context.prefix.lower() == matches[state.index].lower()
        ):
            return (state.index + direction) % len(matches)
        exact_index = next(
            (
                index
                for index, title in enumerate(matches)
                if title.lower() == context.prefix.lower()
            ),
            None,
        )
        if exact_index is not None:
            if len(matches) == 1:
                return exact_index
            return (exact_index + direction) % len(matches)
        return 0 if direction > 0 else len(matches) - 1

    def apply_slash_completion(
        self,
        text_area: TextArea,
        context: SlashCompletionContext,
        completion: str,
    ) -> None:
        lines = text_area.text.split("\n")
        line = lines[context.line]
        lines[context.line] = (
            line[: context.start_col] + completion + line[context.end_col :]
        )
        text_area.text = "\n".join(lines)
        text_area.move_cursor((context.line, context.start_col + len(completion)))
        if text_area.id == "message":
            self.resize_message_input()

    def complete_slash_command(self, text_area: TextArea, *, direction: int) -> bool:
        context = self.slash_completion_context(text_area)
        if context is None:
            return False
        state = self.slash_completion_state.get(context.input_id)
        if (
            state is not None
            and state.line == context.line
            and state.start_col == context.start_col
            and 0 <= state.index < len(state.matches)
            and context.prefix.lower() == state.matches[state.index].lower()
        ):
            matches = state.matches
        else:
            matches = self.slash_completion_matches(context.prefix)
        if not matches:
            self.slash_completion_state.pop(context.input_id, None)
            self.notify(
                f"No slash command matches {context.prefix!r}.",
                severity="warning",
            )
            return True
        index = self.slash_completion_index(context, matches, direction=direction)
        completion = matches[index]
        self.apply_slash_completion(text_area, context, completion)
        self.slash_completion_state[context.input_id] = SlashCompletionState(
            input_id=context.input_id,
            line=context.line,
            start_col=context.start_col,
            original_prefix=context.prefix,
            matches=matches,
            index=index,
        )
        return True

    async def execute_local_slash_command_from_input(
        self,
        text_area: TextArea,
        message: str,
    ) -> bool:
        git_push_branch = parse_git_push_slash_command(message)
        if git_push_branch is not None:
            agent_id = self.sent_history_agent_id(text_area)
            if agent_id:
                self.selected_agent_id = agent_id
                agent_input = self.query_one_or_none("#agent-id", Input)
                if agent_input is not None:
                    agent_input.value = agent_id
            if not agent_id:
                self.notify("Select an agent first.", severity="warning")
                return True
            if not self.is_tmux_direct_enabled(agent_id):
                self.notify(
                    f"Enable tmux direct mode for {agent_id} before using this command.",
                    severity="warning",
                )
                return True
            await self.palette_git_push_target(agent_id, git_push_branch)
            self.record_sent_message(agent_id, message)
            self.set_agent_draft_text(agent_id, text_area, "")
            return True
        command = self.slash_command_for_text(message)
        if command is None:
            return False
        agent_id = self.sent_history_agent_id(text_area)
        if agent_id:
            self.selected_agent_id = agent_id
            agent_input = self.query_one_or_none("#agent-id", Input)
            if agent_input is not None:
                agent_input.value = agent_id
        joplin_action = JOPLIN_SLASH_ACTIONS.get(command.title.lower())
        if joplin_action is not None:
            if not agent_id:
                self.notify("Select an agent first.", severity="warning")
                return True
            await self.joplin_action_for_agent(agent_id, joplin_action)
            self.record_sent_message(agent_id, message)
            self.set_agent_draft_text(agent_id, text_area, "")
            return True
        pr_action = PULL_REQUEST_SLASH_ACTIONS.get(command.title.lower())
        if pr_action is not None:
            if not agent_id:
                self.notify("Select an agent first.", severity="warning")
                return True
            await self.pull_request_action_for_agent(agent_id, pr_action)
            self.record_sent_message(agent_id, message)
            self.set_agent_draft_text(agent_id, text_area, "")
            return True
        issue_action = ISSUE_SLASH_ACTIONS.get(command.title.lower())
        if issue_action is not None:
            if not agent_id:
                self.notify("Select an agent first.", severity="warning")
                return True
            await self.issue_action_for_agent(agent_id, issue_action)
            self.record_sent_message(agent_id, message)
            self.set_agent_draft_text(agent_id, text_area, "")
            return True
        campaign_action = CAMPAIGN_SLASH_ACTIONS.get(command.title.lower())
        if campaign_action is not None:
            if not agent_id:
                self.notify("Select an agent first.", severity="warning")
                return True
            await self.campaign_action_for_agent(agent_id, campaign_action)
            self.record_sent_message(agent_id, message)
            self.set_agent_draft_text(agent_id, text_area, "")
            return True
        original_text = text_area.text
        result = command.callback()
        if inspect.isawaitable(result):
            await result
        if agent_id:
            self.record_sent_message(agent_id, message)
        if text_area.text == original_text:
            if agent_id:
                self.set_agent_draft_text(agent_id, text_area, "")
            else:
                text_area.text = ""
                if text_area.id == "message":
                    self.resize_message_input()
        return True

    def on_tabbed_content_tab_activated(
        self, event: TabbedContent.TabActivated
    ) -> None:
        if event.tabbed_content.id != "agent-tabs":
            return
        self.active_agent_tab = str(event.pane.id)
        agent_id = self.selected_agent_id
        if agent_id:
            self.active_agent_tab_by_agent[agent_id] = self.active_agent_tab
        self.save_settings()
        if self.active_agent_tab == "latest-tab" and agent_id:
            self.mark_latest_seen(agent_id)
            self.apply_tmux_class()
            if self.is_tmux_direct_enabled(agent_id):
                self.run_async_worker(
                    lambda agent_id=agent_id: self.load_tmux_capture(agent_id),
                    name="tmux-capture",
                    exclusive=True,
                )
        elif self.embedded_terminal_agent_id:
            self.run_async_worker(
                lambda: self.detach_embedded_tmux_terminal(release_lease=True),
                name="embedded-terminal-tab-detach",
                exclusive=True,
            )
        if self.active_agent_tab == "codex-tab":
            self.run_async_worker(
                self.load_codex_config,
                name="codex-config",
                exclusive=True,
            )
        if self.active_agent_tab == "workerbee-tab" and agent_id:
            self.run_async_worker(
                lambda agent_id=agent_id: self.load_workerbee_status(agent_id),
                name="workerbee-status",
                exclusive=True,
            )
        if self.active_agent_tab == "pull-requests-tab" and agent_id:
            self.run_async_worker(
                lambda agent_id=agent_id: self.load_pull_requests(agent_id),
                name="pull-requests",
                exclusive=True,
            )
        if self.active_agent_tab == "issues-tab" and agent_id:
            self.run_async_worker(
                lambda agent_id=agent_id: self.load_issues(agent_id),
                name="issues",
                exclusive=True,
            )
        if self.active_agent_tab == "files-tab" and agent_id:
            self.run_async_worker(
                lambda agent_id=agent_id: self.load_agent_files(agent_id),
                name="agent-files",
                exclusive=True,
            )
        if self.active_agent_tab == "editor-tab" and agent_id:
            self.render_editor_for_agent(agent_id)
        if self.active_agent_tab == "operator-kb-tab" and agent_id:
            self.run_async_worker(
                lambda agent_id=agent_id: self.load_operator_kb(agent_id),
                name="operator-kb",
                exclusive=True,
            )
        if self.active_agent_tab == "joplin-tab" and agent_id:
            self.run_async_worker(
                lambda agent_id=agent_id: self.load_joplin_notes(agent_id),
                name="agent-joplin",
                exclusive=True,
            )

    def save_current_agent_pane_state(self, agent_id: str | None = None) -> None:
        agent_id = agent_id or self.selected_agent_id
        if not agent_id:
            return
        self.active_agent_tab_by_agent[agent_id] = self.active_agent_tab
        if self.selected_thread_item_id:
            self.selected_thread_item_id_by_agent[agent_id] = self.selected_thread_item_id
        else:
            self.selected_thread_item_id_by_agent.pop(agent_id, None)
        if self.selected_pull_request_number is not None:
            self.selected_pull_request_number_by_agent[agent_id] = (
                self.selected_pull_request_number
            )
        else:
            self.selected_pull_request_number_by_agent.pop(agent_id, None)
        if self.selected_issue_number is not None:
            self.selected_issue_number_by_agent[agent_id] = self.selected_issue_number
        else:
            self.selected_issue_number_by_agent.pop(agent_id, None)
        message_input = self.query_one_or_none("#message", TextArea)
        if message_input is not None:
            self.message_draft_by_agent[agent_id] = message_input.text
        tmux_message = self.query_one_or_none("#tmux-message", TextArea)
        if tmux_message is not None:
            self.tmux_message_draft_by_agent[agent_id] = tmux_message.text
        self.capture_editor_buffer(agent_id)

    def restore_agent_pane_state(self, agent_id: str) -> None:
        self.selected_thread_item_id = self.selected_thread_item_id_by_agent.get(
            agent_id
        )
        self.selected_pull_request_number = (
            self.selected_pull_request_number_by_agent.get(agent_id)
        )
        self.selected_issue_number = self.selected_issue_number_by_agent.get(agent_id)
        self.restore_agent_drafts(agent_id)
        preferred_tab = self.active_agent_tab_by_agent.get(agent_id, "latest-tab")
        self.activate_agent_tab(preferred_tab)

    def restore_agent_drafts(self, agent_id: str) -> None:
        message_input = self.query_one_or_none("#message", TextArea)
        if message_input is not None:
            message_input.text = self.message_draft_by_agent.get(agent_id, "")
            self.resize_message_input()
        tmux_message = self.query_one_or_none("#tmux-message", TextArea)
        if tmux_message is not None:
            tmux_message.text = self.tmux_message_draft_by_agent.get(agent_id, "")

    def activate_agent_tab(self, tab_id: str) -> str:
        if tab_id == "joplin-tab" and not self.joplin_configured:
            tab_id = "latest-tab"
        tabs = self.query_one_or_none("#agent-tabs", TabbedContent)
        if tabs is not None:
            try:
                tabs.active = tab_id
            except Exception:
                tab_id = "latest-tab"
                tabs.active = tab_id
        self.active_agent_tab = tab_id
        if self.selected_agent_id:
            self.active_agent_tab_by_agent[self.selected_agent_id] = tab_id
        return tab_id

    async def select_agent(self, agent_id: str) -> None:
        previous_agent_id = self.selected_agent_id
        smooth_terminal_handoff = self.should_smooth_terminal_handoff(
            previous_agent_id,
            agent_id,
        )
        if smooth_terminal_handoff:
            self.begin_embedded_terminal_transition(agent_id)
        if agent_id != previous_agent_id:
            await self.detach_embedded_tmux_terminal(
                release_lease=True,
                preserve_transition=smooth_terminal_handoff,
            )
            self.save_current_agent_pane_state(previous_agent_id)
        was_compact_home = self.is_compact_layout() and self.compact_view == "home"
        self.selected_agent_id = agent_id
        self.query_one("#agent-id", Input).value = self.selected_agent_id
        if agent_id != previous_agent_id:
            self.restore_agent_pane_state(agent_id)
        self.update_agent_title()
        self.sync_codex_model_preset_for_agent(agent_id)
        if agent_id not in self.codex_runtime_by_agent and agent_id in self.agents:
            self.codex_runtime_by_agent[agent_id] = self.local_runtime_snapshot(
                self.agents[agent_id]
            )
        self.render_codex_runtime_surface()
        self.apply_tmux_class()
        if self.is_compact_layout():
            self.show_compact_agent()
        if was_compact_home:
            self.activate_agent_tab(
                self.active_agent_tab_by_agent.get(agent_id, "latest-tab")
            )
        await self.refresh_selected_agent(self.selected_agent_id)
        self.run_async_worker(
            lambda: self.load_codex_runtime_status(agent_id),
            name=f"codex-runtime-{agent_id}",
            group="codex-runtime",
            exclusive=True,
            exit_on_error=False,
        )
        if self.active_agent_tab == "latest-tab":
            self.mark_latest_seen(agent_id)
        self.save_settings()

    def plan_mode_state(self, agent_id: str | None) -> str:
        if not agent_id:
            return "off"
        if agent_id in self.tmux_plan_selector_agent_ids:
            return "select"
        if self.pending_slash_command_by_agent.get(agent_id) == PLAN_SLASH_COMMAND:
            return "pending"
        if agent_id in self.plan_mode_active_agent_ids:
            return "on"
        return "off"

    def update_agent_title(self) -> None:
        title = self.query_one_or_none("#agent-title", Static)
        if title is None:
            return
        agent_id = self.selected_agent_id
        if not agent_id:
            title.update("Agent: -")
            return
        state = self.plan_mode_state(agent_id)
        view = "tmux" if self.is_tmux_direct_enabled(agent_id) else "pbx"
        title.update(f"Agent: {agent_id} | View: {view} | Plan: {state}")

    async def load_codex_runtime_status(self, agent_id: str) -> None:
        try:
            response = await self.api_client().get(
                f"/v2/agents/{quote(agent_id, safe='')}/codex-runtime",
                headers=auth_headers(self.token),
                timeout=8,
            )
            response.raise_for_status()
            snapshot = response.json()
            if isinstance(snapshot, dict):
                self.codex_runtime_by_agent[agent_id] = snapshot
        except Exception:
            agent = self.agents.get(agent_id)
            if agent is not None:
                self.codex_runtime_by_agent[agent_id] = self.local_runtime_snapshot(agent)
        if self.selected_agent_id == agent_id:
            self.render_codex_runtime_surface()

    def local_runtime_snapshot(self, agent: Mapping[str, Any]) -> dict[str, Any]:
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        status = str(agent.get("effective_status") or agent.get("status") or "").lower()
        state = {
            "working": "thinking",
            "running": "thinking",
            "blocked": "waiting_user",
            "waiting": "waiting_user",
            "done": "complete",
            "complete": "complete",
            "completed": "complete",
            "failed": "error",
            "error": "error",
            "canceled": "interrupted",
            "cancelled": "interrupted",
            "registered": "ready",
        }.get(status, "unknown")
        model = str(metadata.get("codex_model") or metadata.get("model") or "")
        profile = None
        if model:
            profile = {
                "model": model,
                "reasoning_effort": str(
                    metadata.get("codex_model_reasoning_effort")
                    or metadata.get("model_reasoning_effort")
                    or ""
                ),
            }
        return {
            "api_version": "agent-pbx.codex-runtime/fallback",
            "agent_id": str(agent.get("agent_id") or ""),
            "state": state,
            "profile": profile,
            "context": {},
            "branch": metadata.get("branch") or metadata.get("git_branch"),
            "capabilities": {"native_subagents": "unsupported"},
            "children": [],
            "evidence": {"source": "pbx_report"},
        }

    def render_codex_runtime_surface(self) -> None:
        status_widget = self.query_one_or_none("#codex-runtime-status", Static)
        topology_widget = self.query_one_or_none("#codex-runtime-topology", Static)
        if status_widget is None or topology_widget is None:
            return
        agent_id = self.selected_agent_id
        snapshot = self.codex_runtime_by_agent.get(agent_id or "")
        workerbee = self.workerbee_status_by_agent.get(agent_id or "")
        rendered = runtime_header(
            snapshot,
            workerbee,
            frame=self.codex_runtime_animation_frame,
            color_depth=self.terminal_color_depth,
        )
        status_widget.update(rendered.text)
        topology = runtime_topology(
            snapshot,
            frame=self.codex_runtime_animation_frame,
            color_depth=self.terminal_color_depth,
        )
        topology_widget.update(topology)
        topology_widget.set_class(bool(topology.plain), "has-subagents")

    def activate_latest_tab(self) -> None:
        self.activate_agent_tab("latest-tab")

    def run_async_worker(
        self,
        work_factory: Callable[[], Any],
        *,
        name: str | None = "",
        group: str = "default",
        description: str = "",
        exit_on_error: bool = True,
        start: bool = True,
        exclusive: bool = False,
    ) -> Any:
        async def runner() -> Any:
            result = work_factory()
            if inspect.isawaitable(result):
                return await result
            return result

        return self.run_worker(
            runner,
            name=name,
            group=group,
            description=description,
            exit_on_error=exit_on_error,
            start=start,
            exclusive=exclusive,
        )

    async def refresh_selected_agent(self, agent_id: str) -> None:
        if self.active_agent_tab == "files-tab":
            await self.load_agent_files(agent_id)
        elif self.active_agent_tab == "editor-tab":
            self.render_editor_for_agent(agent_id)
        elif self.active_agent_tab == "workerbee-tab":
            await self.load_workerbee_status(agent_id)
        elif self.active_agent_tab == "pull-requests-tab":
            await self.load_pull_requests(agent_id)
        elif self.active_agent_tab == "issues-tab":
            await self.load_issues(agent_id)
        elif self.active_agent_tab == "campaigns-tab":
            await self.load_operator_campaigns(agent_id)
        elif self.active_agent_tab == "operator-kb-tab":
            await self.load_operator_kb(agent_id)
        elif self.active_agent_tab == "joplin-tab":
            await self.load_joplin_notes(agent_id)
        elif self.is_tmux_direct_enabled(agent_id):
            await self.load_tmux_capture(agent_id)
        else:
            await self.load_latest_report(agent_id)
        await self.load_thread(agent_id)

    def mark_latest_seen(self, agent_id: str) -> None:
        last_seen = self.latest_report_timestamp(agent_id)
        changed = False
        should_sync_remote = False
        if last_seen is not None:
            changed = self.latest_viewed_at_by_agent.get(agent_id) != last_seen
            self.latest_viewed_at_by_agent[agent_id] = last_seen
            shared_seen_at = self.shared_latest_seen_at(agent_id)
            should_sync_remote = shared_seen_at is None or shared_seen_at < last_seen
        if (changed or should_sync_remote) and self.is_running:
            self.run_async_worker(
                lambda agent_id=agent_id: self.mark_latest_seen_remote(agent_id),
                name=f"latest-seen-{agent_id}",
                exclusive=True,
            )
        if agent_id not in self.unseen_latest_agent_ids:
            if changed:
                self.save_settings()
            return
        self.unseen_latest_agent_ids.remove(agent_id)
        self.render_agents()
        self.render_unseen_attention()
        self.save_settings()

    async def mark_latest_seen_remote(self, agent_id: str) -> None:
        agent_record = self.agents.get(agent_id)
        is_root_operator = bool(
            agent_record
            and self.agent_type(agent_record) == OPERATOR_AGENT_TYPE
            and self.operator_role(agent_record) == OPERATOR_ROLE_ROOT
        )
        try:
            response = await self.api_client().post(
                (
                    f"/v2/operators/{agent_id}/alerts/acknowledge"
                    if is_root_operator
                    else f"/v1/agents/{agent_id}/latest/seen"
                ),
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            payload = response.json()
        except Exception:
            return
        if is_root_operator and isinstance(payload, dict):
            acknowledged = payload.get("acknowledged")
            changed = False
            for item in acknowledged if isinstance(acknowledged, list) else []:
                if not isinstance(item, dict):
                    continue
                member_id = str(item.get("agent_id") or "").strip()
                seen_at = float_value(item.get("latest_report_seen_at"))
                if not member_id or seen_at is None:
                    continue
                existing = self.agents.get(member_id)
                if existing is not None:
                    existing["latest_report_seen_at"] = max(
                        self.shared_latest_seen_at(member_id) or 0.0,
                        seen_at,
                    )
                self.latest_viewed_at_by_agent[member_id] = max(
                    self.latest_viewed_at_by_agent.get(member_id, 0.0),
                    seen_at,
                )
                current_report_at = self.latest_report_timestamp(member_id)
                if current_report_at is None or current_report_at <= seen_at:
                    self.unseen_latest_agent_ids.discard(member_id)
                changed = True
            if changed:
                self.render_agents()
                self.render_unseen_attention()
                self.save_settings()
            return
        if not isinstance(payload, dict):
            return
        existing = self.agents.get(agent_id)
        if existing is not None:
            existing["latest_report_seen_at"] = payload.get("latest_report_seen_at")
        else:
            self.agents[agent_id] = payload
        seen_at = self.shared_latest_seen_at(agent_id)
        if seen_at is not None:
            self.latest_viewed_at_by_agent[agent_id] = max(
                self.latest_viewed_at_by_agent.get(agent_id, 0.0),
                seen_at,
            )
            self.save_settings()

    async def load_latest_report(self, agent_id: str) -> None:
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is None:
            return
        try:
            response = await self.api_client().get(
                f"/v1/agents/{agent_id}/reports",
                params={"limit": 1},
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            reports = response.json()
        except Exception as exc:
            detail.text = f"Unable to load report for {agent_id}: {exc}"
            self.render_latest_plan_choice_panel(None)
            return
        if not reports:
            detail.text = f"No reports for {agent_id}."
            self.latest_report_by_agent.pop(agent_id, None)
            self.render_latest_plan_choice_panel(None)
            return
        report = reports[0]
        self.latest_report_by_agent[agent_id] = report
        plan_options = self.plan_options_for_report(report)
        lines = [
            f"Agent: {report['agent_id']}",
            f"Status: {report['status']}",
            f"Needs Input: {'yes' if report.get('needs_input') else 'no'}",
            f"Summary: {report['summary']}",
            "",
            str(report["detail"]),
        ]
        if plan_options:
            lines.extend(
                [
                    "",
                    "Plan Options:",
                    *[f"- {option.display_label}" for option in plan_options],
                ]
            )
        detail.text = "\n".join(lines)
        self.render_latest_plan_choice_panel(report)

    async def refresh_tmux_capture_if_active(self) -> None:
        if (
            not self.is_tmux_direct_enabled(self.selected_agent_id)
            or self.active_agent_tab != "latest-tab"
            or not self.selected_agent_id
            or self.tmux_refreshing
        ):
            return
        self.tmux_refreshing = True
        try:
            await self.load_tmux_capture(self.selected_agent_id)
        finally:
            self.tmux_refreshing = False

    async def load_tmux_capture(self, agent_id: str) -> None:
        status = self.query_one_or_none("#tmux-status", Static)
        stream = self.query_one_or_none("#tmux-stream", TextArea)
        if status is None or stream is None:
            return
        if self.embedded_terminal_v2_enabled:
            mapping = await self.fetch_tmux_runtime_mapping(agent_id)
            if mapping is not None and await self.attach_embedded_tmux_terminal(
                agent_id, mapping
            ):
                return
        if not self.legacy_terminal_capture_enabled:
            self.end_embedded_terminal_transition(agent_id)
            self.tmux_visible_capture_key = None
            self.update_tmux_status(
                status,
                "Tmux: native terminal unavailable; capture fallback disabled",
                cache_key=agent_id,
            )
            stream.text = (
                "The retained tmux capture fallback is disabled by compatibility "
                "policy. Re-enable AGENT_PBX_TUI_COMPAT_TERMINAL_CAPTURE or repair "
                "the managed runtime mapping."
            )
            return
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception as exc:
            self.end_embedded_terminal_transition(agent_id)
            self.tmux_visible_capture_key = None
            self.record_tmux_liveness_state(agent_id, "unavailable")
            self.update_tmux_status(
                status,
                "Tmux: unavailable",
                cache_key=agent_id,
            )
            stream.text = f"Unable to list tmux panes: {exc}"
            self.render_agents()
            return
        self.tmux_panes = panes
        pane, mode = self.resolve_tmux_pane(agent_id, panes)
        if pane is None and mode == "auto":
            selector_pane = await self.resolve_tmux_plan_selector_pane(agent_id, panes)
            if selector_pane is not None:
                pane = selector_pane
                mode = "selector"
        if pane is None:
            self.end_embedded_terminal_transition(agent_id)
            self.tmux_visible_capture_key = None
            self.update_tmux_plan_selector_state(agent_id, "")
            self.record_tmux_liveness_state(
                agent_id,
                "stale" if mode == "stale" else mode,
            )
            if mode == "stale":
                self.update_tmux_status(
                    status,
                    f"Tmux: stale target for {agent_id}",
                    cache_key=agent_id,
                )
                stream.text = (
                    "The saved tmux pane target no longer matches this agent.\n\n"
                    "Use Auto to rediscover the pane or Select Pane to choose one."
                )
            else:
                self.update_tmux_status(
                    status,
                    f"Tmux: no pane for {agent_id}",
                    cache_key=agent_id,
                )
                stream.text = (
                    "No tmux pane is attached for this agent.\n\n"
                    "Use Auto to retry discovery or Select Pane to choose a pane."
                )
            self.render_agents()
            return
        mapped = await self.ensure_tmux_runtime_mapping(agent_id, pane)
        if mapped and self.embedded_terminal_v2_enabled:
            mapping = self.tmux_runtime_mapping_by_agent.get(agent_id)
            if mapping is not None and await self.attach_embedded_tmux_terminal(
                agent_id, mapping
            ):
                return
        self.end_embedded_terminal_transition(agent_id)
        cache_key = f"{agent_id}:{pane.pane_id}"
        self.prepare_tmux_stream_for_capture(stream, cache_key=cache_key, pane=pane)
        try:
            captured = await asyncio.to_thread(
                tmux_support.capture_pane,
                pane.pane_id,
                lines=self.tmux_capture_lines,
            )
        except Exception as exc:
            self.update_tmux_status(
                status,
                f"Tmux: {pane.pane_id} capture failed",
                cache_key=agent_id,
            )
            self.update_tmux_plan_selector_state(agent_id, "")
            self.record_tmux_liveness_state(agent_id, "unavailable", pane_id=pane.pane_id)
            stream.text = f"Unable to capture tmux pane {pane.pane_id}: {exc}"
            self.render_agents()
            return
        displayed = self.crop_tmux_capture_for_display(captured or "(empty tmux pane)")
        self.update_tmux_plan_selector_state(
            agent_id,
            displayed,
            pane_id=pane.pane_id,
        )
        self.record_tmux_capture_liveness(agent_id, pane.pane_id, displayed)
        self.update_tmux_stream(
            stream,
            displayed,
            cache_key=cache_key,
        )
        selector_note = (
            " selector pending: /plan:1 start /plan:2 clear context & start /plan:3 stay"
            if agent_id in self.tmux_plan_selector_agent_ids
            else ""
        )
        native_error = str(
            self.tmux_runtime_mapping_error_by_agent.get(agent_id) or ""
        ).strip()
        native_note = (
            f" native unavailable: {native_error};" if native_error else ""
        )
        self.update_tmux_status(
            status,
            (
                "Tmux: "
                f"{pane.pane_id} {pane.target_label} {mode} "
                f"{native_note} capture fallback "
                f"{self.tmux_capture_mode_label()} "
                "cropped "
                f"{pane.current_command} {pane.width}x{pane.height} "
                f"{'alternate screen; history unavailable' if pane.alternate_on else 'normal screen'} "
                f"history {pane.history_size}"
                f"{selector_note}"
            ),
            cache_key=agent_id,
        )
        self.render_agents()

    async def ensure_tmux_runtime_mapping(
        self,
        agent_id: str,
        pane: tmux_support.TmuxPane,
    ) -> bool:
        identity = self.tmux_runtime_server
        if (
            identity.effective_mode is RuntimeServerMode.DEDICATED
            or not identity.ready
            or not self.tmux_local_direct_context
        ):
            return False
        outer = await asyncio.to_thread(read_outer_tmux_context, identity)
        reason = recursive_attachment_reason(
            target_session=pane.session_name,
            target_pane_id=pane.pane_id,
            outer=outer,
        )
        if reason:
            self.tmux_runtime_mapping_error_by_agent[agent_id] = reason
            return False
        pane_pid = await asyncio.to_thread(
            tmux_support.pane_root_pid,
            pane.pane_id,
        )
        agent = self.agents.get(agent_id) or {}
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        session_id = str(
            metadata.get("fork_codex_session_id")
            or metadata.get("last_resume_codex_session_id")
            or metadata.get("codex_session_id")
            or metadata.get("codex_thread_id")
            or ""
        ).strip()
        signature = (
            identity.server_id,
            pane.session_name,
            pane.window_id or pane.window_index,
            pane.pane_id,
            pane_pid,
            session_id,
        )
        if self.tmux_runtime_mapping_signature_by_agent.get(agent_id) == signature:
            return True
        ticks = await asyncio.to_thread(runtime_process_start_ticks, pane_pid)
        payload = {
            "server_mode": identity.effective_mode.value,
            "socket_path": identity.socket_path,
            "session_name": pane.session_name,
            "window_id": pane.window_id or pane.window_index,
            "window_name": pane.window_name,
            "pane_id": pane.pane_id,
            "pane_pid": pane_pid,
            "process_start_ticks": ticks,
            "codex_session_id": session_id or None,
            "cwd": pane.cwd,
            "origin_client_tty": outer.client_tty if outer else None,
            "origin_session_name": outer.session_name if outer else None,
            "metadata": {
                "managed_by": "agent-pbx-tui",
                "mapping_source": "latest",
                "tmux_bin": configured_tmux_binary(),
            },
        }
        try:
            response = await self.api_client().post(
                f"/v2/tmux/runtimes/{quote(agent_id, safe='')}",
                json=payload,
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            mapping = response.json()
        except Exception as exc:
            self.tmux_runtime_mapping_error_by_agent[agent_id] = str(exc)
            return False
        self.tmux_runtime_mapping_by_agent[agent_id] = mapping
        self.tmux_runtime_mapping_validated_at_by_agent[agent_id] = time.monotonic()
        self.tmux_runtime_mapping_signature_by_agent[agent_id] = signature
        self.tmux_runtime_mapping_error_by_agent.pop(agent_id, None)
        return True

    async def fetch_tmux_runtime_mapping(
        self,
        agent_id: str,
    ) -> dict[str, Any] | None:
        cached = self.tmux_runtime_mapping_by_agent.get(agent_id)
        validated_at = self.tmux_runtime_mapping_validated_at_by_agent.get(agent_id, 0.0)
        if (
            cached is not None
            and str(cached.get("state") or "") == "ready"
            and time.monotonic() - validated_at < TMUX_RUNTIME_MAPPING_CACHE_SECONDS
        ):
            return cached
        try:
            response = await self.api_client().get(
                f"/v2/tmux/runtimes/{quote(agent_id, safe='')}",
                headers=auth_headers(self.token),
            )
            if response.status_code == 404:
                self.tmux_runtime_mapping_by_agent.pop(agent_id, None)
                self.tmux_runtime_mapping_validated_at_by_agent.pop(agent_id, None)
                return None
            response.raise_for_status()
            mapping = response.json()
        except Exception as exc:
            self.tmux_runtime_mapping_error_by_agent[agent_id] = str(exc)
            return None
        self.tmux_runtime_mapping_by_agent[agent_id] = mapping
        self.tmux_runtime_mapping_validated_at_by_agent[agent_id] = time.monotonic()
        if str(mapping.get("state") or "") == "ready":
            self.tmux_runtime_mapping_error_by_agent.pop(agent_id, None)
        else:
            self.tmux_runtime_mapping_error_by_agent[agent_id] = (
                f"runtime mapping is {mapping.get('state') or 'unavailable'}"
            )
        return mapping

    async def acquire_tmux_writer_lease(self, agent_id: str) -> dict[str, Any] | None:
        try:
            response = await self.api_client().post(
                f"/v2/tmux/runtimes/{quote(agent_id, safe='')}/writer/acquire",
                json={
                    "client_id": self.tmux_terminal_client_id,
                    "ttl_seconds": TMUX_WRITER_LEASE_SECONDS,
                },
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            mapping = response.json()
        except Exception as exc:
            self.tmux_runtime_mapping_error_by_agent[agent_id] = str(exc)
            return None
        self.tmux_runtime_mapping_by_agent[agent_id] = mapping
        self.tmux_runtime_mapping_validated_at_by_agent[agent_id] = time.monotonic()
        self.tmux_runtime_mapping_error_by_agent.pop(agent_id, None)
        return mapping

    async def release_tmux_writer_lease(self, agent_id: str) -> None:
        try:
            response = await self.api_client().post(
                f"/v2/tmux/runtimes/{quote(agent_id, safe='')}/writer/release",
                json={
                    "client_id": self.tmux_terminal_client_id,
                    "ttl_seconds": TMUX_WRITER_LEASE_SECONDS,
                },
                headers=auth_headers(self.token),
            )
            if response.status_code not in {404, 409}:
                response.raise_for_status()
        except Exception:
            return

    async def wait_for_embedded_terminal_layout(
        self,
        surface: PbxTerminalSurface,
        *,
        attempts: int = 3,
    ) -> bool:
        """Wait until a newly revealed terminal has an authoritative rectangle.

        The surface normally has ``display: none`` while capture mode is active.
        Starting its PTY in the same message turn that adds the
        ``embedded-terminal`` screen class observes a zero-sized widget and
        gives the nested tmux client the construction fallback of 80x24.  Ask
        Textual for a layout pass and wait for the resulting refresh before
        creating the PTY.
        """

        # Always complete at least one layout pass. A surface that was visible
        # before it was hidden can retain its previous non-zero ``size`` until
        # the new class-driven layout runs. Accepting that stale rectangle
        # starts the nested client at the old split width and leaves Codex
        # overlays clipped even though the surrounding PBX pane is wider.
        for _ in range(max(1, attempts)):
            ready = asyncio.Event()
            self.screen.refresh(layout=True)
            if not surface.call_after_refresh(ready.set):
                return False
            try:
                await asyncio.wait_for(ready.wait(), timeout=0.5)
            except TimeoutError:
                continue
            if surface.size.width > 0 and surface.size.height > 0:
                return True
        return surface.size.width > 0 and surface.size.height > 0

    async def attach_embedded_tmux_terminal(
        self,
        agent_id: str,
        mapping: dict[str, Any],
    ) -> bool:
        if (
            not self.embedded_terminal_v2_enabled
            or self.active_agent_tab != "latest-tab"
            or agent_id != self.selected_agent_id
            or str(mapping.get("state") or "") != "ready"
        ):
            return False
        target = f"{mapping.get('server_id')}:{mapping.get('pane_id')}"
        surface = self.query_one_or_none(
            "#pbx-terminal-surface", PbxTerminalSurface
        )
        if surface is None:
            return False
        if (
            self.embedded_terminal_agent_id == agent_id
            and self.embedded_terminal_target == target
            and surface.attached
        ):
            # The renewal timer owns lease refresh. Reacquiring on every pane
            # refresh caused database writes and event-stream churn while the
            # same client already held the lease.
            surface.set_scroll_mode(self.embedded_terminal_scroll_mode)
            surface.sync_geometry()
            self.apply_tmux_class()
            return True
        await self.detach_embedded_tmux_terminal(
            release_lease=True,
            preserve_transition=(
                self.embedded_terminal_transition_agent_id == agent_id
            ),
        )
        leased = await self.acquire_tmux_writer_lease(agent_id)
        if leased is None:
            return False
        if (
            agent_id != self.selected_agent_id
            or self.active_agent_tab != "latest-tab"
            or not self.embedded_terminal_v2_enabled
        ):
            # Selection can change while the writer lease request is in
            # flight. Never let that stale worker replace the terminal for the
            # newly selected entity.
            await self.release_tmux_writer_lease(agent_id)
            return False
        try:
            self.embedded_terminal_agent_id = agent_id
            self.embedded_terminal_target = target
            self.apply_tmux_class()
            if not await self.wait_for_embedded_terminal_layout(surface):
                raise RuntimeError(
                    "embedded terminal did not receive a visible layout rectangle"
                )
            if (
                agent_id != self.selected_agent_id
                or self.active_agent_tab != "latest-tab"
                or not self.embedded_terminal_v2_enabled
            ):
                await self.release_tmux_writer_lease(agent_id)
                self.embedded_terminal_agent_id = None
                self.embedded_terminal_target = None
                self.apply_tmux_class()
                return False
            surface.attach(
                tmux_client_attach_command(leased),
                target=target,
                cwd=str(leased.get("cwd") or Path.home()),
            )
            surface.set_scroll_mode(self.embedded_terminal_scroll_mode)
        except Exception as exc:
            self.embedded_terminal_agent_id = None
            self.embedded_terminal_target = None
            self.apply_tmux_class()
            await self.release_tmux_writer_lease(agent_id)
            self.tmux_runtime_mapping_error_by_agent[agent_id] = str(exc)
            surface.detach()
            return False
        self.embedded_terminal_transition_agent_id = None
        self.apply_tmux_class()
        status = self.query_one_or_none("#tmux-status", Static)
        if status is not None:
            status.update(
                f"Tmux: native {leased.get('pane_id')} · F3 Tabs/Tab terminal · "
                "Ctrl+P palette · PgUp history · Ctrl+J newline"
            )
        surface.focus()
        return True

    async def detach_embedded_tmux_terminal(
        self,
        *,
        release_lease: bool,
        preserve_transition: bool = False,
    ) -> None:
        agent_id = self.embedded_terminal_agent_id
        self.clear_embedded_terminal_scroll_requests()
        surface = self.query_one_or_none(
            "#pbx-terminal-surface", PbxTerminalSurface
        )
        if surface is not None:
            surface.detach(preserve_transition=preserve_transition)
        if not preserve_transition:
            self.embedded_terminal_transition_agent_id = None
        self.embedded_terminal_agent_id = None
        self.embedded_terminal_target = None
        self.apply_tmux_class()
        if release_lease and agent_id:
            await self.release_tmux_writer_lease(agent_id)

    def should_smooth_terminal_handoff(
        self,
        previous_agent_id: str | None,
        agent_id: str,
    ) -> bool:
        if (
            not previous_agent_id
            or previous_agent_id == agent_id
            or not self.embedded_terminal_v2_enabled
            or self.active_agent_tab != "latest-tab"
            or not self.is_tmux_direct_enabled(agent_id)
            or self.active_agent_tab_by_agent.get(agent_id, "latest-tab")
            != "latest-tab"
            or self.embedded_terminal_agent_id != previous_agent_id
        ):
            return False
        surface = self.query_one_or_none(
            "#pbx-terminal-surface", PbxTerminalSurface
        )
        return bool(surface is not None and surface.attached)

    def begin_embedded_terminal_transition(self, agent_id: str) -> None:
        self.embedded_terminal_transition_agent_id = agent_id
        surface = self.query_one_or_none(
            "#pbx-terminal-surface", PbxTerminalSurface
        )
        if surface is not None:
            surface.begin_transition(
                f"Switching native terminal to {agent_id}..."
            )
        status = self.query_one_or_none("#tmux-status", Static)
        if status is not None:
            status.update(f"Tmux: switching native terminal to {agent_id}...")
        self.apply_tmux_class()

    def end_embedded_terminal_transition(self, agent_id: str | None = None) -> None:
        transition_agent_id = self.embedded_terminal_transition_agent_id
        if agent_id is not None and transition_agent_id != agent_id:
            return
        self.embedded_terminal_transition_agent_id = None
        surface = self.query_one_or_none(
            "#pbx-terminal-surface", PbxTerminalSurface
        )
        if surface is not None:
            surface.end_transition()
        self.apply_tmux_class()

    def clear_embedded_terminal_scroll_requests(self) -> None:
        self.embedded_terminal_scroll_generation += 1
        self.embedded_terminal_scroll_pending = 0
        self.embedded_terminal_scroll_worker_active = False

    def on_terminal_scroll_requested(
        self,
        event: TerminalScrollRequested,
    ) -> None:
        surface = self.embedded_terminal_surface()
        if surface is None or event.control is not surface:
            return
        signed_ticks = event.ticks * (-1 if event.direction < 0 else 1)
        pending = self.embedded_terminal_scroll_pending + signed_ticks
        max_ticks = max(
            1,
            EMBEDDED_TERMINAL_SCROLL_MAX_LINES
            // EMBEDDED_TERMINAL_SCROLL_LINES_PER_TICK,
        )
        self.embedded_terminal_scroll_pending = max(
            -max_ticks,
            min(max_ticks, pending),
        )
        if self.mouse_debug_enabled:
            self.log.debug(
                "embedded terminal scroll request "
                f"agent={self.embedded_terminal_agent_id!r} "
                f"ticks={signed_ticks} pending={self.embedded_terminal_scroll_pending}"
            )
        if not self.embedded_terminal_scroll_worker_active:
            self.embedded_terminal_scroll_worker_active = True
            generation = self.embedded_terminal_scroll_generation
            self.run_async_worker(
                lambda generation=generation: self.flush_embedded_terminal_scroll_requests(
                    generation
                ),
                name="embedded-terminal-scroll",
                group="embedded-terminal-scroll",
                exit_on_error=False,
            )
        event.stop()

    async def flush_embedded_terminal_scroll_requests(
        self,
        generation: int,
    ) -> None:
        try:
            while generation == self.embedded_terminal_scroll_generation:
                await asyncio.sleep(EMBEDDED_TERMINAL_SCROLL_COALESCE_SECONDS)
                ticks = self.embedded_terminal_scroll_pending
                self.embedded_terminal_scroll_pending = 0
                if not ticks:
                    return
                await self.scroll_embedded_tmux_terminal(ticks, generation)
        finally:
            if generation == self.embedded_terminal_scroll_generation:
                self.embedded_terminal_scroll_worker_active = False

    async def scroll_embedded_tmux_terminal(
        self,
        ticks: int,
        generation: int,
    ) -> bool:
        agent_id = self.embedded_terminal_agent_id
        surface = self.embedded_terminal_surface()
        if not agent_id or surface is None:
            return False
        mapping = await self.fetch_tmux_runtime_mapping(agent_id)
        if (
            generation != self.embedded_terminal_scroll_generation
            or mapping is None
            or agent_id != self.embedded_terminal_agent_id
            or surface is not self.embedded_terminal_surface()
        ):
            return False
        pane_id = str(mapping.get("pane_id") or "").strip()
        if not pane_id or str(mapping.get("state") or "") != "ready":
            return False
        mapped_target = f"{mapping.get('server_id')}:{pane_id}"
        if (
            mapped_target != self.embedded_terminal_target
            or surface.target != mapped_target
        ):
            return False
        direction = -1 if ticks < 0 else 1
        lines = min(
            EMBEDDED_TERMINAL_SCROLL_MAX_LINES,
            max(1, abs(ticks)) * EMBEDDED_TERMINAL_SCROLL_LINES_PER_TICK,
        )
        try:
            acted = await asyncio.to_thread(
                tmux_support.scroll_pane_copy_mode,
                pane_id,
                direction,
                lines=lines,
                socket_path=str(mapping.get("socket_path") or "") or None,
            )
        except Exception as exc:
            self.notify(f"Embedded tmux scrollback failed: {exc}", severity="warning")
            return False
        return acted

    async def enter_embedded_tmux_scrollback(self) -> bool:
        agent_id = self.embedded_terminal_agent_id
        surface = self.embedded_terminal_surface()
        if not agent_id or surface is None:
            self.notify(
                "Focus a live embedded tmux terminal before entering scrollback.",
                severity="warning",
            )
            return False
        mapping = await self.fetch_tmux_runtime_mapping(agent_id)
        if (
            mapping is None
            or agent_id != self.embedded_terminal_agent_id
            or surface is not self.embedded_terminal_surface()
        ):
            self.notify("The embedded tmux runtime mapping changed.", severity="warning")
            return False
        pane_id = str(mapping.get("pane_id") or "").strip()
        if not pane_id or str(mapping.get("state") or "") != "ready":
            self.notify("The embedded tmux runtime is not ready.", severity="warning")
            return False
        mapped_target = f"{mapping.get('server_id')}:{pane_id}"
        if (
            mapped_target != self.embedded_terminal_target
            or surface.target != mapped_target
        ):
            self.notify("The embedded tmux target no longer matches its mapping.", severity="warning")
            return False
        try:
            await asyncio.to_thread(
                tmux_support.enter_pane_copy_mode,
                pane_id,
                socket_path=str(mapping.get("socket_path") or "") or None,
            )
        except Exception as exc:
            self.notify(f"Unable to enter tmux scrollback: {exc}", severity="warning")
            return False
        surface.focus()
        self.notify("Tmux scrollback active; use arrows, Page Up/Down, or swipe.")
        return True

    def schedule_tmux_writer_lease_renewal(self) -> None:
        if not self.embedded_terminal_agent_id:
            return
        self.run_async_worker(
            self.renew_embedded_tmux_writer_lease_if_active,
            name="tmux-writer-lease-renew",
            group="tmux-writer-lease",
            exclusive=True,
        )

    async def renew_embedded_tmux_writer_lease_if_active(self) -> None:
        agent_id = self.embedded_terminal_agent_id
        if not agent_id:
            return
        if self.embedded_terminal_surface() is None:
            await self.detach_embedded_tmux_terminal(release_lease=True)
            return
        mapping = await self.acquire_tmux_writer_lease(agent_id)
        if mapping is None:
            await self.detach_embedded_tmux_terminal(release_lease=True)
            self.notify(
                f"Embedded terminal writer lease was lost for {agent_id}; using capture fallback.",
                severity="warning",
            )
            await self.load_tmux_capture(agent_id)
            return
        if self.embedded_terminal_surface() is None:
            # State may change while the renewal request is in flight. Release
            # the just-renewed lease instead of allowing the timer to resurrect
            # a hidden or detached embedded client.
            await self.detach_embedded_tmux_terminal(release_lease=True)

    async def resolve_runtime_pop_client(
        self,
        agent_id: str,
        mapping: dict[str, Any],
        *,
        direction: str,
    ) -> RuntimeTmuxClient:
        identity = runtime_mapping_server_identity(mapping)
        if direction == "out":
            return await asyncio.to_thread(
                resolve_invoking_outer_client,
                identity,
                tui_pane_id=str(os.environ.get("TMUX_PANE") or ""),
                origin_session_name=str(mapping.get("origin_session_name") or ""),
            )
        client = self.tmux_pop_client_by_agent.get(agent_id)
        if client is None:
            raise ValueError(
                "cannot pop in safely: this TUI has no active pop-out client transaction"
            )
        clients = await asyncio.to_thread(list_runtime_clients, identity)
        exact = tuple(
            item
            for item in clients
            if item.tty == client.tty
            and (client.client_pid is None or item.client_pid == client.client_pid)
        )
        if len(exact) != 1:
            raise ValueError(
                "cannot pop in safely: the recorded tmux client is no longer live"
            )
        runtime_session = str(mapping.get("session_name") or "")
        if exact[0].session_name != runtime_session:
            raise ValueError(
                "cannot pop in safely: the recorded tmux client is not attached "
                f"to runtime session {runtime_session!r}"
            )
        return exact[0]

    async def pop_runtime(self, direction: str) -> bool:
        agent_id = self.selected_agent_id
        if not agent_id:
            self.notify("Select an Agent or Operator first.", severity="warning")
            return False
        mapping = await self.fetch_tmux_runtime_mapping(agent_id)
        if mapping is None:
            self.notify("No managed tmux runtime mapping is available.", severity="warning")
            return False
        resolved_client: RuntimeTmuxClient | None = None
        try:
            mode = normalize_runtime_server_mode(mapping.get("server_mode"))
            force_suspend = self.tmux_popout_mode == "suspend_attach" and direction == "out"
            if force_suspend:
                plan = RuntimePopPlan(
                    "suspend_attach",
                    tmux_client_attach_command(mapping),
                    str(mapping.get("session_name") or ""),
                )
            else:
                if mode is not RuntimeServerMode.DEDICATED:
                    resolved_client = await self.resolve_runtime_pop_client(
                        agent_id,
                        mapping,
                        direction=direction,
                    )
                plan = runtime_pop_plan(
                    mapping,
                    direction=direction,
                    origin_client_tty=(resolved_client.tty if resolved_client else None),
                )
            if self.tmux_popout_mode == "switch_client" and plan.action.startswith(
                "suspend"
            ):
                raise ValueError(
                    "switch-client pop-out requires an integrated outer tmux runtime"
                )
        except ValueError as exc:
            self.notify(str(exc), severity="warning")
            return False
        await self.detach_embedded_tmux_terminal(release_lease=True)
        if plan.action == "suspend_attach":
            with self.suspend():
                result = execute_runtime_pop_plan(plan)
        else:
            result = await asyncio.to_thread(execute_runtime_pop_plan, plan)
        if result.returncode != 0:
            self.notify(result.stderr.strip() or "tmux pop failed", severity="error")
            await self.load_tmux_capture(agent_id)
            return False
        if direction == "out" and resolved_client is not None:
            self.tmux_pop_client_by_agent[agent_id] = resolved_client
        elif direction == "in":
            self.tmux_pop_client_by_agent.pop(agent_id, None)
        if direction == "in":
            await self.load_tmux_capture(agent_id)
        return True

    async def resolve_tmux_plan_selector_pane(
        self,
        agent_id: str,
        panes: list[tmux_support.TmuxPane],
    ) -> tmux_support.TmuxPane | None:
        if agent_id in self.tmux_detached_agent_ids:
            return None
        agent = self.agents.get(agent_id, {"agent_id": agent_id})
        candidates = [
            pane
            for pane in tmux_support.ranked_panes_for_agent(
                self.tmux_candidate_panes_for_agent(agent, panes),
                agent,
            )
            if tmux_support.pane_matches_agent(pane, agent)
        ]
        selector_matches = await self.tmux_plan_selector_matches(candidates)
        if len(selector_matches) != 1:
            self.update_tmux_plan_selector_state(agent_id, "")
            return None
        pane, displayed = selector_matches[0]
        self.update_tmux_plan_selector_state(
            agent_id,
            displayed,
            pane_id=pane.pane_id,
        )
        return pane

    async def tmux_plan_selector_matches(
        self,
        panes: Iterable[tmux_support.TmuxPane],
    ) -> list[tuple[tmux_support.TmuxPane, str]]:
        matches: list[tuple[tmux_support.TmuxPane, str]] = []
        seen_pane_ids: set[str] = set()
        for pane in panes:
            if pane.pane_id in seen_pane_ids:
                continue
            seen_pane_ids.add(pane.pane_id)
            try:
                captured = await asyncio.to_thread(
                    tmux_support.capture_pane,
                    pane.pane_id,
                    lines=self.tmux_capture_lines,
                )
            except Exception:
                continue
            displayed = self.crop_tmux_capture_for_display(captured or "")
            if contains_codex_native_plan_selector(displayed):
                matches.append((pane, displayed))
        return matches

    def update_tmux_plan_selector_state(
        self,
        agent_id: str,
        captured: str,
        *,
        pane_id: str | None = None,
    ) -> bool:
        was_pending = agent_id in self.tmux_plan_selector_agent_ids
        indices = set(codex_native_plan_selector_indices(captured))
        is_pending = bool(indices)
        if is_pending:
            self.tmux_plan_selector_agent_ids.add(agent_id)
            self.tmux_plan_selector_indices_by_agent[agent_id] = indices
            if pane_id:
                self.tmux_plan_selector_pane_by_agent[agent_id] = pane_id
        else:
            self.tmux_plan_selector_agent_ids.discard(agent_id)
            self.tmux_plan_selector_pane_by_agent.pop(agent_id, None)
            self.tmux_plan_selector_indices_by_agent.pop(agent_id, None)
        if was_pending == is_pending:
            return False
        self.update_agent_title()
        self.render_unseen_attention()
        return True

    def native_plan_selector_indices_for_pane(
        self,
        agent_id: str,
        pane_id: str,
    ) -> set[int]:
        indices = set(self.tmux_plan_selector_indices_by_agent.get(agent_id, set()))
        stream = self.query_one_or_none("#tmux-stream", TextArea)
        visible_pane_id = self.tmux_pane_id_from_capture_key(self.tmux_visible_capture_key)
        if stream is not None and visible_pane_id == pane_id:
            visible_indices = set(codex_native_plan_selector_indices(stream.text))
            indices.update(visible_indices)
            visible_agent_id = self.tmux_agent_id_from_capture_key(
                self.tmux_visible_capture_key
            )
            if visible_agent_id:
                self.update_tmux_plan_selector_state(
                    visible_agent_id,
                    stream.text,
                    pane_id=pane_id,
                )
        return indices

    def available_native_plan_selector_indices(self, agent_id: str) -> set[int]:
        pane_id = self.tmux_plan_selector_pane_by_agent.get(agent_id)
        if pane_id:
            return self.native_plan_selector_indices_for_pane(agent_id, pane_id)
        stream = self.query_one_or_none("#tmux-stream", TextArea)
        if stream is None:
            return set(self.tmux_plan_selector_indices_by_agent.get(agent_id, set()))
        visible_pane_id = self.tmux_visible_plan_selector_pane_id()
        if visible_pane_id is None:
            return set(self.tmux_plan_selector_indices_by_agent.get(agent_id, set()))
        return self.native_plan_selector_indices_for_pane(agent_id, visible_pane_id)

    def tmux_visible_native_plan_selector_pending(self) -> bool:
        return self.tmux_visible_plan_selector_pane_id() is not None

    def tmux_native_plan_selector_pending(self, agent_id: str) -> bool:
        if agent_id in self.tmux_plan_selector_agent_ids:
            if (
                agent_id == self.selected_agent_id
                and str(self.tmux_visible_capture_key or "").startswith(f"{agent_id}:")
            ):
                stream = self.query_one_or_none("#tmux-stream", TextArea)
                if stream is not None and not contains_codex_native_plan_selector(stream.text):
                    self.update_tmux_plan_selector_state(agent_id, stream.text)
                    return False
                if stream is not None:
                    self.update_tmux_plan_selector_state(
                        agent_id,
                        stream.text,
                        pane_id=self.tmux_visible_pane_id_for_agent(agent_id),
                    )
            return True
        if agent_id != self.selected_agent_id:
            return False
        if not str(self.tmux_visible_capture_key or "").startswith(f"{agent_id}:"):
            return False
        stream = self.query_one_or_none("#tmux-stream", TextArea)
        if stream is None or not contains_codex_native_plan_selector(stream.text):
            return False
        pane_id = self.tmux_visible_pane_id_for_agent(agent_id)
        self.update_tmux_plan_selector_state(
            agent_id,
            stream.text,
            pane_id=pane_id,
        )
        self.update_agent_title()
        self.render_unseen_attention()
        return True

    def tmux_agent_id_from_capture_key(self, cache_key: str | None) -> str | None:
        value = str(cache_key or "")
        if ":" not in value:
            return None
        agent_id, pane_id = value.rsplit(":", 1)
        if not agent_id or not pane_id:
            return None
        return agent_id

    def tmux_pane_id_from_capture_key(self, cache_key: str | None) -> str | None:
        value = str(cache_key or "")
        if ":" not in value:
            return None
        _, pane_id = value.rsplit(":", 1)
        return pane_id or None

    def tmux_visible_plan_selector_pane_id(self) -> str | None:
        stream = self.query_one_or_none("#tmux-stream", TextArea)
        if stream is None or not contains_codex_native_plan_selector(stream.text):
            return None
        pane_id = self.tmux_pane_id_from_capture_key(self.tmux_visible_capture_key)
        agent_id = self.tmux_agent_id_from_capture_key(self.tmux_visible_capture_key)
        if agent_id and pane_id:
            self.update_tmux_plan_selector_state(
                agent_id,
                stream.text,
                pane_id=pane_id,
            )
        return pane_id

    def tmux_visible_pane_id_for_agent(self, agent_id: str) -> str | None:
        prefix = f"{agent_id}:"
        cache_key = str(self.tmux_visible_capture_key or "")
        if not cache_key.startswith(prefix):
            return None
        return self.tmux_pane_id_from_capture_key(cache_key)

    def prepare_tmux_stream_for_capture(
        self,
        stream: TextArea,
        *,
        cache_key: str,
        pane: tmux_support.TmuxPane,
    ) -> bool:
        if self.tmux_visible_capture_key == cache_key:
            return False
        self.tmux_visible_capture_key = cache_key
        stream.text = f"Loading tmux pane {pane.pane_id} ({pane.target_label})..."
        self.snap_tmux_stream_to_bottom(stream)
        return True

    def update_tmux_status(
        self,
        status: Static,
        text: str,
        *,
        cache_key: str,
    ) -> bool:
        if self.tmux_last_status_by_agent.get(cache_key) == text:
            return False
        self.tmux_last_status_by_agent[cache_key] = text
        status.update(text)
        return True

    def tmux_capture_mode_label(self) -> str:
        if self.tmux_capture_lines <= 0:
            return "visible"
        return f"scrollback {self.tmux_capture_lines}"

    def crop_tmux_capture_for_display(self, captured: str) -> str:
        lines = captured.splitlines()
        if not lines:
            return captured
        search_start = max(0, len(lines) - 12)
        for index in range(len(lines) - 1, search_start - 1, -1):
            if CODEX_STATUS_LINE_PATTERN.search(lines[index]):
                body = "\n".join(lines[:index]).rstrip("\n")
                return body or "(empty tmux pane)"
        return captured

    def update_tmux_stream(
        self,
        stream: TextArea,
        captured: str,
        *,
        cache_key: str,
    ) -> bool:
        previous = self.tmux_last_capture_by_pane.get(cache_key)
        self.tmux_last_capture_by_pane[cache_key] = captured
        if previous == captured and stream.text == captured:
            return False
        if stream.text == captured:
            return False
        at_bottom = self.tmux_stream_is_at_bottom(stream)
        scroll_y = stream.scroll_y
        scroll_target_y = stream.scroll_target_y
        anchor = self.tmux_stream_content_anchor(stream.text, scroll_y)
        stream.text = captured
        if at_bottom:
            self.snap_tmux_stream_to_bottom(stream)
        else:
            anchored_y = self.tmux_stream_anchored_scroll_y(
                captured,
                anchor,
                fallback=scroll_y,
            )
            target_delta = scroll_target_y - scroll_y
            stream.scroll_y = anchored_y
            stream.scroll_target_y = max(0.0, anchored_y + target_delta)
        return True

    def tmux_stream_content_anchor(
        self,
        text: str,
        scroll_y: float,
    ) -> tuple[tuple[str, ...], int, float] | None:
        lines = text.splitlines()
        if not lines:
            return None
        index = min(max(0, int(scroll_y)), len(lines) - 1)
        start = max(0, index - 1)
        end = min(len(lines), index + 2)
        return tuple(lines[start:end]), start, float(scroll_y)

    def tmux_stream_anchored_scroll_y(
        self,
        text: str,
        anchor: tuple[tuple[str, ...], int, float] | None,
        *,
        fallback: float,
    ) -> float:
        if anchor is None:
            return fallback
        context, old_start, old_scroll = anchor
        if not context:
            return fallback
        lines = text.splitlines()
        width = len(context)
        matches = [
            index
            for index in range(0, max(0, len(lines) - width + 1))
            if tuple(lines[index : index + width]) == context
        ]
        if not matches:
            return fallback
        new_start = min(matches, key=lambda index: abs(index - old_start))
        return max(0.0, old_scroll + (new_start - old_start))

    def tmux_stream_is_at_bottom(self, stream: TextArea) -> bool:
        max_scroll_y = float(getattr(stream, "max_scroll_y", 0) or 0)
        if max_scroll_y <= 0:
            return True
        scroll_y = float(getattr(stream, "scroll_y", 0) or 0)
        scroll_target_y = float(getattr(stream, "scroll_target_y", scroll_y) or 0)
        return max(scroll_y, scroll_target_y) >= max_scroll_y - 1

    def should_restore_tmux_stream_tail_after_resize(self) -> bool:
        if self.active_agent_tab != "latest-tab" or not self.tmux_visible_capture_key:
            return False
        stream = self.query_one_or_none("#tmux-stream", TextArea)
        if stream is None or not stream.text:
            return False
        return self.tmux_stream_is_at_bottom(stream)

    def handle_tmux_stream_focus(self, stream: TextArea) -> None:
        if self.tmux_stream_is_at_bottom(stream):
            self.snap_tmux_stream_to_bottom(stream)

    def snap_tmux_stream_to_bottom(self, stream: TextArea | None = None) -> None:
        if stream is None:
            stream = self.query_one_or_none("#tmux-stream", TextArea)
        if stream is None:
            return
        lines = stream.text.split("\n")
        row = max(0, len(lines) - 1)
        column = len(lines[-1]) if lines else 0
        location = (row, column)
        try:
            stream.move_cursor(location, center=False)
        except Exception:
            stream.selection = (location, location)
        stream.scroll_end(animate=False)
        stream.scroll_x = 0
        stream.scroll_target_x = 0

    def is_operator_tmux_pane(self, pane: tmux_support.TmuxPane) -> bool:
        return pane.session_name == self.operator_tmux_session_name()

    async def reconcile_operator_tmux_targets(self) -> bool:
        if not self.tmux_features_available or not self.tmux_local_direct_context:
            return False
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception:
            return False
        self.tmux_panes = panes
        changed = self.reconcile_operator_tmux_targets_from_panes(panes)
        if changed:
            self.save_settings()
        return changed

    def reconcile_operator_tmux_targets_from_panes(
        self,
        panes: list[tmux_support.TmuxPane],
    ) -> bool:
        changed = False
        for agent in self.ordered_agents(OPERATOR_AGENT_TYPE):
            agent_id = str(agent.get("agent_id") or "").strip()
            if not agent_id or agent_id in self.tmux_detached_agent_ids:
                continue
            if self.clear_inactive_operator_fork_tmux_state(agent_id, agent, panes):
                changed = True
                continue
            matches = [
                pane
                for pane in panes
                if self.tmux_pane_allowed_for_agent(agent, pane)
            ]
            saved_pane = self.saved_tmux_target_pane_for_agent(
                agent_id,
                agent,
                panes,
            )
            if saved_pane is not None:
                if self.tmux_direct_agent_modes.get(agent_id) is not True:
                    self.tmux_direct_agent_modes[agent_id] = True
                    changed = True
                changed = self.update_local_agent_tmux_pane(agent_id, saved_pane) or changed
                continue
            if self.tmux_agent_targets.get(agent_id):
                self.clear_saved_tmux_target(agent_id)
                changed = True
            if len(matches) != 1:
                continue
            pane = matches[0]
            if self.tmux_agent_targets.get(agent_id) != pane.pane_id:
                self.tmux_agent_targets[agent_id] = pane.pane_id
                changed = True
            if self.tmux_direct_agent_modes.get(agent_id) is not True:
                self.tmux_direct_agent_modes[agent_id] = True
                changed = True
            self.tmux_detached_agent_ids.discard(agent_id)
            changed = self.update_local_agent_tmux_pane(agent_id, pane) or changed
        changed = self.prune_selected_operator_fork_targets() or changed
        return changed

    def saved_tmux_target_pane_for_agent(
        self,
        agent_id: str,
        agent: dict[str, Any],
        panes: Iterable[tmux_support.TmuxPane],
    ) -> tmux_support.TmuxPane | None:
        saved = str(self.tmux_agent_targets.get(agent_id) or "").strip()
        if not saved:
            return None
        for pane in panes:
            if pane.pane_id != saved and pane.target_label != saved:
                continue
            if self.tmux_pane_allowed_for_agent(agent, pane):
                return pane
            # A stable pane id is stronger ownership evidence than mutable
            # tmux window/title text. Codex may update those labels while a
            # long-lived Operator remains in the PBX-owned operator session.
            # Accept that explicit binding only when no other PBX entity also
            # claims the pane.
            if (
                pane.pane_id == saved
                and self.agent_type(agent) == OPERATOR_AGENT_TYPE
                and self.is_operator_tmux_pane(pane)
                and set(self.agent_ids_for_tmux_pane(pane.pane_id)) <= {agent_id}
            ):
                return pane
        return None

    def update_local_agent_tmux_pane(
        self,
        agent_id: str,
        pane: tmux_support.TmuxPane,
    ) -> bool:
        agent = self.agents.get(agent_id)
        if agent is None:
            return False
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        if metadata.get("tmux_pane_id") == pane.pane_id:
            return False
        agent["metadata"] = {**metadata, "tmux_pane_id": pane.pane_id}
        return True

    def prune_selected_operator_fork_targets(self) -> bool:
        changed = False
        for logical_operator_id, target_key in list(
            self.selected_operator_fork_target_by_operator.items()
        ):
            if ":" not in target_key:
                self.selected_operator_fork_target_by_operator.pop(logical_operator_id, None)
                changed = True
                continue
            fork_agent_id, pane_id = target_key.rsplit(":", 1)
            fork = self.agents.get(fork_agent_id)
            if (
                fork is None
                or self.operator_role(fork) != OPERATOR_ROLE_FORK
                or self.logical_operator_id_for_agent(fork) != logical_operator_id
                or self.tmux_agent_targets.get(fork_agent_id) != pane_id
            ):
                self.selected_operator_fork_target_by_operator.pop(logical_operator_id, None)
                changed = True
        return changed

    def tmux_pane_matches_operator_agent(
        self,
        agent: dict[str, Any],
        pane: tmux_support.TmuxPane,
    ) -> bool:
        agent_id = str(agent.get("agent_id") or "").strip()
        if not agent_id:
            return False
        return pane.window_name == agent_id or pane.title == agent_id

    def tmux_pane_allowed_for_agent(
        self,
        agent: dict[str, Any],
        pane: tmux_support.TmuxPane,
    ) -> bool:
        agent_type = self.agent_type(agent)
        if agent_type == CALLER_AGENT_TYPE:
            return not self.is_operator_tmux_pane(pane)
        if agent_type == OPERATOR_AGENT_TYPE:
            return (
                self.is_operator_tmux_pane(pane)
                and self.tmux_pane_matches_operator_agent(agent, pane)
            )
        return True

    def tmux_candidate_panes_for_agent(
        self,
        agent: dict[str, Any],
        panes: list[tmux_support.TmuxPane],
    ) -> list[tmux_support.TmuxPane]:
        return [
            pane for pane in panes if self.tmux_pane_allowed_for_agent(agent, pane)
        ]

    def clear_saved_tmux_target(self, agent_id: str) -> None:
        self.tmux_agent_targets.pop(agent_id, None)
        self.tmux_manual_override_agent_ids.discard(agent_id)

    def clear_inactive_operator_fork_tmux_state(
        self,
        agent_id: str,
        agent: dict[str, Any],
        panes: list[tmux_support.TmuxPane],
    ) -> bool:
        if self.operator_role(agent) != OPERATOR_ROLE_FORK:
            return False
        if self.operator_fork_is_running(agent):
            return False
        if any(self.tmux_pane_allowed_for_agent(agent, pane) for pane in panes):
            return False
        candidate_pane_ids = {
            str(self.tmux_agent_targets.get(agent_id) or "").strip(),
            str(
                (
                    agent.get("metadata")
                    if isinstance(agent.get("metadata"), dict)
                    else {}
                ).get("tmux_pane_id")
                or ""
            ).strip(),
        }
        candidate_pane_ids.discard("")
        live_pane_ids = {pane.pane_id for pane in panes} | {
            pane.target_label for pane in panes
        }
        if candidate_pane_ids and candidate_pane_ids & live_pane_ids:
            return False
        changed = (
            agent_id in self.tmux_agent_targets
            or agent_id in self.tmux_direct_agent_modes
            or agent_id in self.tmux_manual_override_agent_ids
            or agent_id in self.tmux_liveness_by_agent
            or agent_id in self.tmux_plan_selector_agent_ids
            or agent_id in self.tmux_plan_selector_pane_by_agent
            or agent_id in self.tmux_plan_selector_indices_by_agent
        )
        if not changed:
            return False
        self.clear_operator_tmux_state(agent_id)
        return True

    def resolve_tmux_pane(
        self,
        agent_id: str,
        panes: list[tmux_support.TmuxPane],
    ) -> tuple[tmux_support.TmuxPane | None, str]:
        if agent_id in self.tmux_detached_agent_ids:
            return None, "detached"
        agent = self.agents.get(agent_id, {"agent_id": agent_id})
        manual_target = self.tmux_agent_targets.get(agent_id)
        if manual_target:
            for pane in panes:
                if pane.pane_id == manual_target or pane.target_label == manual_target:
                    if not self.tmux_pane_allowed_for_agent(agent, pane):
                        self.clear_saved_tmux_target(agent_id)
                        self.save_settings()
                        break
                    if (
                        agent_id not in self.tmux_manual_override_agent_ids
                        and not tmux_support.pane_matches_agent(pane, agent)
                    ):
                        self.clear_saved_tmux_target(agent_id)
                        self.save_settings()
                        break
                    return pane, "manual"
            else:
                self.clear_saved_tmux_target(agent_id)
                self.save_settings()
        candidate_panes = self.tmux_candidate_panes_for_agent(agent, panes)
        if self.agent_type(agent) == OPERATOR_AGENT_TYPE and len(candidate_panes) == 1:
            return candidate_panes[0], "auto"
        pane = tmux_support.choose_pane_for_agent(candidate_panes, agent)
        if pane is None:
            return None, "auto"
        return pane, "auto"

    async def select_next_tmux_pane(self) -> None:
        agent_id = self.selected_agent_id
        if not agent_id:
            return
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception as exc:
            stream = self.query_one_or_none("#tmux-stream", TextArea)
            if stream is not None:
                stream.text = f"Unable to list tmux panes: {exc}"
            return
        self.tmux_panes = panes
        if not panes:
            stream = self.query_one_or_none("#tmux-stream", TextArea)
            if stream is not None:
                stream.text = "No tmux panes are available."
            return
        agent = self.agents.get(agent_id, {"agent_id": agent_id})
        ranked = tmux_support.ranked_panes_for_agent(
            self.tmux_candidate_panes_for_agent(agent, panes),
            agent,
        )
        if not ranked:
            stream = self.query_one_or_none("#tmux-stream", TextArea)
            if stream is not None:
                stream.text = "No tmux panes match this agent type."
            return
        current = self.tmux_agent_targets.get(agent_id)
        current_index = next(
            (
                index
                for index, pane in enumerate(ranked)
                if pane.pane_id == current or pane.target_label == current
            ),
            -1,
        )
        pane = ranked[(current_index + 1) % len(ranked)]
        self.tmux_agent_targets[agent_id] = pane.pane_id
        self.tmux_manual_override_agent_ids.add(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.save_settings()
        await self.load_tmux_capture(agent_id)

    async def set_tmux_auto(self) -> None:
        agent_id = self.selected_agent_id
        if not agent_id:
            return
        self.tmux_agent_targets.pop(agent_id, None)
        self.tmux_manual_override_agent_ids.discard(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.save_settings()
        await self.load_tmux_capture(agent_id)

    async def detach_tmux_pane(self) -> None:
        agent_id = self.selected_agent_id
        if not agent_id:
            return
        self.tmux_agent_targets.pop(agent_id, None)
        self.tmux_manual_override_agent_ids.discard(agent_id)
        self.tmux_detached_agent_ids.add(agent_id)
        self.tmux_visible_capture_key = None
        self.save_settings()
        status = self.query_one_or_none("#tmux-status", Static)
        stream = self.query_one_or_none("#tmux-stream", TextArea)
        if status is not None:
            status.update(f"Tmux: detached from {agent_id}")
        if stream is not None:
            stream.text = "Detached. Use Auto or Select Pane to reconnect."

    async def load_thread(self, agent_id: str) -> None:
        thread_detail = self.query_one("#thread-detail", TextArea)
        try:
            response = await self.api_client().get(
                f"/v1/agents/{agent_id}/thread",
                params={"limit": 100},
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            thread = response.json()
        except Exception as exc:
            self.thread_items = {}
            self.thread_order = []
            self.marked_thread_item_ids.clear()
            self.render_thread([])
            self.render_plan_choice_panel(None)
            thread_detail.text = f"Unable to load thread for {agent_id}: {exc}"
            return
        thread = self.order_thread_for_display(thread)
        self.thread_items = {item["item_id"]: item for item in thread}
        self.thread_order = [item["item_id"] for item in thread]
        self.marked_thread_item_ids.intersection_update(self.thread_items)
        self.render_thread(thread)
        if thread:
            item_id = (
                self.selected_thread_item_id
                if self.selected_thread_item_id in self.thread_items
                else thread[0]["item_id"]
            )
            self.select_thread_item(item_id)
        else:
            self.selected_thread_item_id = None
            self.selected_thread_item_id_by_agent.pop(agent_id, None)
            self.thread_order = []
            self.render_plan_choice_panel(None)
            thread_detail.text = f"No thread history for {agent_id}."

    def order_thread_for_display(
        self, thread: list[dict[str, Any]]
    ) -> list[dict[str, Any]]:
        return sorted(
            thread,
            key=lambda item: (float(item["created_at"]), str(item["item_id"])),
            reverse=True,
        )

