    def on_select_changed(self, event: Select.Changed) -> None:
        if event.select.id == "codex-model-preset":
            preset = codex_model_preset_for(event.value)
            if preset is not None:
                self.update_codex_model_status(preset)

    async def send_input(self) -> None:
        if self.is_tmux_direct_enabled():
            focused_input = (
                self.focused
                if isinstance(self.focused, TextArea)
                and self.focused.id in {"message", "tmux-message"}
                else None
            )
            tmux_input = self.query_one_or_none("#tmux-message", TextArea)
            message_input = self.query_one_or_none("#message", TextArea)
            if focused_input is not None and focused_input.text.strip():
                await self.send_tmux_text_area_input(focused_input)
                return
            if tmux_input is not None and tmux_input.text.strip():
                await self.send_tmux_text_area_input(tmux_input)
                return
            if message_input is not None and message_input.text.strip():
                await self.send_tmux_text_area_input(message_input)
                return
            if tmux_input is not None:
                await self.send_tmux_text_area_input(tmux_input)
            return
        message_input = self.query_one("#message", TextArea)
        agent_id = self.sent_history_agent_id(message_input) or ""
        message = message_input.text.strip()
        if not message:
            return
        if not agent_id:
            if await self.execute_local_slash_command_from_input(message_input, message):
                return
            return
        if is_plan_toggle_message(message):
            toggled = await self.toggle_plan_mode_from_input(agent_id, via_tmux=False)
            if toggled:
                self.record_sent_message(agent_id, message)
                self.set_agent_draft_text(agent_id, message_input, "")
            return
        selection = parse_plan_selection_command(message)
        if selection is not None:
            sent_selection = await self.send_plan_selection(
                agent_id,
                selection,
                via_tmux=False,
            )
            if sent_selection:
                self.record_sent_message(agent_id, message)
                self.set_agent_draft_text(agent_id, message_input, "")
            return
        if await self.execute_local_slash_command_from_input(message_input, message):
            return
        routed_agent_id = await self.route_operator_prompt_to_fork(agent_id, message)
        if routed_agent_id is None:
            return
        agent_id = routed_agent_id
        if self.should_send_plan_prompt(agent_id, message):
            expanded_message = await self.expand_prompt_references(
                agent_id,
                message,
            )
            if expanded_message is None:
                return
            sent_plan = await self.send_plan_prompt(
                agent_id,
                expanded_message,
                via_tmux=False,
            )
            if sent_plan:
                self.record_sent_message(agent_id, message)
                self.clear_pending_slash_command(agent_id)
                self.set_agent_draft_text(agent_id, message_input, "")
            return
        pending_slash_commands = self.pending_slash_command_sequence_for_message(
            agent_id, message
        )
        expanded_message = await self.expand_prompt_references(agent_id, message)
        if expanded_message is None:
            return
        for pending_slash in pending_slash_commands:
            await self.queue_command(
                agent_id,
                "send_input",
                {"message": pending_slash},
            )
        command = await self.queue_command(
            agent_id,
            "send_input",
            {"message": expanded_message},
        )
        self.clear_pending_slash_command(agent_id)
        self.record_sent_message(agent_id, message)
        self.set_agent_draft_text(agent_id, message_input, "")
        self.notify_queued_command(agent_id, "Input", command)
        await self.refresh_events()
        await self.load_thread(agent_id)

    def resize_message_input(self) -> None:
        message_input = self.query_one_or_none("#message", TextArea)
        if message_input is None:
            return
        if self.is_tiny_layout():
            message_input.styles.height = 1
            message_input.styles.min_height = 1
            message_input.styles.max_height = 1
            composer_inputs = self.query_one("#composer-inputs")
            composer_inputs.styles.height = 1
            composer_inputs.styles.min_height = 1
            composer_inputs.styles.max_height = 1
            composer = self.query_one("#composer")
            composer.styles.height = 6
            composer.styles.min_height = 6
            composer.styles.max_height = 6
            return
        line_count = max(1, message_input.text.count("\n") + 1)
        height = min(
            FOLLOW_UP_MAX_HEIGHT,
            max(FOLLOW_UP_MIN_HEIGHT, line_count + 2),
        )
        message_input.styles.height = height
        self.query_one("#composer-inputs").styles.height = height
        self.query_one("#composer").styles.height = height + 7

    async def send_tmux_input(self) -> None:
        message_input = self.query_one("#tmux-message", TextArea)
        await self.send_tmux_text_area_input(message_input)

    async def send_tmux_text_area_input(self, message_input: TextArea) -> None:
        agent_id = self.sent_history_agent_id(message_input) or ""
        message = message_input.text
        if not message.strip():
            return
        if not agent_id:
            if await self.execute_local_slash_command_from_input(
                message_input, message.strip()
            ):
                return
            return
        if is_plan_toggle_message(message):
            toggled = await self.toggle_plan_mode_from_input(agent_id, via_tmux=True)
            if toggled:
                self.record_sent_message(agent_id, message)
                self.set_agent_draft_text(agent_id, message_input, "")
                await self.load_tmux_capture(agent_id)
            return
        selection = parse_plan_selection_command(message)
        if selection is not None:
            sent_selection = await self.send_plan_selection(
                agent_id,
                selection,
                via_tmux=True,
            )
            if sent_selection:
                self.record_sent_message(agent_id, message)
                self.set_agent_draft_text(agent_id, message_input, "")
            return
        if await self.execute_local_slash_command_from_input(
            message_input, message.strip()
        ):
            return
        routed_agent_id = await self.route_operator_prompt_to_fork(agent_id, message)
        if routed_agent_id is None:
            return
        agent_id = routed_agent_id
        if self.should_send_plan_prompt(agent_id, message):
            expanded_message = await self.expand_prompt_references(
                agent_id,
                message,
            )
            if expanded_message is None:
                return
            sent_plan = await self.send_plan_prompt(
                agent_id,
                expanded_message,
                via_tmux=True,
            )
            if sent_plan:
                self.record_sent_message(agent_id, message)
                self.clear_pending_slash_command(agent_id)
                self.set_agent_draft_text(agent_id, message_input, "")
                await self.load_tmux_capture(agent_id)
            return
        pending_slash_commands = self.pending_slash_command_sequence_for_message(
            agent_id, message
        )
        expanded_message = await self.expand_prompt_references(agent_id, message)
        if expanded_message is None:
            return
        for pending_slash in pending_slash_commands:
            sent_slash = await self.send_text_to_tmux(agent_id, pending_slash)
            if not sent_slash:
                return
            await asyncio.sleep(SLASH_COMMAND_FOLLOWUP_DELAY_SECONDS)
        sent = await self.send_text_to_tmux(agent_id, expanded_message)
        if not sent:
            return
        self.clear_pending_slash_command(agent_id)
        self.record_sent_message(agent_id, message)
        await self.record_tmux_joplin_interaction(agent_id, expanded_message)
        self.set_agent_draft_text(agent_id, message_input, "")
        await self.load_tmux_capture(agent_id)

    def pending_slash_command_sequence_for_message(
        self, agent_id: str, message: str
    ) -> list[str]:
        command = self.pending_slash_command_by_agent.get(agent_id)
        body = message.strip()
        if not command or not body:
            return []
        if body.startswith("/"):
            return []
        if command == PLAN_SLASH_COMMAND:
            return [PLAN_SLASH_COMMAND]
        return [command]

    def clear_pending_slash_command(self, agent_id: str) -> None:
        self.pending_slash_command_by_agent.pop(agent_id, None)
        self.update_agent_title()

    def should_send_plan_prompt(self, agent_id: str, message: str) -> bool:
        command = self.pending_slash_command_by_agent.get(agent_id)
        return (
            command == PLAN_SLASH_COMMAND
            and bool(message.strip())
            and not message.strip().startswith("/")
        )

    async def toggle_plan_mode_from_input(
        self,
        agent_id: str,
        *,
        via_tmux: bool,
    ) -> bool:
        if self.plan_mode_state(agent_id) == "pending":
            self.pending_slash_command_by_agent.pop(agent_id, None)
            self.update_agent_title()
            self.notify(f"Plan mode canceled for {agent_id}; /plan was not sent.")
            return True
        return await self.toggle_sent_plan_mode(agent_id, via_tmux=via_tmux)

    async def toggle_sent_plan_mode(
        self,
        agent_id: str,
        *,
        via_tmux: bool | None = None,
    ) -> bool:
        use_tmux = (
            self.is_tmux_direct_enabled(agent_id)
            if via_tmux is None
            else via_tmux
        )
        if use_tmux:
            sent = await self.send_keys_to_tmux(agent_id, PLAN_SLASH_COMMAND)
            if not sent:
                return False
            await self.load_tmux_capture(agent_id)
        else:
            command = await self.queue_command(
                agent_id,
                "send_input",
                {"message": PLAN_SLASH_COMMAND},
            )
            self.notify_queued_command(agent_id, "Plan toggle", command)
            await self.refresh_events()
            await self.load_thread(agent_id)
        if agent_id in self.plan_mode_active_agent_ids:
            self.plan_mode_active_agent_ids.discard(agent_id)
            self.notify(f"Plan mode toggled off for {agent_id}.")
        else:
            self.plan_mode_active_agent_ids.add(agent_id)
            self.notify(f"Plan mode toggled on for {agent_id}.")
        self.pending_slash_command_by_agent.pop(agent_id, None)
        self.update_agent_title()
        self.render_agents()
        return True

    async def send_plan_prompt(
        self,
        agent_id: str,
        message: str,
        *,
        via_tmux: bool,
    ) -> bool:
        plan_prompt = render_plan_prompt(message)
        if via_tmux:
            sent_slash = await self.send_keys_to_tmux(agent_id, PLAN_SLASH_COMMAND)
            if not sent_slash:
                return False
            await asyncio.sleep(PLAN_MODE_FOLLOWUP_DELAY_SECONDS)
            sent_prompt = await self.send_text_to_tmux(agent_id, plan_prompt)
            if not sent_prompt:
                return False
            await self.record_tmux_joplin_interaction(agent_id, plan_prompt)
            self.notify(f"Plan prompt sent to tmux for {agent_id}.")
            self.plan_mode_active_agent_ids.add(agent_id)
            self.update_agent_title()
            self.render_agents()
            return True
        await self.queue_command(
            agent_id,
            "send_input",
            {"message": PLAN_SLASH_COMMAND},
        )
        command = await self.queue_command(
            agent_id,
            "send_input",
            {"message": plan_prompt},
        )
        self.notify_queued_command(agent_id, "Plan prompt", command)
        await self.refresh_events()
        await self.load_thread(agent_id)
        self.plan_mode_active_agent_ids.add(agent_id)
        self.update_agent_title()
        self.render_agents()
        return True

    async def send_text_to_tmux(self, agent_id: str, message: str) -> bool:
        status = self.query_one_or_none("#tmux-status", Static)
        pane = await self.resolve_tmux_send_pane(agent_id, status=status)
        if pane is None:
            return False
        try:
            await asyncio.to_thread(
                tmux_support.send_text,
                pane.pane_id,
                message,
                **self.runtime_tmux_command_kwargs(agent_id),
            )
        except Exception as exc:
            if status is not None:
                status.update(f"Tmux: send failed ({exc})")
            return False
        return True

    async def send_keys_to_tmux(self, agent_id: str, message: str) -> bool:
        status = self.query_one_or_none("#tmux-status", Static)
        pane = await self.resolve_tmux_send_pane(agent_id, status=status)
        if pane is None:
            return False
        try:
            await asyncio.to_thread(
                tmux_support.send_literal_keys,
                pane.pane_id,
                message,
                **self.runtime_tmux_command_kwargs(agent_id),
            )
        except Exception as exc:
            if status is not None:
                status.update(f"Tmux: send failed ({exc})")
            return False
        return True

    async def send_key_to_tmux(self, agent_id: str, key: str) -> bool:
        status = self.query_one_or_none("#tmux-status", Static)
        pane = await self.resolve_tmux_send_pane(agent_id, status=status)
        if pane is None:
            return False
        return await self.send_key_to_tmux_pane(
            pane.pane_id,
            key,
            status=status,
            **self.runtime_tmux_command_kwargs(agent_id),
        )

    async def send_key_to_tmux_pane(
        self,
        pane_id: str,
        key: str,
        *,
        status: Static | None = None,
        tmux_bin: str = "tmux",
        socket_path: str | None = None,
    ) -> bool:
        runtime_kwargs: dict[str, str | None]
        if socket_path is not None or tmux_bin != "tmux":
            runtime_kwargs = {"tmux_bin": tmux_bin, "socket_path": socket_path}
        else:
            runtime_kwargs = self.runtime_tmux_command_kwargs_for_pane(pane_id)
        try:
            await asyncio.to_thread(
                tmux_support.send_key,
                pane_id,
                key,
                **runtime_kwargs,
            )
        except Exception as exc:
            if status is not None:
                status.update(f"Tmux: send failed ({exc})")
            return False
        return True

    async def verify_tmux_hard_stop(self, agent_id: str, key_label: str) -> None:
        await asyncio.sleep(TMUX_HARD_STOP_VERIFY_DELAY_SECONDS)
        first = await self.capture_tmux_display_for_agent(agent_id)
        await asyncio.sleep(TMUX_HARD_STOP_VERIFY_DELAY_SECONDS)
        second = await self.capture_tmux_display_for_agent(agent_id)
        await self.load_tmux_capture(agent_id)
        if first is None or second is None:
            self.notify(
                f"Sent {key_label}; unable to verify tmux pane state.",
                severity="warning",
            )
            return
        if first == second:
            self.notify(f"Sent {key_label}; tmux pane was stable after verification.")
            return
        self.notify(
            f"Sent {key_label}; tmux pane was still changing after verification.",
            severity="warning",
        )

    async def send_escape_to_operator_scope(self, agent_id: str) -> bool:
        agent = self.agents.get(agent_id)
        if (
            agent is None
            or self.agent_type(agent) != OPERATOR_AGENT_TYPE
            or self.operator_role(agent) != OPERATOR_ROLE_ROOT
        ):
            return False
        status = self.query_one_or_none("#tmux-status", Static)
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception as exc:
            if status is not None:
                status.update(f"Tmux: unavailable ({exc})")
            return False
        self.tmux_panes = panes
        logical_operator_id = self.logical_operator_id_for_agent(agent)
        targets: list[tuple[str, tmux_support.TmuxPane]] = []
        root_pane, _mode = self.resolve_tmux_pane(agent_id, panes)
        if root_pane is not None:
            targets.append((agent_id, root_pane))
        for fork, pane in self.operator_fork_pane_targets(logical_operator_id, panes):
            if not self.operator_fork_is_running(fork):
                continue
            fork_agent_id = str(fork.get("agent_id") or "").strip()
            if fork_agent_id:
                targets.append((fork_agent_id, pane))
        deduped: list[tuple[str, tmux_support.TmuxPane]] = []
        seen_panes: set[str] = set()
        for target_agent_id, pane in targets:
            if pane.pane_id in seen_panes:
                continue
            seen_panes.add(pane.pane_id)
            deduped.append((target_agent_id, pane))
        if not deduped:
            if status is not None:
                status.update(f"Tmux: no operator panes for {agent_id}")
            return False
        sent: list[str] = []
        failed: list[str] = []
        for _target_agent_id, pane in deduped:
            if await self.send_key_to_tmux_pane(pane.pane_id, "Escape", status=status):
                sent.append(pane.pane_id)
            else:
                failed.append(pane.pane_id)
        if sent:
            suffix = f"; failed {', '.join(failed)}" if failed else ""
            self.notify(
                f"Sent Escape to {len(sent)} operator pane(s) for {agent_id}{suffix}."
            )
            return True
        return False

    async def send_text_to_tmux_pane(
        self,
        pane_id: str,
        message: str,
        *,
        status: Static | None = None,
    ) -> bool:
        try:
            await asyncio.to_thread(
                tmux_support.send_text,
                pane_id,
                message,
                **self.runtime_tmux_command_kwargs_for_pane(pane_id),
            )
        except Exception as exc:
            if status is not None:
                status.update(f"Tmux: send failed ({exc})")
            return False
        return True

    def agent_metadata(self, agent: dict[str, Any] | None) -> dict[str, Any]:
        if not isinstance(agent, dict):
            return {}
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        return dict(metadata)

    def codex_command_from_start_command(self, start_command: str) -> str:
        clean = start_command.strip()
        if not clean:
            return ""
        try:
            argv = shlex.split(clean)
        except ValueError:
            return ""
        if len(argv) == 1 and " " in argv[0]:
            try:
                nested = shlex.split(argv[0])
            except ValueError:
                nested = []
            if nested:
                argv = nested
        if not argv:
            return ""
        executable = Path(argv[0]).name.lower()
        if executable != "codex" and "codex" not in executable:
            return ""
        stop_index = len(argv)
        for index, item in enumerate(argv[1:], start=1):
            if item in {"resume", "fork"}:
                stop_index = index
                break
        return shlex.join(argv[:stop_index])

    def runtime_tmux_command_kwargs(self, agent_id: str) -> dict[str, str]:
        """Return the exact server identity for a validated runtime mapping."""

        mapping = self.tmux_runtime_mapping_by_agent.get(agent_id)
        if not isinstance(mapping, dict) or str(mapping.get("state") or "") != "ready":
            return {}
        socket_path = str(mapping.get("socket_path") or "").strip()
        if not socket_path:
            return {}
        return {
            "tmux_bin": runtime_mapping_tmux_binary(mapping),
            "socket_path": socket_path,
        }

    def runtime_tmux_command_kwargs_for_pane(self, pane_id: str) -> dict[str, str]:
        """Resolve a pane only through a ready authoritative runtime mapping."""

        for agent_id, mapping in self.tmux_runtime_mapping_by_agent.items():
            if (
                isinstance(mapping, dict)
                and str(mapping.get("state") or "") == "ready"
                and str(mapping.get("pane_id") or "") == pane_id
            ):
                return self.runtime_tmux_command_kwargs(agent_id)
        return {}

    async def tmux_pane_start_command(
        self,
        pane_id: str,
        *,
        agent_id: str = "",
    ) -> str:
        try:
            return await asyncio.to_thread(
                tmux_support.pane_start_command,
                pane_id,
                **self.runtime_tmux_command_kwargs(agent_id),
            )
        except Exception:
            return ""

    async def codex_command_for_agent_restart(
        self,
        agent: dict[str, Any],
        pane: tmux_support.TmuxPane,
        *,
        allow_default: bool = True,
    ) -> str:
        metadata = self.agent_metadata(agent)
        configured = str(metadata.get("codex_command") or "").strip()
        if configured:
            normalized = self.codex_command_on_current_shell(configured)
            return normalized or configured
        start_command = await self.tmux_pane_start_command(
            pane.pane_id,
            agent_id=str(agent.get("agent_id") or ""),
        )
        from_start = self.codex_command_from_start_command(start_command)
        if from_start:
            normalized = self.codex_command_on_current_shell(from_start)
            return normalized or from_start
        if not allow_default:
            return ""
        return self.operator_codex_command()

    def codex_command_on_current_shell(self, codex_command: str) -> str:
        clean = codex_command.strip()
        if not clean:
            return self.operator_codex_command()
        try:
            argv = shlex.split(clean)
        except ValueError:
            return ""
        if not argv:
            return self.operator_codex_command()
        executable = Path(argv[0]).name.lower()
        if "codex" not in executable:
            return clean
        shell_parts = shlex.split(self.operator_codex_command())
        return shlex.join([*shell_parts, *argv[1:]])

    def resolved_codex_launch_command(self, codex_command: str) -> tuple[str, str]:
        """Return an absolute Codex command and the PATH needed by its launcher.

        Managed runtime migration can be driven by a headless helper whose PATH
        differs from the interactive TUI.  Tmux copies that helper environment
        into a newly created session, so a bare ``codex`` command may disappear
        even when another runtime session can resolve it.  Resolve the executable
        before creating a pane and explicitly carry its parent directory in PATH;
        this also keeps ``#!/usr/bin/env node`` npm launchers working.
        """

        clean = codex_command.strip()
        if not clean:
            raise RuntimeError("Codex launch command is empty")
        try:
            argv = shlex.split(clean)
        except ValueError as exc:
            raise RuntimeError(f"Codex launch command is invalid: {exc}") from exc
        if not argv:
            raise RuntimeError("Codex launch command is empty")

        executable = argv[0]
        expanded = Path(executable).expanduser()
        if expanded.is_absolute() or os.sep in executable:
            candidate = expanded.absolute()
            resolved = str(candidate) if candidate.is_file() else ""
        else:
            resolved = shutil.which(executable) or ""
        if not resolved or not os.access(resolved, os.X_OK):
            raise RuntimeError(
                f"Codex executable {executable!r} is unavailable in the launch environment; "
                "set AGENT_PBX_TUI_CODEX_BIN to an executable absolute path"
            )

        current_path = os.getenv("PATH", "")
        path_entries = [str(Path(resolved).parent), *current_path.split(os.pathsep)]
        launch_path = os.pathsep.join(
            dict.fromkeys(entry for entry in path_entries if entry)
        )
        argv[0] = resolved
        try:
            with Path(resolved).open("rb") as handle:
                shebang = handle.readline(256).decode(
                    "utf-8", errors="replace"
                ).strip()
        except OSError:
            shebang = ""
        if shebang.startswith("#!"):
            try:
                interpreter_parts = shlex.split(shebang[2:].strip())
            except ValueError:
                interpreter_parts = []
            if (
                len(interpreter_parts) == 2
                and Path(interpreter_parts[0]).name == "env"
                and interpreter_parts[1] == "node"
            ):
                node = next(
                    (
                        str(candidate)
                        for entry in launch_path.split(os.pathsep)
                        if entry
                        for candidate in (Path(entry) / "node",)
                        if candidate.is_file() and os.access(candidate, os.X_OK)
                    ),
                    "",
                )
                if not node or not os.access(node, os.X_OK):
                    raise RuntimeError(
                        "Codex uses an env-node launcher, but an executable Node.js "
                        "runtime is unavailable beside the configured Codex executable"
                    )
                argv = [node, resolved, *argv[1:]]
        return shlex.join(argv), launch_path

    @staticmethod
    def codex_resume_session_id_from_command(command: str) -> str | None:
        """Return the session passed to a real ``codex ... resume`` command.

        ``pane_start_command`` is intentionally used only as a best-effort
        ownership signal.  Restricting this parser to a Codex resume invocation
        prevents a bootstrap prompt containing the word ``resume`` from being
        mistaken for a session lease.
        """
        try:
            argv = shlex.split(command)
        except ValueError:
            return None
        if len(argv) < 3:
            return None
        try:
            resume_index = argv.index("resume")
        except ValueError:
            return None
        if resume_index <= 0 or "fork" in argv[:resume_index]:
            return None
        command_prefix = argv[:resume_index]
        if not any("codex" in token.lower() for token in command_prefix):
            return None
        session_id = argv[-1].strip()
        if not session_id or session_id.startswith("-"):
            return None
        return session_id

    @staticmethod
    def tmux_pane_current_process_may_be_codex(pane: tmux_support.TmuxPane) -> bool:
        """Avoid treating an exited Codex pane's historical start command as live."""
        command = Path(pane.current_command.strip()).name.lower()
        return command in {"bun", "codex", "deno", "node", "nodejs"} or "codex" in command

    def agent_ids_for_tmux_pane(self, pane_id: str) -> tuple[str, ...]:
        agent_ids = {
            agent_id
            for agent_id, target_pane_id in self.tmux_agent_targets.items()
            if target_pane_id == pane_id
        }
        for agent_id, agent in self.agents.items():
            if not isinstance(agent, dict):
                continue
            metadata = self.agent_metadata(agent)
            if str(metadata.get("tmux_pane_id") or "").strip() == pane_id:
                agent_ids.add(agent_id)
        return tuple(sorted(agent_ids))

    async def codex_resume_session_owners(
        self,
        session_id: str,
        *,
        excluding_pane_id: str | None = None,
    ) -> list[CodexResumeSessionOwner]:
        """Find live tmux panes that are actively resuming ``session_id``.

        The foreground-process check matters because tmux keeps a pane's start
        command after Codex has exited back to a shell.  A shell with an old
        ``codex resume`` start command must not block a safe restart.
        """
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception as exc:
            raise RuntimeError(f"unable to inspect tmux panes: {exc}") from exc
        owners: list[CodexResumeSessionOwner] = []
        for pane in panes:
            if pane.pane_id == excluding_pane_id:
                continue
            if not self.tmux_pane_current_process_may_be_codex(pane):
                continue
            try:
                if not await asyncio.to_thread(tmux_support.pane_is_live, pane.pane_id):
                    continue
                start_command = await asyncio.to_thread(
                    tmux_support.pane_start_command,
                    pane.pane_id,
                )
            except Exception as exc:
                raise RuntimeError(
                    f"unable to inspect live pane {pane.pane_id}: {exc}"
                ) from exc
            if self.codex_resume_session_id_from_command(start_command) != session_id:
                continue
            owners.append(
                CodexResumeSessionOwner(
                    pane_id=pane.pane_id,
                    target_label=pane.target_label,
                    title=pane.title or pane.window_name,
                    agent_ids=self.agent_ids_for_tmux_pane(pane.pane_id),
                )
            )
        return owners

    async def ensure_codex_resume_session_available(
        self,
        agent_id: str,
        session_id: str,
        *,
        replacing_pane_id: str | None = None,
    ) -> bool:
        """Refuse an in-place replacement that would enter Codex's lease dialog."""
        try:
            owners = await self.codex_resume_session_owners(
                session_id,
                excluding_pane_id=replacing_pane_id,
            )
        except Exception as exc:
            return self.record_runtime_migration_failure(
                agent_id,
                f"Unable to verify whether {agent_id}'s Codex session is already open; "
                f"no pane was replaced. {exc}",
                severity="warning",
            )
        if not owners:
            return True
        owner_labels = ", ".join(owner.display_label for owner in owners)
        return self.record_runtime_migration_failure(
            agent_id,
            f"Refused to resume {agent_id}: its Codex conversation is active in "
            f"{owner_labels}. Close or wait for that owner, then retry; to branch "
            "intentionally, use Codex's explicit fork action. Agent PBX will not "
            "fork automatically.",
            severity="warning",
        )

    def record_runtime_migration_failure(
        self,
        agent_id: str,
        message: str,
        *,
        severity: str = "error",
    ) -> bool:
        """Persist a runtime transition failure before displaying it in the TUI."""

        self.runtime_migration_error_by_agent[agent_id] = message
        self.notify(message, severity=severity)
        return False

    def codex_session_lease_conflict_detected(self, text: str) -> bool:
        normalized = text.lower()
        return any(marker in normalized for marker in CODEX_SESSION_LEASE_CONFLICT_MARKERS)

    @staticmethod
    def bounded_runtime_failure_capture(text: str) -> str:
        """Return a compact local terminal tail suitable for a migration error."""

        lines = [line.strip() for line in str(text or "").splitlines() if line.strip()]
        if not lines:
            return ""
        captured = " | ".join(lines[-8:])
        limit = CODEX_MANAGED_RESUME_FAILURE_CAPTURE_CHARS
        if len(captured) <= limit:
            return captured
        return "…" + captured[-(limit - 1) :]

    async def retained_tmux_pane_failure(
        self,
        pane_id: str,
        *,
        tmux_bin: str,
        socket_path: str | None,
    ) -> tuple[str, bool]:
        """Describe a retained process exit and classify Codex lease failures."""

        exit_status = await asyncio.to_thread(
            tmux_support.pane_dead_status,
            pane_id,
            tmux_bin=tmux_bin,
            socket_path=socket_path,
        )
        try:
            captured = await asyncio.to_thread(
                tmux_support.capture_pane,
                pane_id,
                lines=CODEX_MANAGED_RESUME_FAILURE_CAPTURE_LINES,
                tmux_bin=tmux_bin,
                socket_path=socket_path,
            )
        except Exception as exc:
            captured = ""
            capture_error = f"; terminal capture failed: {exc}"
        else:
            capture_error = ""
        status_detail = (
            f" with status {exit_status}" if exit_status is not None else ""
        )
        terminal_tail = self.bounded_runtime_failure_capture(captured)
        output_detail = f"; terminal tail: {terminal_tail}" if terminal_tail else ""
        detail = (
            f"{pane_id} exited{status_detail} before Codex resume stabilized"
            f"{output_detail}{capture_error}"
        )
        return detail, self.codex_session_lease_conflict_detected(captured)

    async def tmux_pane_has_codex_session_lease_conflict(
        self,
        pane_id: str,
        *,
        tmux_bin: str = "tmux",
        socket_path: str | None = None,
    ) -> bool:
        try:
            captured = await asyncio.to_thread(
                tmux_support.capture_pane,
                pane_id,
                lines=0,
                tmux_bin=tmux_bin,
                socket_path=socket_path,
            )
        except Exception:
            return False
        return self.codex_session_lease_conflict_detected(captured)

    def operator_session_can_resume(self, agent_id: str, session_id: str) -> bool:
        """A fork must never resume its caller/root source conversation."""
        metadata = self.operator_metadata_for(agent_id)
        source_session_id = str(metadata.get("source_codex_session_id") or "").strip()
        agent = self.agents.get(agent_id)
        is_fork = (
            isinstance(agent, dict)
            and self.operator_role(agent) == OPERATOR_ROLE_FORK
        )
        return not (
            is_fork
            and bool(source_session_id)
            and session_id == source_session_id
        )

    def operator_restart_target(
        self,
        agent_id: str,
        candidates: list[OperatorSessionCandidate],
    ) -> OperatorSessionCandidate | None:
        candidates = [
            candidate
            for candidate in candidates
            if self.operator_session_can_resume(agent_id, candidate.session_id)
        ]
        if not candidates:
            return None
        current_session_ids = self.current_operator_session_ids(agent_id)
        for candidate in candidates:
            if candidate.session_id in current_session_ids:
                return candidate
        return candidates[0] if candidates else None

    async def quit_or_kill_tmux_pane(self, pane_id: str, *, label: str) -> bool:
        try:
            exited = await asyncio.to_thread(
                tmux_support.quit_pane,
                pane_id,
                timeout_seconds=CODEX_RESTART_WAIT_SECONDS,
            )
        except Exception as exc:
            self.notify(f"Unable to send /q to {label}: {exc}", severity="warning")
            exited = False
        if exited:
            return True
        try:
            await asyncio.to_thread(tmux_support.kill_pane, pane_id)
        except Exception as exc:
            self.notify(f"Unable to kill {label} after /q: {exc}", severity="error")
            return False
        return True

    async def launch_restart_pane(
        self,
        *,
        session_name: str,
        window_name: str,
        command: str,
        label: str,
        cwd: str | None = None,
        env: Mapping[str, str] | None = None,
    ) -> str:
        failures: list[str] = []
        attempts = max(1, CODEX_RESTART_LAUNCH_ATTEMPTS)
        for attempt in range(1, attempts + 1):
            try:
                pane_id = await asyncio.to_thread(
                    tmux_support.launch_pane,
                    session_name=session_name,
                    window_name=window_name,
                    command=command,
                    cwd=cwd,
                    env=env,
                    width=self.detached_tmux_width,
                    height=self.detached_tmux_height,
                )
            except Exception as exc:
                failures.append(str(exc))
            else:
                if CODEX_RESTART_STABILIZE_SECONDS > 0:
                    await asyncio.sleep(CODEX_RESTART_STABILIZE_SECONDS)
                try:
                    pane_alive = await asyncio.to_thread(tmux_support.pane_exists, pane_id)
                except Exception as exc:
                    failures.append(f"{pane_id} liveness check failed: {exc}")
                else:
                    if pane_alive:
                        return pane_id
                    failures.append(f"{pane_id} exited before Codex restart stabilized")
            if attempt < attempts and CODEX_RESTART_RETRY_SECONDS > 0:
                await asyncio.sleep(CODEX_RESTART_RETRY_SECONDS)
        detail = "; ".join(failures[-3:]) or "replacement pane did not stay running"
        raise RuntimeError(f"{label} relaunch failed after {attempts} attempt(s): {detail}")

    async def respawn_restart_pane(
        self,
        *,
        pane_id: str,
        command: str,
        label: str,
        cwd: str | None = None,
        env: Mapping[str, str] | None = None,
        rollback_command: str = "",
        rollback_cwd: str | None = None,
        rollback_env: Mapping[str, str] | None = None,
        tmux_bin: str = "tmux",
        socket_path: str | None = None,
    ) -> str:
        """Restart Codex in place and restore the prior launch if it cannot live."""
        failures: list[str] = []
        lease_conflict = False
        attempts = max(1, CODEX_RESTART_LAUNCH_ATTEMPTS)
        runtime_kwargs: dict[str, str | None] = {}
        if socket_path is not None or tmux_bin != "tmux":
            runtime_kwargs = {"tmux_bin": tmux_bin, "socket_path": socket_path}
        pane_guarded = await asyncio.to_thread(
            tmux_support.pane_exists,
            pane_id,
            **runtime_kwargs,
        )
        previous_remain_on_exit = False
        restored = False
        replacement_ready = False
        if pane_guarded:
            try:
                previous_remain_on_exit = await asyncio.to_thread(
                    tmux_support.pane_remain_on_exit,
                    pane_id,
                    **runtime_kwargs,
                )
                await asyncio.to_thread(
                    tmux_support.set_pane_remain_on_exit,
                    pane_id,
                    True,
                    **runtime_kwargs,
                )
            except Exception as exc:
                raise RuntimeError(
                    f"unable to preserve {pane_id} for transactional restart; "
                    f"no process was replaced: {exc}"
                ) from exc

        try:
            for attempt in range(1, attempts + 1):
                try:
                    await asyncio.to_thread(
                        tmux_support.respawn_pane,
                        pane_id,
                        command=command,
                        cwd=cwd,
                        env=env,
                        **runtime_kwargs,
                    )
                except Exception as exc:
                    failures.append(str(exc))
                else:
                    if CODEX_RESTART_STABILIZE_SECONDS > 0:
                        await asyncio.sleep(CODEX_RESTART_STABILIZE_SECONDS)
                    try:
                        pane_alive = await asyncio.to_thread(
                            tmux_support.pane_is_live,
                            pane_id,
                            **runtime_kwargs,
                        )
                    except Exception as exc:
                        failures.append(f"{pane_id} liveness check failed: {exc}")
                    else:
                        if pane_alive:
                            if await self.tmux_pane_has_codex_session_lease_conflict(
                                pane_id,
                                **runtime_kwargs,
                            ):
                                lease_conflict = True
                                failures.append(
                                    f"{pane_id} opened Codex's conversation lease dialog"
                                )
                                break
                            replacement_ready = True
                            return pane_id
                        exit_status = await asyncio.to_thread(
                            tmux_support.pane_dead_status,
                            pane_id,
                            **runtime_kwargs,
                        )
                        status_detail = (
                            f" with status {exit_status}"
                            if exit_status is not None
                            else ""
                        )
                        failures.append(
                            f"{pane_id} exited{status_detail} before Codex restart stabilized"
                        )
                if attempt < attempts and CODEX_RESTART_RETRY_SECONDS > 0:
                    await asyncio.sleep(CODEX_RESTART_RETRY_SECONDS)

            rollback_detail = ""
            if rollback_command:
                try:
                    await asyncio.to_thread(
                        tmux_support.respawn_pane,
                        pane_id,
                        command=rollback_command,
                        cwd=rollback_cwd,
                        env=rollback_env,
                        **runtime_kwargs,
                    )
                    if CODEX_RESTART_STABILIZE_SECONDS > 0:
                        await asyncio.sleep(CODEX_RESTART_STABILIZE_SECONDS)
                    restored = await asyncio.to_thread(
                        tmux_support.pane_is_live,
                        pane_id,
                        **runtime_kwargs,
                    )
                except Exception as exc:
                    rollback_detail = f"; rollback failed: {exc}"
                else:
                    rollback_detail = (
                        "; restored the prior command in the original pane"
                        if restored
                        else "; rollback command did not stay running"
                    )
            detail = "; ".join(failures[-3:]) or "replacement pane did not stay running"
            error_type = CodexSessionLeaseConflictError if lease_conflict else RuntimeError
            raise error_type(
                f"{label} in-place relaunch failed after {attempts} attempt(s): "
                f"{detail}{rollback_detail}"
            )
        finally:
            if pane_guarded and await asyncio.to_thread(
                tmux_support.pane_exists,
                pane_id,
                **runtime_kwargs,
            ):
                pane_live = await asyncio.to_thread(
                    tmux_support.pane_is_live,
                    pane_id,
                    **runtime_kwargs,
                )
                if replacement_ready or restored or pane_live:
                    try:
                        await asyncio.to_thread(
                            tmux_support.set_pane_remain_on_exit,
                            pane_id,
                            previous_remain_on_exit,
                            **runtime_kwargs,
                        )
                    except Exception as exc:
                        self.notify(
                            f"Restart completed, but {pane_id}'s remain-on-exit "
                            f"setting could not be restored: {exc}",
                            severity="warning",
                        )
                # If replacement and rollback both failed, leave the dead pane
                # retained.  That preserves the pane id, exit status, and screen
                # for diagnosis or a subsequent manual recovery.

    async def restart_rollback_command(
        self,
        pane_id: str,
        *,
        tmux_bin: str = "tmux",
        socket_path: str | None = None,
    ) -> str:
        """Capture a transient rollback command without persisting launch details."""
        try:
            runtime_kwargs: dict[str, str | None] = {}
            if socket_path is not None or tmux_bin != "tmux":
                runtime_kwargs = {"tmux_bin": tmux_bin, "socket_path": socket_path}
            return await asyncio.to_thread(
                tmux_support.pane_start_command,
                pane_id,
                **runtime_kwargs,
            )
        except Exception as exc:
            raise RuntimeError(f"unable to snapshot existing pane command: {exc}") from exc

    def restart_model_preset(
        self,
        metadata: Mapping[str, Any],
        requested: CodexModelPreset | None,
        *,
        operator: bool = False,
    ) -> CodexModelPreset | None:
        """Keep an explicit model, otherwise apply the role-owned PBX default."""
        return (
            requested
            or codex_model_preset_from_metadata(metadata)
            or CODEX_MODEL_PRESET_BY_KEY[
                DEFAULT_OPERATOR_MODEL_PRESET_KEY
                if operator
                else DEFAULT_CALLER_MODEL_PRESET_KEY
            ]
        )

    async def register_tmux_relaunched_caller(
        self,
        agent_id: str,
        *,
        pane_id: str,
        cwd: str,
        codex_command: str,
        model_preset: CodexModelPreset | None = None,
    ) -> dict[str, Any] | None:
        agent = self.agents.get(agent_id)
        if not isinstance(agent, dict):
            return None
        metadata = self.agent_metadata(agent)
        updated_metadata = {
            **metadata,
            "cwd": cwd,
            "tmux_pane_id": pane_id,
            "codex_command": codex_command,
            "last_tmux_restart_at": time.time(),
            "last_tmux_restart_mode": "in_place",
        }
        if model_preset is not None:
            updated_metadata.update(model_preset.metadata())
        response = await self.api_client().post(
            "/v1/agents/register",
            json={
                "agent_id": agent_id,
                "project": str(agent.get("project") or "agent-pbx"),
                "name": str(agent.get("name") or agent_id),
                "agent_type": CALLER_AGENT_TYPE,
                "pbx_active": bool(agent.get("pbx_active", True)),
                "metadata": updated_metadata,
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        updated = response.json()
        if isinstance(updated, dict):
            self.agents[agent_id] = updated
            return updated
        return None

    async def refresh_tmux_runtime_mapping_after_restart(
        self,
        agent_id: str,
        pane_id: str,
    ) -> bool:
        """Refresh process evidence after an in-place pane respawn.

        Tmux preserves the pane id across ``respawn-pane`` while replacing its
        root process.  Leaving the old PID/start ticks in the durable mapping
        makes the next live assessment classify a healthy pane as reused.
        """

        mapping = self.tmux_runtime_mapping_by_agent.get(agent_id)
        if not isinstance(mapping, dict):
            return True
        socket_path = str(mapping.get("socket_path") or "").strip()
        if not socket_path:
            return True
        runtime_kwargs = {
            "tmux_bin": runtime_mapping_tmux_binary(mapping),
            "socket_path": socket_path,
        }
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes, **runtime_kwargs)
            pane = next((item for item in panes if item.pane_id == pane_id), None)
            if pane is None:
                raise RuntimeError(f"respawned pane {pane_id} is unavailable")
            pane_pid = await asyncio.to_thread(
                tmux_support.pane_root_pid,
                pane_id,
                **runtime_kwargs,
            )
            if pane_pid is None:
                raise RuntimeError(f"respawned pane {pane_id} has no root process")
            agent = self.agents.get(agent_id)
            metadata = self.agent_metadata(agent)
            session_id = str(
                metadata.get("fork_codex_session_id")
                or metadata.get("last_resume_codex_session_id")
                or metadata.get("codex_session_id")
                or metadata.get("codex_thread_id")
                or mapping.get("codex_session_id")
                or ""
            ).strip()
            mapping_metadata = (
                dict(mapping.get("metadata"))
                if isinstance(mapping.get("metadata"), dict)
                else {}
            )
            response = await self.api_client().post(
                f"/v2/tmux/runtimes/{quote(agent_id, safe='')}",
                json={
                    "server_mode": normalize_runtime_server_mode(
                        mapping.get("server_mode")
                    ).value,
                    "socket_path": socket_path,
                    "session_name": pane.session_name,
                    "window_id": pane.window_id or pane.window_index,
                    "window_name": pane.window_name,
                    "pane_id": pane.pane_id,
                    "pane_pid": pane_pid,
                    "process_start_ticks": await asyncio.to_thread(
                        runtime_process_start_ticks,
                        pane_pid,
                    ),
                    "codex_session_id": session_id or None,
                    "cwd": pane.cwd,
                    "origin_client_tty": mapping.get("origin_client_tty"),
                    "origin_session_name": mapping.get("origin_session_name"),
                    "metadata": {
                        **mapping_metadata,
                        "mapping_source": "in_place_restart",
                        "tmux_bin": runtime_kwargs["tmux_bin"],
                    },
                },
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            refreshed = response.json()
            if not isinstance(refreshed, dict):
                raise RuntimeError("runtime mapping refresh returned invalid data")
        except Exception as exc:
            self.tmux_runtime_mapping_error_by_agent[agent_id] = str(exc)
            self.notify(
                f"Restarted {agent_id}, but runtime evidence refresh failed: {exc}",
                severity="error",
            )
            return False
        self.tmux_runtime_mapping_by_agent[agent_id] = refreshed
        self.tmux_runtime_mapping_validated_at_by_agent[agent_id] = time.monotonic()
        self.tmux_runtime_mapping_error_by_agent.pop(agent_id, None)
        return True

    async def relaunch_operator_root_codex(
        self,
        agent_id: str,
        pane: tmux_support.TmuxPane,
        *,
        model_preset: CodexModelPreset | None = None,
        resume_candidate: OperatorSessionCandidate | None = None,
    ) -> bool:
        pane_id = pane.pane_id
        runtime_kwargs = self.runtime_tmux_command_kwargs(agent_id)
        agent = self.agents.get(agent_id)
        metadata = self.agent_metadata(agent)
        effective_model_preset = self.restart_model_preset(
            metadata, model_preset, operator=True
        )
        if metadata.get("launched_by") != "agent-pbx-tui":
            self.notify(
                f"{agent_id} has a non-TUI-owned tmux pane; detach it before restart.",
                severity="warning",
            )
            return False
        self.tmux_agent_targets[agent_id] = pane_id
        candidates = await asyncio.to_thread(self.operator_session_candidates, agent_id)
        target = resume_candidate or self.operator_restart_target(agent_id, candidates)
        if target is None:
            self.notify(f"No resumable Codex session found for {agent_id}.", severity="warning")
            await self.show_selected_operator_history()
            return False
        if not await self.ensure_codex_resume_session_available(
            agent_id,
            target.session_id,
            replacing_pane_id=pane_id,
        ):
            return False
        if not await self.ensure_operator_auth_ready():
            return False
        cwd = str(metadata.get("cwd") or self.operator_cwd()).strip() or os.getcwd()
        codex_command = self.operator_codex_command()
        mcp_url = agent_pbx_mcp_url(self.server)
        session_name = self.operator_tmux_session_name()
        history = self.operator_session_history_metadata(
            agent_id,
            include=[*candidates[:3], target],
        )
        try:
            await self.configure_operator_codex_mcp(
                codex_command=codex_command,
                mcp_url=mcp_url,
            )
            rollback_command = await self.restart_rollback_command(
                pane_id,
                **runtime_kwargs,
            )
        except Exception as exc:
            self.notify(f"Unable to prepare {agent_id} for restart: {exc}", severity="error")
            return False
        launch_config_overrides = operator_agent_config_overrides(
            mcp_url=mcp_url,
            codex_home=self.codex_home_dir(),
            work_root=cwd,
            include_campaign_lifecycle=True,
            terminal_mode=self.codex_terminal_mode,
        )
        launch_config_overrides.extend(
            codex_model_preset_config_overrides(effective_model_preset)
        )
        env = self.operator_launch_env(
            agent_id=agent_id,
            cwd=cwd,
            mcp_url=mcp_url,
            model_preset=effective_model_preset,
        )
        env["AGENT_PBX_RESUME_CODEX_SESSION_ID"] = target.session_id
        rollback_env = self.operator_launch_env(
            agent_id=agent_id,
            cwd=cwd,
            mcp_url=mcp_url,
            model_preset=codex_model_preset_from_metadata(metadata),
        )
        rollback_env["AGENT_PBX_RESUME_CODEX_SESSION_ID"] = target.session_id
        try:
            new_pane_id = await self.respawn_restart_pane(
                pane_id=pane_id,
                command=self.operator_resume_command(
                    codex_command,
                    target.session_id,
                    cd=cwd,
                    config_overrides=launch_config_overrides,
                ),
                label=agent_id,
                cwd=cwd,
                env=env,
                rollback_command=rollback_command,
                rollback_cwd=pane.cwd or cwd,
                rollback_env=rollback_env,
                **runtime_kwargs,
            )
            await self.register_operator_root(
                agent_id,
                cwd=cwd,
                codex_command=codex_command,
                mcp_url=mcp_url,
                session_name=session_name,
                tmux_pane_id=new_pane_id,
                resumed_codex_session_id=target.session_id,
                operator_session_history=history,
                model_preset=effective_model_preset,
                restart_mode="in_place",
            )
        except Exception as exc:
            self.notify(f"Unable to relaunch {agent_id}: {exc}", severity="error")
            return False
        self.tmux_agent_targets[agent_id] = new_pane_id
        self.tmux_manual_override_agent_ids.add(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.tmux_direct_agent_modes[agent_id] = True
        await asyncio.sleep(1.0)
        await self.send_text_to_tmux_pane(
            new_pane_id,
            self.operator_bootstrap_prompt(agent_id, cwd),
        )
        self.save_settings()
        self.notify(
            f"Restarted {agent_id} in place on Codex session {target.session_id}."
        )
        return True

    async def relaunch_operator_fork_codex(
        self,
        agent_id: str,
        pane: tmux_support.TmuxPane,
        *,
        model_preset: CodexModelPreset | None = None,
    ) -> bool:
        agent = self.agents.get(agent_id)
        runtime_kwargs = self.runtime_tmux_command_kwargs(agent_id)
        metadata = self.agent_metadata(agent)
        effective_model_preset = self.restart_model_preset(
            metadata, model_preset, operator=True
        )
        rollback_model_preset = codex_model_preset_from_metadata(metadata)
        if metadata.get("launched_by") != "agent-pbx-tui":
            self.notify(
                f"{agent_id} has a non-TUI-owned tmux pane; detach it before restart.",
                severity="warning",
            )
            return False
        logical_operator_id = str(metadata.get("logical_operator_id") or "").strip()
        source_caller_agent_id = str(metadata.get("source_caller_agent_id") or "").strip()
        source_session_id = str(metadata.get("source_codex_session_id") or "").strip()
        if not logical_operator_id or not source_caller_agent_id or not source_session_id:
            self.notify(f"{agent_id} is missing operator fork metadata.", severity="error")
            return False
        if not await self.ensure_operator_auth_ready():
            return False
        codex_command = self.operator_codex_command()
        mcp_url = agent_pbx_mcp_url(self.server)
        fork_track_id = self.normalize_operator_fork_track_id(
            str(metadata.get("fork_track_id") or DEFAULT_OPERATOR_FORK_TRACK_ID)
        )
        fork_purpose = self.normalize_operator_fork_label(
            str(metadata.get("fork_purpose") or ""),
            default=(
                DEFAULT_OPERATOR_FORK_PURPOSE
                if fork_track_id == DEFAULT_OPERATOR_FORK_TRACK_ID
                else REVIEW_OPERATOR_FORK_PURPOSE
            ),
        )
        access_mode = self.normalize_operator_fork_label(
            str(metadata.get("access_mode") or ""),
            default=(
                DEFAULT_OPERATOR_FORK_ACCESS_MODE
                if fork_purpose == DEFAULT_OPERATOR_FORK_PURPOSE
                else REVIEW_OPERATOR_FORK_ACCESS_MODE
            ),
        )
        source_cwd = str(metadata.get("source_cwd") or "").strip()
        work_root = str(metadata.get("work_root") or metadata.get("cwd") or pane.cwd).strip()
        unsafe_persisted_fork_session = (
            str(metadata.get("fork_codex_session_id") or "").strip()
            == source_session_id
        )
        source_session_resume_rejected = False
        candidates = await asyncio.to_thread(self.operator_session_candidates, agent_id)
        target = self.operator_restart_target(agent_id, candidates)
        if target is not None and target.session_id == source_session_id:
            # Defensive backstop for metadata produced before the candidate filter.
            target = None
            source_session_resume_rejected = True
        target_invalid_encrypted_content = (
            target is not None
            and self.operator_session_has_invalid_encrypted_content(target)
        )
        if (
            not target_invalid_encrypted_content
            and fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            and await self.tmux_pane_has_invalid_encrypted_content(pane.pane_id)
        ):
            target_invalid_encrypted_content = True
        if target_invalid_encrypted_content:
            target = None
        if target is None and unsafe_persisted_fork_session:
            source_session_resume_rejected = True
        review_launch_mode = self.normalize_review_operator_fork_launch_mode(
            str(metadata.get("review_launch_mode") or "")
        )
        if (
            fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            and target_invalid_encrypted_content
        ):
            review_launch_mode = REVIEW_OPERATOR_FORK_LAUNCH_MODE_FRESH_CONTEXT
        raw_review_servers = metadata.get("review_mcp_approval_servers", [])
        review_servers = (
            tuple(
                str(item)
                for item in raw_review_servers
                if str(item).strip()
            )
            if isinstance(raw_review_servers, (list, tuple))
            else ()
        )
        if not review_servers and fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE:
            review_servers = review_operator_mcp_approval_server_names()
        launch_config_overrides = (
            review_operator_config_overrides(
                review_servers,
                mcp_url=mcp_url,
                codex_home=self.codex_home_dir(),
                work_root=work_root,
                terminal_mode=self.codex_terminal_mode,
            )
            if fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            else operator_agent_config_overrides(
                mcp_url=mcp_url,
                codex_home=self.codex_home_dir(),
                work_root=work_root,
                terminal_mode=self.codex_terminal_mode,
            )
        )
        launch_config_overrides.extend(
            codex_model_preset_config_overrides(effective_model_preset)
        )
        sandbox = (
            "workspace-write"
            if fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            else None
        )

        def build_bootstrap(mode: str) -> str:
            return self.operator_bootstrap_prompt(
                agent_id,
                work_root,
                logical_operator_id=logical_operator_id,
                source_caller_agent_id=source_caller_agent_id,
                source_codex_session_id=source_session_id,
                fork_track_id=fork_track_id,
                fork_purpose=fork_purpose,
                access_mode=access_mode,
                source_cwd=source_cwd or work_root,
                work_root=work_root,
                review_launch_mode=mode,
            )

        def build_command(
            mode: str,
            resume_target: OperatorSessionCandidate | None,
        ) -> str:
            bootstrap_prompt = build_bootstrap(mode)
            if resume_target is not None:
                return self.operator_resume_command(
                    codex_command,
                    resume_target.session_id,
                    cd=work_root if work_root and work_root != source_cwd else None,
                    sandbox=sandbox,
                    config_overrides=launch_config_overrides,
                )
            if (
                fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE
                and mode == REVIEW_OPERATOR_FORK_LAUNCH_MODE_FRESH_CONTEXT
            ):
                return self.codex_start_command(
                    codex_command,
                    bootstrap_prompt,
                    cd=work_root if work_root and work_root != source_cwd else None,
                    sandbox=sandbox,
                    config_overrides=launch_config_overrides,
                )
            return self.operator_fork_command(
                codex_command,
                source_session_id,
                bootstrap_prompt,
                cd=work_root if work_root and work_root != source_cwd else None,
                sandbox=sandbox,
                config_overrides=launch_config_overrides,
            )

        def build_env(
            mode: str,
            resume_target: OperatorSessionCandidate | None,
            *,
            preset: CodexModelPreset | None = effective_model_preset,
        ) -> dict[str, str]:
            launch_env = self.operator_launch_env(
                agent_id=agent_id,
                cwd=work_root,
                mcp_url=mcp_url,
                model_preset=preset,
                operator_role=OPERATOR_ROLE_FORK,
                logical_operator_id=logical_operator_id,
                source_caller_agent_id=source_caller_agent_id,
                source_codex_session_id=source_session_id,
                fork_track_id=fork_track_id,
                fork_purpose=fork_purpose,
                access_mode=access_mode,
                source_cwd=source_cwd or work_root,
                work_root=work_root,
                review_launch_mode=mode,
            )
            if resume_target is not None:
                launch_env["AGENT_PBX_RESUME_CODEX_SESSION_ID"] = (
                    resume_target.session_id
                )
            return launch_env

        command = build_command(review_launch_mode, target)
        if target is not None and not await self.ensure_codex_resume_session_available(
            agent_id,
            target.session_id,
            replacing_pane_id=pane.pane_id,
        ):
            return False
        try:
            await self.configure_operator_codex_mcp(
                codex_command=codex_command,
                mcp_url=mcp_url,
            )
            rollback_command = await self.restart_rollback_command(
                pane.pane_id,
                **runtime_kwargs,
            )
        except Exception as exc:
            self.notify(f"Unable to configure Codex MCP: {exc}", severity="error")
            return False
        try:
            new_pane_id = await self.respawn_restart_pane(
                pane_id=pane.pane_id,
                command=command,
                label=agent_id,
                cwd=work_root,
                env=build_env(review_launch_mode, target),
                rollback_command=rollback_command,
                rollback_cwd=pane.cwd or work_root,
                rollback_env=build_env(
                    review_launch_mode,
                    target,
                    preset=rollback_model_preset,
                ),
                **runtime_kwargs,
            )
            if (
                fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE
                and review_launch_mode
                != REVIEW_OPERATOR_FORK_LAUNCH_MODE_FRESH_CONTEXT
                and await self.review_fork_pane_has_invalid_encrypted_content(new_pane_id)
            ):
                self.notify(
                    "Codex continuation failed encrypted-content verification; "
                    "restarting review fork with fresh context.",
                    severity="warning",
                )
                target = None
                target_invalid_encrypted_content = True
                review_launch_mode = REVIEW_OPERATOR_FORK_LAUNCH_MODE_FRESH_CONTEXT
                new_pane_id = await self.respawn_restart_pane(
                    pane_id=pane.pane_id,
                    command=build_command(review_launch_mode, target),
                    label=agent_id,
                    cwd=work_root,
                    env=build_env(review_launch_mode, target),
                    rollback_command=rollback_command,
                    rollback_cwd=pane.cwd or work_root,
                    rollback_env=build_env(
                        review_launch_mode,
                        target,
                        preset=rollback_model_preset,
                    ),
                    **runtime_kwargs,
                )
        except Exception as exc:
            self.notify(f"Unable to relaunch {agent_id}: {exc}", severity="error")
            return False
        fork_metadata = {
            **metadata,
            "tmux_pane_id": new_pane_id,
            "last_tmux_restart_at": time.time(),
            "last_tmux_restart_mode": "in_place",
        }
        if effective_model_preset is not None:
            fork_metadata.update(effective_model_preset.metadata())
        if fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE:
            fork_metadata["review_launch_mode"] = review_launch_mode
        if target_invalid_encrypted_content:
            fork_metadata["source_continuation_disabled_reason"] = (
                "invalid_encrypted_content"
            )
            fork_metadata.pop("fork_codex_session_id", None)
        if source_session_resume_rejected:
            for key in FORK_RESUME_IDENTITY_METADATA_KEYS:
                fork_metadata.pop(key, None)
            fork_metadata["fork_resume_disabled_reason"] = (
                "source_session_collision"
            )
        if target is not None:
            fork_metadata["fork_codex_session_id"] = target.session_id
        try:
            fork = await self.record_operator_fork(
                logical_operator_id=logical_operator_id,
                source_caller_agent_id=source_caller_agent_id,
                fork_agent_id=agent_id,
                tmux_pane_id=new_pane_id,
                metadata=fork_metadata,
                fork_track_id=fork_track_id,
                fork_purpose=fork_purpose,
                access_mode=access_mode,
                source_cwd=source_cwd or work_root,
                work_root=work_root,
                fork_codex_session_id=target.session_id if target is not None else None,
                clear_fork_codex_session_id=source_session_resume_rejected,
            )
            if isinstance(fork, dict):
                self.agents[agent_id] = self.operator_fork_record_agent(fork)
        except Exception as exc:
            self.notify(
                f"Relaunched {agent_id}, but PBX fork registration failed: {exc}",
                severity="warning",
            )
        self.tmux_agent_targets[agent_id] = new_pane_id
        self.tmux_manual_override_agent_ids.add(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.tmux_direct_agent_modes[agent_id] = True
        if target is not None:
            await asyncio.sleep(1.0)
            await self.send_text_to_tmux_pane(
                new_pane_id,
                build_bootstrap(review_launch_mode),
            )
        self.save_settings()
        suffix = f" on Codex session {target.session_id}" if target else ""
        self.notify(f"Restarted {agent_id} in place{suffix}.")
        return True

    async def relaunch_caller_codex(
        self,
        agent_id: str,
        pane: tmux_support.TmuxPane,
        *,
        model_preset: CodexModelPreset | None = None,
    ) -> bool:
        agent = self.agents.get(agent_id)
        runtime_kwargs = self.runtime_tmux_command_kwargs(agent_id)
        if not isinstance(agent, dict):
            self.notify(f"{agent_id} is not loaded.", severity="warning")
            return False
        metadata = self.agent_metadata(agent)
        effective_model_preset = self.restart_model_preset(metadata, model_preset)
        session_id = str(
            metadata.get("codex_session_id") or metadata.get("codex_thread_id") or ""
        ).strip()
        if not session_id:
            self.notify(
                f"{agent_id} is missing metadata.codex_session_id; send /q manually.",
                severity="warning",
            )
            return False
        cwd = str(metadata.get("cwd") or pane.cwd or os.getcwd()).strip()
        codex_command = await self.codex_command_for_agent_restart(
            agent,
            pane,
            allow_default=True,
        )
        if not codex_command:
            self.notify(
                f"{agent_id} has no recoverable Codex launch command; send /q manually.",
                severity="warning",
            )
            return False
        if not await self.ensure_codex_resume_session_available(
            agent_id,
            session_id,
            replacing_pane_id=pane.pane_id,
        ):
            return False
        command = self.operator_resume_command(
            codex_command,
            session_id,
            cd=cwd,
            config_overrides=codex_model_preset_config_overrides(effective_model_preset),
        )
        try:
            rollback_command = await self.restart_rollback_command(
                pane.pane_id,
                **runtime_kwargs,
            )
            new_pane_id = await self.respawn_restart_pane(
                pane_id=pane.pane_id,
                command=command,
                label=agent_id,
                cwd=cwd,
                rollback_command=rollback_command,
                rollback_cwd=pane.cwd or cwd,
                **runtime_kwargs,
            )
        except Exception as exc:
            self.notify(f"Unable to relaunch {agent_id}: {exc}", severity="error")
            return False
        self.tmux_agent_targets[agent_id] = new_pane_id
        self.tmux_manual_override_agent_ids.add(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.tmux_direct_agent_modes[agent_id] = True
        try:
            await self.register_tmux_relaunched_caller(
                agent_id,
                pane_id=new_pane_id,
                cwd=cwd,
                codex_command=codex_command,
                model_preset=effective_model_preset,
            )
        except Exception as exc:
            self.notify(
                f"Relaunched {agent_id}, but PBX registration failed: {exc}",
                severity="warning",
            )
        self.save_settings()
        self.notify(
            f"Restarted {agent_id} in place on Codex session {session_id}."
        )
        return True

    async def restart_tmux_codex_session(
        self,
        agent_id: str | None = None,
        *,
        model_preset: CodexModelPreset | None = None,
        model_elevation_lease_id: str | None = None,
    ) -> bool:
        agent_id = agent_id or self.query_one("#agent-id", Input).value.strip()
        if not agent_id:
            self.notify("Select an agent before restarting Codex.", severity="warning")
            return False
        if model_preset is not None and model_preset.elevated and not model_elevation_lease_id:
            self.notify(
                "Sol max requires explicit user approval and a justification.",
                severity="warning",
            )
            return False
        if model_preset is not None and not await self.ensure_codex_model_preset_valid(
            model_preset
        ):
            return False
        if not self.tmux_features_available:
            self.notify("Tmux is required to restart a Codex pane.", severity="warning")
            return False
        if not self.is_tmux_direct_enabled(agent_id):
            self.notify(
                f"Enable tmux direct mode for {agent_id} before restarting Codex.",
                severity="warning",
            )
            return False
        status = self.query_one_or_none("#tmux-status", Static)
        pane = await self.resolve_tmux_send_pane(agent_id, status=status)
        if pane is None:
            self.notify(f"No tmux pane found for {agent_id}.", severity="warning")
            return False
        agent = self.agents.get(agent_id)
        if not isinstance(agent, dict):
            self.notify(f"{agent_id} is not loaded.", severity="warning")
            return False
        if model_elevation_lease_id and model_preset is not None:
            activated = await self.activate_model_elevation_lease(
                model_elevation_lease_id,
                agent_id=agent_id,
                preset=model_preset,
            )
            if not activated:
                return False
        if self.agent_type(agent) == OPERATOR_AGENT_TYPE:
            if self.operator_role(agent) == OPERATOR_ROLE_FORK:
                restarted = await self.relaunch_operator_fork_codex(
                    agent_id,
                    pane,
                    model_preset=model_preset,
                )
            else:
                restarted = await self.relaunch_operator_root_codex(
                    agent_id,
                    pane,
                    model_preset=model_preset,
                )
        else:
            restarted = await self.relaunch_caller_codex(
                agent_id,
                pane,
                model_preset=model_preset,
            )
        if not restarted:
            if model_elevation_lease_id:
                await self.finish_model_elevation_lease(
                    model_elevation_lease_id,
                    status="failed",
                    transition={"reason": "restart_failed"},
                )
            return False
        if not await self.refresh_tmux_runtime_mapping_after_restart(
            agent_id,
            pane.pane_id,
        ):
            if model_elevation_lease_id:
                await self.finish_model_elevation_lease(
                    model_elevation_lease_id,
                    status="failed",
                    transition={"reason": "runtime_mapping_refresh_failed"},
                )
            return False
        await self.refresh_agents()
        await self.refresh_events()
        await self.load_tmux_capture(agent_id)
        return True

    async def resume_tmux_codex_in_managed_runtime(self, agent_id: str) -> bool:
        """Resume a preserved identity on the configured managed runtime server.

        Cross-server migration cannot move a live PTY.  This path therefore
        requires the source mapping to be non-ready and independently checks
        Codex's conversation lease before creating the target.  The old mapping
        remains the rollback record until the new pane is live and registered.
        """

        self.runtime_migration_error_by_agent.pop(agent_id, None)
        agent = self.agents.get(agent_id)
        if not isinstance(agent, dict):
            return self.record_runtime_migration_failure(
                agent_id,
                f"{agent_id} is not loaded.",
                severity="warning",
            )
        identity = self.tmux_runtime_server
        if not identity.ready or identity.effective_mode is not RuntimeServerMode.DEDICATED:
            return self.record_runtime_migration_failure(
                agent_id,
                "Managed cross-server resume requires a ready dedicated runtime server.",
                severity="warning",
            )
        source_mapping = await self.fetch_tmux_runtime_mapping(agent_id)
        if isinstance(source_mapping, dict) and str(source_mapping.get("state") or "") == "ready":
            if str(source_mapping.get("server_id") or "") == identity.server_id:
                return await self.restart_tmux_codex_session(agent_id)
            return self.record_runtime_migration_failure(
                agent_id,
                f"{agent_id}'s source runtime is still live; close it at a safe turn "
                "boundary before managed resume.",
                severity="warning",
            )
        metadata = self.agent_metadata(agent)
        session_id = str(
            metadata.get("fork_codex_session_id")
            or metadata.get("last_resume_codex_session_id")
            or metadata.get("codex_session_id")
            or metadata.get("codex_thread_id")
            or ""
        ).strip()
        if not session_id:
            return self.record_runtime_migration_failure(
                agent_id,
                f"{agent_id} has no Codex session to resume.",
                severity="warning",
            )
        cwd = str(
            metadata.get("work_root")
            or metadata.get("cwd")
            or metadata.get("source_cwd")
            or ""
        ).strip()
        if not cwd or not Path(cwd).is_dir():
            return self.record_runtime_migration_failure(
                agent_id,
                f"{agent_id}'s working directory is unavailable: {cwd!r}",
            )
        if not await self.ensure_codex_resume_session_available(agent_id, session_id):
            return False
        writer_lock_released = await asyncio.to_thread(
            wait_for_codex_thread_writer_lock_release,
            session_id,
            codex_home=self.codex_home_dir(),
            timeout_seconds=CODEX_SESSION_WRITER_LOCK_WAIT_SECONDS,
            stable_seconds=CODEX_SESSION_WRITER_LOCK_STABLE_SECONDS,
        )
        if not writer_lock_released:
            lock_path = codex_thread_writer_lock_path(
                session_id,
                codex_home=self.codex_home_dir(),
            )
            return self.record_runtime_migration_failure(
                agent_id,
                f"Refused to resume {agent_id}: Codex's thread-writer lease remained "
                f"active at {lock_path} after "
                f"{CODEX_SESSION_WRITER_LOCK_WAIT_SECONDS:g} seconds.",
                severity="warning",
            )

        preset = self.restart_model_preset(
            metadata,
            None,
            operator=self.agent_type(agent) == OPERATOR_AGENT_TYPE,
        )
        codex_command = self.codex_command_on_current_shell(
            str(metadata.get("codex_command") or self.operator_codex_command())
        )
        try:
            codex_command, codex_launch_path = self.resolved_codex_launch_command(
                codex_command
            )
        except RuntimeError as exc:
            return self.record_runtime_migration_failure(
                agent_id,
                f"Refused to create a managed tmux pane for {agent_id}: {exc}",
                severity="warning",
            )
        mcp_url = agent_pbx_mcp_url(self.server)
        sandbox: str | None = None
        if self.agent_type(agent) == OPERATOR_AGENT_TYPE:
            if not await self.ensure_operator_auth_ready():
                return self.record_runtime_migration_failure(
                    agent_id,
                    "Operator authentication is not ready for managed resume.",
                    severity="warning",
                )
            await self.configure_operator_codex_mcp(
                codex_command=codex_command,
                mcp_url=mcp_url,
            )
            role = self.operator_role(agent)
            if role == OPERATOR_ROLE_FORK:
                purpose = self.normalize_operator_fork_label(
                    metadata.get("fork_purpose"),
                    default=DEFAULT_OPERATOR_FORK_PURPOSE,
                )
                overrides = (
                    review_operator_config_overrides(
                        mcp_url=mcp_url,
                        codex_home=self.codex_home_dir(),
                        work_root=cwd,
                        terminal_mode=self.codex_terminal_mode,
                    )
                    if purpose == REVIEW_OPERATOR_FORK_PURPOSE
                    else operator_agent_config_overrides(
                        mcp_url=mcp_url,
                        codex_home=self.codex_home_dir(),
                        work_root=cwd,
                        terminal_mode=self.codex_terminal_mode,
                    )
                )
                if purpose == REVIEW_OPERATOR_FORK_PURPOSE:
                    sandbox = "workspace-write"
                env = self.operator_launch_env(
                    agent_id=agent_id,
                    cwd=cwd,
                    mcp_url=mcp_url,
                    model_preset=preset,
                    operator_role=OPERATOR_ROLE_FORK,
                    logical_operator_id=str(metadata.get("logical_operator_id") or agent_id),
                    source_caller_agent_id=str(metadata.get("source_caller_agent_id") or "") or None,
                    source_codex_session_id=str(metadata.get("source_codex_session_id") or "") or None,
                    fork_track_id=str(metadata.get("fork_track_id") or "") or None,
                    fork_purpose=purpose,
                    access_mode=str(metadata.get("access_mode") or "") or None,
                    source_cwd=str(metadata.get("source_cwd") or "") or None,
                    work_root=cwd,
                    review_launch_mode=str(metadata.get("review_launch_mode") or "") or None,
                )
            else:
                overrides = operator_agent_config_overrides(
                    mcp_url=mcp_url,
                    codex_home=self.codex_home_dir(),
                    work_root=cwd,
                    include_campaign_lifecycle=True,
                    terminal_mode=self.codex_terminal_mode,
                )
                env = self.operator_launch_env(
                    agent_id=agent_id,
                    cwd=cwd,
                    mcp_url=mcp_url,
                    model_preset=preset,
                )
        else:
            overrides = caller_agent_config_overrides(
                mcp_url=mcp_url,
                work_root=cwd,
                terminal_mode=self.codex_terminal_mode,
            )
            env = {
                AGENT_PBX_SERVER_URL_ENV: self.server,
                AGENT_PBX_MCP_URL_ENV: mcp_url,
                "AGENT_PBX_AGENT_ID": agent_id,
                "AGENT_PBX_REPORTING_AGENT_ID": agent_id,
                "AGENT_PBX_AGENT_TYPE": CALLER_AGENT_TYPE,
                "AGENT_PBX_AGENT_PROJECT": str(agent.get("project") or Path(cwd).name),
                "AGENT_PBX_PBX_MODE": PBX_REPORT_MODE,
                "AGENT_PBX_CWD": cwd,
            }
            if self.token:
                env[AGENT_PBX_TOKEN_ENV] = self.token
        overrides.extend(codex_model_preset_config_overrides(preset))
        env["PATH"] = codex_launch_path
        env["AGENT_PBX_RESUME_CODEX_SESSION_ID"] = session_id
        command = self.operator_resume_command(
            codex_command,
            session_id,
            cd=cwd,
            sandbox=sandbox,
            config_overrides=overrides,
        )
        safe_id = re.sub(r"[^A-Za-z0-9_.-]+", "-", agent_id).strip(".-") or "agent"
        session_name = f"agent-pbx-runtime-{safe_id}"[:240]
        runtime_kwargs = {
            "tmux_bin": identity.command_prefix[0],
            "socket_path": identity.socket_path,
        }
        pane_id = ""
        try:
            started = await asyncio.to_thread(ensure_dedicated_runtime_server, identity)
            if started:
                await asyncio.to_thread(restore_dedicated_runtime_exit_policy, identity)
        except Exception as exc:
            return self.record_runtime_migration_failure(
                agent_id,
                f"Unable to prepare the managed tmux server for {agent_id}: {exc}",
            )

        attempts = max(1, CODEX_RESTART_LAUNCH_ATTEMPTS)
        failures: list[str] = []
        mapping: dict[str, Any] | None = None
        for attempt in range(1, attempts + 1):
            pane_id = ""
            try:
                pane_id = await asyncio.to_thread(
                    tmux_support.launch_pane,
                    session_name=session_name,
                    window_name=safe_id[:120],
                    command=CODEX_MANAGED_RESUME_PLACEHOLDER_COMMAND,
                    cwd=cwd,
                    env=env,
                    width=self.detached_tmux_width,
                    height=self.detached_tmux_height,
                    **runtime_kwargs,
                )
                await asyncio.to_thread(
                    tmux_support.set_pane_remain_on_exit,
                    pane_id,
                    True,
                    **runtime_kwargs,
                )
                await asyncio.to_thread(
                    tmux_support.respawn_pane,
                    pane_id,
                    command=command,
                    cwd=cwd,
                    env=env,
                    **runtime_kwargs,
                )
                if CODEX_RESTART_STABILIZE_SECONDS > 0:
                    await asyncio.sleep(CODEX_RESTART_STABILIZE_SECONDS)
                if not await asyncio.to_thread(
                    tmux_support.pane_is_live,
                    pane_id,
                    **runtime_kwargs,
                ):
                    detail, lease_conflict = await self.retained_tmux_pane_failure(
                        pane_id,
                        **runtime_kwargs,
                    )
                    error_type = (
                        CodexSessionLeaseConflictError if lease_conflict else RuntimeError
                    )
                    raise error_type(detail)
                try:
                    captured = await asyncio.to_thread(
                        tmux_support.capture_pane,
                        pane_id,
                        lines=CODEX_MANAGED_RESUME_FAILURE_CAPTURE_LINES,
                        **runtime_kwargs,
                    )
                except Exception as exc:
                    raise RuntimeError(
                        f"unable to inspect retained target pane {pane_id}: {exc}"
                    ) from exc
                if not await asyncio.to_thread(
                    tmux_support.pane_is_live,
                    pane_id,
                    **runtime_kwargs,
                ):
                    detail, lease_conflict = await self.retained_tmux_pane_failure(
                        pane_id,
                        **runtime_kwargs,
                    )
                    error_type = (
                        CodexSessionLeaseConflictError if lease_conflict else RuntimeError
                    )
                    raise error_type(detail)
                if self.codex_session_lease_conflict_detected(captured):
                    raise CodexSessionLeaseConflictError(
                        "resumed Codex pane opened the conversation lease dialog"
                    )
                panes = await asyncio.to_thread(tmux_support.list_panes, **runtime_kwargs)
                pane = next((item for item in panes if item.pane_id == pane_id), None)
                if pane is None:
                    raise RuntimeError("resumed pane is not visible on the target runtime server")
                pane_pid = await asyncio.to_thread(
                    tmux_support.pane_root_pid,
                    pane_id,
                    **runtime_kwargs,
                )
                response = await self.api_client().post(
                    f"/v2/tmux/runtimes/{quote(agent_id, safe='')}",
                    json={
                        "server_mode": RuntimeServerMode.DEDICATED.value,
                        "socket_path": identity.socket_path,
                        "session_name": pane.session_name,
                        "window_id": pane.window_id or pane.window_index,
                        "window_name": pane.window_name,
                        "pane_id": pane.pane_id,
                        "pane_pid": pane_pid,
                        "process_start_ticks": await asyncio.to_thread(
                            runtime_process_start_ticks,
                            pane_pid,
                        ),
                        "codex_session_id": session_id,
                        "cwd": pane.cwd,
                        "metadata": {
                            "managed_by": "agent-pbx-tui",
                            "mapping_source": "managed_cross_server_resume",
                            "tmux_bin": identity.command_prefix[0],
                        },
                    },
                    headers=auth_headers(self.token),
                )
                response.raise_for_status()
                payload = response.json()
                if not isinstance(payload, dict):
                    raise RuntimeError("runtime registration returned a non-object response")
                mapping = payload
                try:
                    await asyncio.to_thread(
                        tmux_support.set_pane_remain_on_exit,
                        pane_id,
                        False,
                        **runtime_kwargs,
                    )
                except Exception as exc:
                    self.notify(
                        f"{agent_id} resumed, but {pane_id}'s diagnostic retention "
                        f"could not be disabled: {exc}",
                        severity="warning",
                    )
                break
            except Exception as exc:
                failures.append(f"attempt {attempt}: {exc}")
                if pane_id:
                    try:
                        await asyncio.to_thread(
                            tmux_support.kill_pane,
                            pane_id,
                            **runtime_kwargs,
                        )
                    except Exception as cleanup_exc:
                        failures.append(f"unable to remove attempted pane {pane_id}: {cleanup_exc}")
                        break
                retry_lease = isinstance(exc, CodexSessionLeaseConflictError)
                if (
                    retry_lease
                    and attempt < attempts
                    and CODEX_RESTART_RETRY_SECONDS > 0
                ):
                    await asyncio.sleep(CODEX_RESTART_RETRY_SECONDS)
                if retry_lease and attempt < attempts:
                    continue
                break

        if mapping is None:
            detail = "; ".join(failures[-attempts:]) or "target pane was not created"
            return self.record_runtime_migration_failure(
                agent_id,
                f"Unable to resume {agent_id} on managed tmux after "
                f"{attempt} attempt(s): {detail}",
            )

        updated_metadata = {
            **metadata,
            "tmux_pane_id": pane_id,
            "tmux_session": session_name,
            "runtime_server_id": identity.server_id,
            "runtime_server_mode": RuntimeServerMode.DEDICATED.value,
            "last_tmux_restart_at": time.time(),
            "last_tmux_restart_mode": "managed_cross_server_resume",
        }
        if preset is not None:
            updated_metadata.update(preset.metadata())
        try:
            registered = await self.api_client().post(
                "/v1/agents/register",
                json={
                    "agent_id": agent_id,
                    "project": str(agent.get("project") or "agent-pbx"),
                    "name": str(agent.get("name") or agent_id),
                    "agent_type": self.agent_type(agent),
                    "pbx_active": bool(agent.get("pbx_active", True)),
                    "metadata": updated_metadata,
                },
                headers=auth_headers(self.token),
            )
            registered.raise_for_status()
            updated = registered.json()
            if isinstance(updated, dict):
                self.agents[agent_id] = updated
            if (
                self.agent_type(agent) == OPERATOR_AGENT_TYPE
                and self.operator_role(agent) == OPERATOR_ROLE_FORK
            ):
                fork = await self.record_operator_fork(
                    logical_operator_id=str(metadata.get("logical_operator_id") or agent_id),
                    source_caller_agent_id=str(
                        metadata.get("source_caller_agent_id") or ""
                    ),
                    fork_agent_id=agent_id,
                    tmux_pane_id=pane_id,
                    metadata=updated_metadata,
                    fork_track_id=str(metadata.get("fork_track_id") or "") or None,
                    fork_purpose=str(metadata.get("fork_purpose") or "") or None,
                    access_mode=str(metadata.get("access_mode") or "") or None,
                    source_cwd=str(metadata.get("source_cwd") or cwd),
                    work_root=cwd,
                    fork_codex_session_id=session_id,
                )
                if isinstance(fork, dict):
                    self.agents[agent_id] = self.operator_fork_record_agent(fork)
        except Exception as exc:
            self.notify(
                f"{agent_id} resumed and mapped, but metadata refresh failed: {exc}",
                severity="warning",
            )
        self.tmux_runtime_mapping_by_agent[agent_id] = mapping
        self.tmux_runtime_mapping_validated_at_by_agent[agent_id] = time.monotonic()
        self.tmux_agent_targets[agent_id] = pane_id
        self.tmux_direct_agent_modes[agent_id] = True
        self.tmux_manual_override_agent_ids.add(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.save_settings()
        self.notify(f"Resumed {agent_id} on managed tmux pane {pane_id}.")
        return True

    async def resolve_tmux_send_pane(
        self,
        agent_id: str,
        *,
        status: Static | None,
    ) -> tmux_support.TmuxPane | None:
        mapping = await self.fetch_tmux_runtime_mapping(agent_id)
        registered_mapping = (
            mapping
            if isinstance(mapping, dict)
            else self.tmux_runtime_mapping_by_agent.get(agent_id)
        )
        if isinstance(registered_mapping, dict):
            state = str(registered_mapping.get("state") or "unavailable")
            if state != "ready":
                if status is not None:
                    status.update(f"Tmux: runtime mapping is {state} for {agent_id}")
                return None
            runtime_kwargs = self.runtime_tmux_command_kwargs(agent_id)
            try:
                panes = await asyncio.to_thread(
                    tmux_support.list_panes,
                    **runtime_kwargs,
                )
            except Exception as exc:
                if status is not None:
                    status.update(f"Tmux: mapped runtime unavailable ({exc})")
                return None
            pane_id = str(registered_mapping.get("pane_id") or "")
            pane = next((item for item in panes if item.pane_id == pane_id), None)
            if pane is None:
                if status is not None:
                    status.update(f"Tmux: mapped pane {pane_id or '(missing)'} is unavailable")
                return None
            if pane.session_name != str(registered_mapping.get("session_name") or ""):
                if status is not None:
                    status.update("Tmux: mapped pane belongs to another runtime session")
                return None
            self.tmux_agent_targets[agent_id] = pane.pane_id
            return pane
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception as exc:
            if status is not None:
                status.update(f"Tmux: unavailable ({exc})")
            return None
        self.tmux_panes = panes
        pane, mode = self.resolve_tmux_pane(agent_id, panes)
        if pane is None:
            if status is not None:
                if mode == "stale":
                    status.update(f"Tmux: stale target for {agent_id}")
                else:
                    status.update(f"Tmux: no pane for {agent_id}")
            return None
        return pane

    def selected_plan_option(self) -> PlanChoice | None:
        item = (
            self.thread_items.get(self.selected_thread_item_id)
            if self.selected_thread_item_id
            else None
        )
        options = self.plan_options_for_item(item)
        if self.selected_plan_option_index is None:
            return None
        if (
            self.selected_plan_option_index < 0
            or self.selected_plan_option_index >= len(options)
        ):
            return None
        return options[self.selected_plan_option_index]

    def selected_latest_plan_option(self) -> PlanChoice | None:
        report = (
            self.latest_report_by_agent.get(self.selected_agent_id)
            if self.selected_agent_id
            else None
        )
        options = self.plan_options_for_report(report)
        if self.selected_latest_plan_option_index is None:
            return None
        if (
            self.selected_latest_plan_option_index < 0
            or self.selected_latest_plan_option_index >= len(options)
        ):
            return None
        return options[self.selected_latest_plan_option_index]

    def plan_options_for_item(self, item: dict[str, Any] | None) -> list[PlanChoice]:
        if not item or item.get("kind") != "report":
            return []
        metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
        return plan_choices_from_value(metadata.get("plan_options"))

    def plan_options_for_report(self, report: dict[str, Any] | None) -> list[PlanChoice]:
        if not report:
            return []
        return plan_choices_from_value(report.get("plan_options"))

    def plan_choice_message(self, option: PlanChoice, notes: str = "") -> str:
        message = f"Selected plan option: {option.label.strip()}"
        clean_notes = notes.strip()
        if clean_notes:
            message = f"{message}\n\nOperator notes:\n{clean_notes}"
        return message

    def plan_choice_payload(self, option: PlanChoice, notes: str = "") -> dict[str, Any]:
        return {
            "message": self.plan_choice_message(option, notes),
            "plan_choice": option.payload(),
        }

    def current_thread_plan_options_for_agent(self, agent_id: str) -> list[PlanChoice]:
        if not self.selected_thread_item_id:
            return []
        item = self.thread_items.get(self.selected_thread_item_id)
        if not item:
            return []
        item_agent_id = str(item.get("agent_id") or "")
        if item_agent_id:
            if item_agent_id != agent_id:
                return []
        elif agent_id != self.selected_agent_id:
            return []
        thread = self.plan_options_for_item(item)
        return thread

    def current_plan_options_for_agent(self, agent_id: str) -> list[PlanChoice]:
        latest = self.plan_options_for_report(self.latest_report_by_agent.get(agent_id))
        thread = self.current_thread_plan_options_for_agent(agent_id)
        if self.active_agent_tab == "thread-tab" and thread:
            return thread
        return latest or thread

    def plan_option_for_selection(
        self,
        agent_id: str,
        selection: PlanSelection,
    ) -> PlanChoice | None:
        options = self.current_plan_options_for_agent(agent_id)
        selected_index = selection.index - 1
        if selected_index < 0 or selected_index >= len(options):
            return None
        return options[selected_index]

    async def send_native_plan_selection(
        self,
        agent_id: str,
        selection: PlanSelection,
        *,
        notify_missing: bool = True,
        allow_tmux_pane_fallback: bool = False,
    ) -> bool:
        label = CODEX_NATIVE_PLAN_SELECTOR_CHOICES.get(
            selection.index,
            f"option {selection.index}",
        )
        status = self.query_one_or_none("#tmux-status", Static)
        pane_id = await self.resolve_native_plan_selection_pane_id(
            agent_id,
            status=status,
            notify_missing=notify_missing and not allow_tmux_pane_fallback,
        )
        if pane_id is None:
            if not allow_tmux_pane_fallback:
                return False
            pane = await self.resolve_tmux_send_pane(agent_id, status=status)
            if pane is None:
                return False
            pane_id = pane.pane_id
        sent = await self.send_key_to_tmux_pane(
            pane_id,
            str(selection.index),
            status=status,
        )
        if not sent:
            return False
        self.tmux_plan_selector_agent_ids.discard(agent_id)
        self.tmux_plan_selector_pane_by_agent.pop(agent_id, None)
        self.tmux_plan_selector_indices_by_agent.pop(agent_id, None)
        visible_agent_id = self.tmux_agent_id_from_capture_key(self.tmux_visible_capture_key)
        if visible_agent_id and visible_agent_id != agent_id:
            self.tmux_plan_selector_agent_ids.discard(visible_agent_id)
            self.tmux_plan_selector_pane_by_agent.pop(visible_agent_id, None)
            self.tmux_plan_selector_indices_by_agent.pop(visible_agent_id, None)
        self.update_agent_title()
        self.render_agents()
        self.render_unseen_attention()
        if selection.notes:
            note_message = (
                f"Plan selection note for option {selection.index}:\n"
                f"{selection.notes}"
            )
            await asyncio.sleep(PLAN_MODE_FOLLOWUP_DELAY_SECONDS)
            note_sent = await self.send_text_to_tmux_pane(
                pane_id,
                note_message,
                status=status,
            )
            if note_sent:
                await self.record_tmux_joplin_interaction(agent_id, note_message)
            else:
                self.notify(
                    "Plan option was selected, but the trailing note could not be sent.",
                    severity="warning",
                )
        self.notify(f"Pressed {selection.index} ({label}) in Codex plan selector.")
        await asyncio.sleep(SLASH_COMMAND_FOLLOWUP_DELAY_SECONDS)
        await self.load_tmux_capture(agent_id)
        return True

    async def resolve_native_plan_selection_pane_id(
        self,
        agent_id: str,
        *,
        status: Static | None = None,
        notify_missing: bool = True,
    ) -> str | None:
        visible_pane_id = self.tmux_visible_plan_selector_pane_id()
        if visible_pane_id:
            return visible_pane_id
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception as exc:
            if status is not None:
                status.update(f"Tmux: unavailable ({exc})")
            return None
        self.tmux_panes = panes
        stored_pane_id = self.tmux_plan_selector_pane_by_agent.get(agent_id)
        if stored_pane_id:
            stored_panes = [pane for pane in panes if pane.pane_id == stored_pane_id]
            stored_matches = await self.tmux_plan_selector_matches(stored_panes)
            if stored_matches:
                pane, displayed = stored_matches[0]
                self.update_tmux_plan_selector_state(
                    agent_id,
                    displayed,
                    pane_id=pane.pane_id,
                )
                return pane.pane_id
            self.update_tmux_plan_selector_state(agent_id, "")
        pane = await self.resolve_tmux_plan_selector_pane(agent_id, panes)
        if pane is not None:
            return pane.pane_id
        selector_matches = await self.tmux_plan_selector_matches(panes)
        if len(selector_matches) == 1:
            pane, displayed = selector_matches[0]
            self.update_tmux_plan_selector_state(
                agent_id,
                displayed,
                pane_id=pane.pane_id,
            )
            return pane.pane_id
        if len(selector_matches) > 1:
            labels = ", ".join(
                f"{pane.pane_id} {pane.target_label}" for pane, _ in selector_matches[:4]
            )
            extra = len(selector_matches) - 4
            if extra > 0:
                labels = f"{labels}, +{extra}"
            self.notify(
                f"Multiple Codex plan selectors are visible in tmux: {labels}. "
                "Select the target pane first.",
                severity="warning",
            )
            return None
        if notify_missing:
            self.notify(
                "No Codex native plan selector is visible in tmux for /plan selection.",
                severity="warning",
            )
        return None

    async def send_plan_selection(
        self,
        agent_id: str,
        selection: PlanSelection,
        *,
        via_tmux: bool,
    ) -> bool:
        options = self.current_plan_options_for_agent(agent_id)
        native_pending = self.tmux_native_plan_selector_pending(agent_id)
        if via_tmux or native_pending:
            sent_native = await self.send_native_plan_selection(
                agent_id,
                selection,
                notify_missing=not options,
                allow_tmux_pane_fallback=via_tmux,
            )
            if sent_native:
                return True
            if not options or native_pending:
                return False
        option = self.plan_option_for_selection(agent_id, selection)
        if option is None:
            self.notify(
                f"Plan option {selection.index} is not available for {agent_id}.",
                severity="warning",
            )
            return False
        message = self.plan_choice_message(option, selection.notes)
        if via_tmux:
            sent = await self.send_text_to_tmux(agent_id, message)
            if not sent:
                return False
            await self.record_tmux_joplin_interaction(agent_id, message)
            self.notify(f"Sent /plan:{selection.index} reply to Codex pane for {agent_id}.")
            await self.load_tmux_capture(agent_id)
            return True
        command = await self.queue_command(
            agent_id,
            "send_input",
            self.plan_choice_payload(option, selection.notes),
        )
        self.notify_queued_command(agent_id, "Plan choice", command)
        await self.refresh_events()
        await self.load_thread(agent_id)
        return True

    async def send_plan_choice(self) -> None:
        agent_id = (
            self.selected_agent_id or self.query_one("#agent-id", Input).value.strip()
        )
        if not agent_id or self.selected_plan_option_index is None:
            self.notify("Select a plan option first.", severity="warning")
            return
        await self.send_plan_selection(
            agent_id,
            PlanSelection(index=self.selected_plan_option_index + 1),
            via_tmux=False,
        )

